/* 令和6年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r06.committeeSessions.push(...[{"id":"r06-20240515-19","meetingId":"r06-cm05","date":"2024年5月15日","dateIso":"2024-05-15","committee":"災害・環境対策特別委員会","time":"午後 １時００分～午後 ３時０２分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"気候変動適応法の改正","agenda":"気候変動適応法の改正","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"この資料のところから伺いたいのですけれども、区の対応のところで、特別警戒アラートが発表された場合は、（仮称）熱中症対策本部会議を設置するということで、この役割やどのような会議体なのかというところ、構成員、メンバーはどのような人になるのか、学識経験者などが入るのかどうかを含めて伺いたいと思います。地域センターなどは閉まっていると思うのですけれども、伺いたいと思います。","respondent":"中西環境課長","answer":"大きく３点のご質問かと思います。１つ目が、仮称ではあります、現在検討中の熱中症対策本部会議ですが、順番は前後しますが、構成員としましては、部長級の出席といったことを予定しています。","voiceIndex":5,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、区としては、その熱中症弱者を把握されているのか、何人かを把握されているかどうかというところも伺いたい。今、薬局と避暑シェルターの開設に向けて協議中ということなのですが、調剤薬局を考えると、待ちスペース、余分なスペースがあまり広くないようなイメージがあるのですが、実際、区としてはどのように利用していくという考えなのかを伺いたいと思います。","respondent":"中西環境課長","answer":"環境課として全課に網をかけまして、丁寧に対応してまいりたいと考えています。薬局です。","voiceIndex":7,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"そのような状況は、やはり込み入った対策が必要かと思うのですけれども、区としては、そこにはどのような対策をしていこうと考えていらっしゃるのかを伺います。今回、そのような熱中症の普及啓発の一つの仕組みとして、熱中症対策普及団体というものが、また一つ位置づけられているのですけれども、区としてはどのようなところがこれに当たるかという考えがあれば伺いたいと思います。","respondent":"中西環境課長","answer":"それこそ民生委員の活動の中ですとか、どのような団体があるかを把握しながら、どのような取組ができるかといったところを検討してまいりたいと考えています。","voiceIndex":9,"id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり、普及啓発を含め、そのようなところの対策も重要だと思います。寝ている間ですから、エアコンをつけていれば、そのようなことにはならないと思いますので、エアコン設置、取替えもできるように、低所得者への支援も含めてやっていただきたいと要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-004"},{"speaker":"ゆきた委員","kind":"確認","question":"６１か所の避暑シェルターの開設に当たって、１点確認させていただければと思います。もちろん、救急隊を呼ぶことが一番だと思いますが、救急隊が来るまでの応急処置としての事前準備として、アイシングのストックとか、夏場では既に氷がなくなっている場合もあるかと思われますが、傷病者が出たときの事前準備としては、どのような対策を取られているかをお聞きできればと思います。","respondent":"中西環境課長","answer":"正直、今、統一的に何かこれをということはやってはございませんが、例えば児童センターですと、アイスノンみたいなものを準備していたりと、それぞれの施設のほうで、そのようなお水以外、空調以外の部分で、様々な準備をしていると確認しています。","voiceIndex":13,"id":"exchange-005"},{"speaker":"吉田委員","kind":"質問・要望","question":"なので、高齢者に関していえば、やはりケアマネの方がそのような状況を把握しておられると思います。そこから考えると、障害者の相談支援センターの支援員は、やはりそのような障害者の方たちで、自ら水分補給や冷やすなどということができない方の情報は持っておられるので、そのような方たちとも、ぜひ連携をしていただきたいと思うのですけれども、その辺について現状はいかがでしょうか。","respondent":"中西環境課長","answer":"当然、ケアマネの方とも連携を図っておりますので、引き続き私どものほうからも声かけをしながら、そのような現場にいらっしゃるような方々の対応というところに関しても、目を向けてまいりたいと考えています。","voiceIndex":17,"id":"exchange-006"},{"speaker":"吉田委員","kind":"質問・要望","question":"そうですね。ですから、このように指定されているところ以外でも、区の施設、例えば図書館はすごくいいと思うのですけれども、そのようなところであれば、きっと休ませてくださると思うのです。既に考えておられるようだったら、申し訳ないのですけれども、その辺の現状はどのようになっているかを伺いしたいと思います。","respondent":"中西環境課長","answer":"避暑シェルターといったことに限らずではあります。例えば図書館、地域センターもそうですけれども、所管業務でない業務であったとしても、ご相談があれば、それは区の職員として適切に対応していますので、その形は引き続き続けてまいりたいと考えています。","voiceIndex":19,"id":"exchange-007"},{"speaker":"吉田委員","kind":"質問・要望","question":"ですから、そのようなことも、今度、区商連や区信連の皆さんとも、このような取組を一緒にやりましょうみたいな呼びかけも当然されていると思うのですけれども、ぜひお願いしたいと思います。多分これは前向きの答弁があると思って、要望にとどめします。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"ご説明ありがとうございました。何点か確認させていただきたいと思います。年々暑さがひどくなっている中で、このような対応がされてきていると思います。避暑シェルターが設置をされている中で、文化センターには冷水等の提供がありませんということで、ホームページに出ているのですけれども、ここに冷水等の提供がないということは、どのようなことからなのかを教えていただきたいと思います。","respondent":"中西環境課長","answer":"すみません、所管のほうに正式にヒアリングをしたわけではございませんが、設置場所はそれなりのスペースを取ってしまうといったところで、なかなかできない部分もあろうかと思いますので、今後どのような対応が取れるかといったところは検討させていただきたいと思います。","voiceIndex":23,"id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"文化センターにつきましても、できる限りの対応ができますように前向きなご検討をお願いしたいと思います。暑さ指数が３５になるという発信がされる状況が、これまではそんなにないということではありましたけれども、やはり年々暑さがひどくなっていることもありますので、そこは職員の皆様の負担にならないように。公園の暑さ対策ということでの対応が分かれば教えていただきたいと思います。","respondent":"高梨都市計画課長","answer":"よしずの設置も、一気に全ての公園にできませんので、一定の期間をもって準備を進めてまいりますので、その中でできるだけ前倒しで、早くできることができるかということを公園課とも協議しながら進めてまいれればと考えています。","voiceIndex":25,"id":"exchange-010"},{"speaker":"西村委員","kind":"質問","question":"１点お伺いさせてください。熱中症特別警戒アラートの頻度のお話が、先ほど埼玉県の事例もありましたが、お話を伺っていて、高齢者の方などにとっては外出が特に危険な状況になるぐらいであろうと思いました。","respondent":"中西環境課長","answer":"ＳＮＳ等をなかなか見ない、いわゆるデジタル・デバイドの方々への対応といったことと存じます。","voiceIndex":28,"id":"exchange-011"},{"speaker":"西村委員","kind":"質問・要望","question":"そうですね。Ｌ字で出ておりましたので、それをぜひ続けていただきたいことと、高齢者の方はそもそも外出をも控えていただきたいと思いますので、様々ご検討いただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-012"},{"speaker":"つる委員","kind":"提案","question":"これについては、昨年の自分の第２回定例会の一般質問の中で、エアコンはあるのだけれども古くて、清掃をすれば使えるのではないかというところで、クリーニングの助成をしたらどうだという提案もします。区民への対応の発信、対応の促進、庁内での施策の提案などの辺りについては、今、環境課としては、どのような考えがあるのかを教えてください。","respondent":"中西環境課長","answer":"ホームページだけではなくて、それこそ町会掲示板等に貼らせていただくというようなことも含めて、環境課のほうで各所管のほうに声をかけながら進めてまいりたいと考えています。","voiceIndex":32,"id":"exchange-013"},{"speaker":"つる委員","kind":"提案","question":"だから、そのような意味では先ほど環境課としての動きを伺ったわけですけれども、環境課として、ぜひ施策を促すような取組をやっていただきたいと思います。具体的なところでは、先ほど文化センターではないとあったわけですけれども、環境課の違う取組として、マイボトル用給水機の設置を進めていたかと思いますが、このようなところもあるわけですから、例えば文化センターでもそれを設置すればいいのです。","respondent":"中西環境課長","answer":"民間施設へのマイボトル給水機の設置助成も始めておりますので、そのようなものも積極的に打ち出しながら、まずは環境課としてできること、それから所管と調整しながら、所管のほうで対応できることについては密に連携をしてまいりたいと考えています。","voiceIndex":34,"id":"exchange-014"},{"speaker":"つる委員","kind":"質問・要望","question":"最後です。先ほど質問の中でいろいろ申し上げました、オープンの時間を少し早めるとか、当然、職員の方の時間的制約もあるのだと思うのですけれども、その辺の工夫など、この辺も全体を通して、とにかく暑さによって残念なことにならないような対応を、ぜひ積極的にやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-015"},{"speaker":"鈴木副委員長","kind":"質問","question":"緊急搬送にしても、５５％が高齢者で、亡くなる方も高齢者が多い。高齢者の方は、自分で暑さも結構感じないのです。その点伺いたい。これは、ここのところでこのような対策が取られるというところでの報告だったので伺いたいのですけれども、そのような連携だったり、どこでどのようになっていくのかということは、区のほうとしてできているのか。そのことについて伺いたいと思います。","respondent":"中西環境課長","answer":"引き続き環境課のほうもこのような形で、今、例えば本部会議の事務局をやるような形もありますので、私どものほうでも適宜提携しながら、一つ一つ進めてまいりたいと考えています。","voiceIndex":38,"id":"exchange-016"},{"speaker":"鈴木副委員長","kind":"質問・要望","question":"そのようなことの検討もぜひしていただきたいと思うのですが、その点、１点伺いたいと思います。そのようなところで、経口補水液などは、避暑シェルターには常備しておくということは必要なのではないかと思うのですけれども、避暑シェルターとしてのあるべき基準のようなものは、一定、区としても検討することが必要なのではないかと思うのですけれども、その点も伺いたいと思います。","respondent":"中西環境課長","answer":"避暑シェルターの居心地のよい在り方、基準といったところに関しましては、画一的なスペースを持っている施設全てを網羅しているわけではないので、なかなかできる部分、できない部分があろうかと思いますので、個々別々にはなるかと思いますが。","voiceIndex":40,"id":"exchange-017"},{"speaker":"鈴木副委員長","kind":"質問・要望","question":"そのような点では、これからますます気候危機の深刻な状況になっていきますので、知識の普及啓発もそうですし、対策というところでも、区としても、できれば計画をしっかりとつくってやるくらいにしたほうがいいと思いますけれども、そのようなところも含めて、区民の命を守るというところで対策を取っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-018"},{"speaker":"須貝委員","kind":"質問・要望","question":"これはテレビでも報道をしています。ですから、広報しながわは分かります。監督、代表者の方、先生方も、やはり子どもたちの顔色やしぐさなどを見て、責任を持って監督・運営しているわけですから、そこら辺は考えてほしい。行くに行けない。行くに行けないから、自宅にいなければいけないのですから、やはりそのようなことも考えて、区民に発信していただきたいと私は思うのですが、いかがでしょうか。","respondent":"中西環境課長","answer":"イベントの開催関係のお話ですが、国のほうも、それから私どものほうでも、必ず全てを中止するといったところで考えているわけではなくて、まず第１順位としては、いかに熱中症に対応できる、対策できるかといったところが最初に来て。","voiceIndex":44,"id":"exchange-019"},{"speaker":"須貝委員","kind":"質問・要望","question":"いろいろ申し上げましたけれども、やはり人の命がかかっている。そして、ご高齢者、もうどうしようもないのですから、もうお金もない、何もない。いろいろたくさん仕事があると思うのですけれども、区としてしっかりした対応していただきたいと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-020"},{"speaker":"澤田委員","kind":"質問","question":"今、皆さんから様々な質問は出尽くしているとは思うのですけれども、一つ気になったことがありまして、避暑シェルターの場所というのは、ホームページにばっと出てはいるのですけれども、マップみたいなものは、現在あるのでしょうか。教えていただけますでしょうか。","respondent":"中西環境課長","answer":"網羅したマップのようなものは、特段ご用意はなかったかと思います。今後クーリングシェルターの公表等も行ってまいりますので、場所の周知の仕方も含めて、どのような形が取れるかは検討させていただきたいと思います。","voiceIndex":47,"id":"exchange-021"},{"speaker":"澤田委員","kind":"質問","question":"現在ないということで、これからいろいろ検討されていくことかと思います。そのときにそのような方に向けてできること、お金をかけなくてもできるようなこと、例えば保冷剤をわきに挟む、鼠径部に挟むなどの案内もあったら、熱中症にかかってしまう方が少しは減るのかと思うのですが、いかがお考えでしょうか。","respondent":"中西環境課長","answer":"様々ご指摘をいただいたかと思います。どのような形で周知をしていくのか、また熱中症対策は、どのようなものがご自分にとって適しているのかと考えていただくような手法を、今後、様々少し研究させていただきたいと思います。","voiceIndex":49,"id":"exchange-022"}]},{"id":"topic-02","title":"感震ブレーカー設置補助事業の拡大","agenda":"感震ブレーカー設置補助事業の拡大","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"まさに求めてきたことなので、うれしく思います。設置費用を含めて、少し古いのですけれども、令和４年度の設置助成のパンフレットがありまして、そこにはこの分電盤型で、内蔵型だと７万円から８万円、接続型だと３万円から４万円、簡易タイプが１万５,０００円程度ということで出ていたのですけれども、この費用というのは、現在も変わらないのかどうかというところを伺いたいと思います。","respondent":"羽鳥防災体制整備担当課長","answer":"そのようなところも、今後、世論調査等で、なるべく数字を把握するように努めまして、早期に２５％にこだわることなく、なるべく多くの設置ができるように事業を進めてまいりたいと考えています。","voiceIndex":57,"id":"exchange-023"},{"speaker":"のだて委員","kind":"質問・要望","question":"分電盤型とアース付コンセント型については、分電盤のほうが安心というか、確実ということですけれども、基本的には同じということです。現在、全区的には１.２％、特区では５.１％なので、２５％までは差が結構あるという状況ですけれども、今の課題ですとか、区の取組でこのようなことを充実させていきたいということがさらにあれば伺いたいと思います。","respondent":"羽鳥防災体制整備担当課長","answer":"委員おっしゃったとおり、アース付コンセント型のＰＲを、区としてもぜひ積極的に進めてまいりたいと考えています。","voiceIndex":59,"id":"exchange-024"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"この点についてお聞きできればと思います。もう１点ですが、（３）の補助率・額の拡大について記載されていますが、感震ブレーカーの設置推進事業補助金交付要綱の改正では、記載のない分電盤型の新築住宅についてはどうなるのか。（３）1)分電盤型の一般世帯に組み込まれているのか、教えていただきたいと思います。","respondent":"羽鳥防災体制整備担当課長","answer":"ですので、特に今回記載させていただいてはおりませんが、今年度からは特にその枠は設けず、今回書かせていただいた４つの枠で進めていきたいと考えています。","voiceIndex":62,"id":"exchange-025"},{"speaker":"ゆきた委員","kind":"質問","question":"新築であっても、分電盤型は一般世帯の中に入るという認識でよろしいでしょうか。広報の工夫については、より一層の工夫を考慮していただければと思います。","respondent":"羽鳥防災体制整備担当課長","answer":"新築のところです。新築時に同時に補助するというところがなくなるだけですので、設置されている分電盤に対する補助というのは、今までどおり残ります。ですので、通常の既存の補助で対応できるです。","voiceIndex":64,"id":"exchange-026"},{"speaker":"吉田委員","kind":"質問・要望","question":"そのようなためにも、そんなに工事の金額の負担だけではなくて、その手間の負担もないということが分かると、申請される方が増えるのではないかと思うのですが、その点について、恥ずかしながら、認識を改めさせていただきたいのですけれども、いかがでしょうか。","respondent":"羽鳥防災体制整備担当課長","answer":"正式にお申込みいただくという流れにはなってあります。工事の期間に関しましては、特に決められたものはないのですけれども、そんなに時間はかからない、１週間もかからないでできると認識しています。","voiceIndex":67,"id":"exchange-027"},{"speaker":"吉田委員","kind":"質問・要望","question":"そのような情報はとても大事だと思うのです。申請してみないと、その辺の情報が得られないということは、私の感覚でいうと、遅いと思うので、ぜひ事前のこのような制度のご案内のときに、なるべくこれぐらいの負担で済みますからというような表現がいいかと思うのですけれども、ぜひ検討していただきたい。すみません、もう一度、その辺、ぜひお願いしたいのですが、いかがでしょうか。","respondent":"羽鳥防災体制整備担当課長","answer":"ただ、どのぐらいの期間がかかるのかというところは、特に記載がなかったので、そこは検討させていただきたいと思います。","voiceIndex":69,"id":"exchange-028"},{"speaker":"吉田委員","kind":"提案","question":"たとえ時間と手間がかかっても、これはやるべきだと私も思うのです。提案が出せなくて、ごめんなさい。そのような促しの広報をこれからもぜひ進めていただきたいと思います。これは要望です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":71,"id":"exchange-029"},{"speaker":"須貝委員","kind":"質問・要望","question":"これだけ様々な事業をやっているのですが、普及啓発にいい方法を考えていただいて、多くの区民の方が早く認知していただけるように努力をしていただきたいと私は思います。今、マンション等、各家庭もオートロックを非常に多く使っている中で、ドアの開錠や開閉装置が機能しなくなって、出入りができなくなるということも、そのような注意も併せて、皆さんに伝えてほしい、普及啓発してほしい。","respondent":"羽鳥防災体制整備担当課長","answer":"人工呼吸器をご利用の方に関しましては、東京都が無償配布しているような特定機器遮断型というものがありますので、そのようなものを活用しながら、一括で遮断されないような対応も取ることがありますので。","voiceIndex":73,"id":"exchange-030"},{"speaker":"須貝委員","kind":"質問・要望","question":"ご答弁はいいですけれども、そのようなところも注意喚起をしていただきたいと思います。今、区ではできるだけやっているという話ですが、できれば、広報しながわで、６万数千件ではなくて、やはり１０万件、２０万件単位で区民にできるだけ知らせるような方法を区も持っているのですけれども、できるだけこのようないいことは、予算を使って知らしめる、教えてあげていただきたいと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-031"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"数点お伺いしたいと思います。補助率のところは、上がったので、すごくよかったと思います。例えば高齢者が手すりをつけるようなリフォームの際に、申請は、多分、住宅課なり、建築課なりにいろいろと申請されると思うのですけれども、ついでにこの工事もやりませんかというように、先ほど吉田委員が話していた受入れ側の手間というのですか、どうせなら一緒にやってくださいと。よろしくお願いします。","respondent":"羽鳥防災体制整備担当課長","answer":"今後、動向を見て、さらなる拡充というところは検討を進めてまいりたいと考えています。他課とも連携して、周知できないかですけれども、委員おっしゃるとおり、他課とも連携して、しっかりやってまいりたいと考えています。","voiceIndex":77,"id":"exchange-032"},{"speaker":"つる委員","kind":"確認","question":"新築のところで、先ほど質疑がありました。改めて確認なのですけれども、要綱を見ると、注文住宅の設計などを進めていって、施工業者に施主が委任をして申請する、補助金を受けるということは、交付要綱に書いてある。要はハウスメーカーや工務店が施主に代わって、区に申請をするという流れでいいのですか。そこを教えてください。","respondent":"羽鳥防災体制整備担当課長","answer":"委員おっしゃるとおりです。","voiceIndex":80,"id":"exchange-033"},{"speaker":"つる委員","kind":"質問","question":"それは、まさに注文住宅の新築なので、これからつくり上げていくということなのですけれども、新築であっても、もう既に既設になっている。建て売りです。建て売りでそれがついている新築ですという場合は、これはもうどうしようもないのですか。そこは対象にすることは、もうなかなか難しいということですか。","respondent":"羽鳥防災体制整備担当課長","answer":"委員おっしゃるとおり、建て売りの場合は、やはり難しい部分があります。そのようなところもあって、なかなか分かりづらい部分もあって、平成２８年度から実績も１件という形になっていたということがあります。","voiceIndex":82,"id":"exchange-034"},{"speaker":"のだて委員","kind":"確認","question":"その辺りも伺いたい。通信状況を確認するということなので、それがどこで行われるのかということ、この訓練には区の職員の参加はあるのか、どうか。国が今やっている国家安全保障戦略があると思うのですけれども、この自治体の協力を得ていくという感じだと思っているのですが、そことの関係というのは、今回の訓練とはあるのかどうかということも伺いたいと思います。","respondent":"伊藤災害対策担当課長","answer":"今のところ住民への説明は予定してございませんが、後ほど庁内に同じような形で本情報を共有させていただきまして、庁舎内に一般の方が来訪された際も答えられるようにＱ＆Ａのようなものを併せて添付をさせていただきまして。","voiceIndex":89,"id":"exchange-035"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、住民への説明は想定していないということなのですけれども、やはり住民の方も驚くのではないかと思うので、そこは、ぜひ説明もするように検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-036"}]},{"id":"topic-03","title":"特定事件調査のまとめ","agenda":"特定事件調査のまとめ","exchanges":[{"speaker":"つる委員","kind":"質問","question":"これは、てにをはも含めても、これで了という感じになりますか。であれば、もしかすると、私がこの表現に理解がないのかどうかは分からないのですけれども、防災に関することのほうで７行目のところの「避難行動要支者支援」となっているのですけれども、委員長、これはそのような表現ですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":95,"id":"exchange-037"},{"speaker":"つる委員","kind":"質問","question":"私が質問しているのですから、委員長がきちんとそれをどうするかということを仕切ってまとめください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":97,"id":"exchange-038"},{"speaker":"鈴木副委員長","kind":"意見","question":"どうも１年間、ありがとうございました。お疲れさまでした。理事者の皆様はもういらっしゃらないので、理事者の方には、正副委員長との打ち合わせのときにお礼を言っておきました。事務局の方々には、本当にきめ細やかなご配慮をいただきまして、１年間本当にお世話になりました。ありがとうございました。本当に１年間お世話になりまして、ありがとうございました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":102,"id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6713#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":37495,"voices":103}},{"id":"r06-20240516-10","meetingId":"r06-cm05","date":"2024年5月16日","dateIso":"2024-05-16","committee":"議会運営委員会","time":"午後 １時００分～午後 １時３７分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を10件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"常任・議運・特別委員会の構成","agenda":"常任・議運・特別委員会の構成","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"お示しいただいた案なのですけれども、案ということで今見ているわけですが、共産党としては、文教委員会を希望したいと思っていまして、今お示しされている文教に振り分けられている皆さん、会派とかがあると思うのですけれども、次回の２２日までに少し希望なども伺って、もし先方が、いいですよと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"次回、２２日にあるので、さらに本会議の前に議運があるので、仮の決定としてはいいかもしれないですが、仮に文教委員会に所属されている自民党、公明党、未来、維新、無所属の中で、それでしたら交換してもいいですよというところがあれば、次回にそういったことも含めて確認していただきたいと思っていますので、ぜひお願いしたいのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"２２日に議会運営委員会が入っているので、私は言っているのです。次回が２２日。ですから、私は、交渉というか、相手があることなので、応じてくれるとは限らないし、難しいとは思っていますけれども、私たちとしては、文教委員会にもやはり委員を希望しているということもあるので、できれば、ぎりぎりまでそういった努力はしていきたいと思う。ですから、私たちはそのように言っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"ほかの会派、要は各会派構成でいろいろ皆さん考えられて、つくっていることです。ですから、委員会をその中で変えるというのは、なかなかここで即決などというのは難しいし、また時間もかかってしまうので、それだったら、無所属の方には恐縮ですけれども、枠を、無所属の方を１つ区民委員会と交換してもらってやれば、何ら問題はない。今日皆さんの意見が一致すれば。駄目ですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"区民委員会のところと替わってもいいですよという方がもしいれば、そうしたら、そのとき改めて次回にそのことも含めて報告をして決定すればいいのではないですかということなのです。もちろんこの場で、文教委員会に、こちらに入れてくださいということを言ってもいいのですけれども、委員長案を尊重しているというか、丁寧に言っているのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-005"},{"speaker":"須貝委員","kind":"質問","question":"ご自分の希望を言って、無所属の方は様々な方がいらっしゃるのだから、例えば、文教が減って区民に移ったとか、どのようにするのか、構成をまたシャッフルするのは、数からいうと難しい点はあるのですけれども、一応、そういう方向で考えられたらいいのではないですか。これ、数が増えると、逆に難しくなるのかな。","respondent":"高橋（伸）委員長","answer":"ついては、各会派からもいろいろ、各会派によってそれぞれ主張があると思いますけれども、今おっしゃられている安藤委員のことも一定のことは分かりますが、全体のバランスを考えてこういう案を示させてもらいましたので、これで本日決めたいと思いますけれども、ほかに皆さん。","voiceIndex":23,"id":"exchange-006"},{"speaker":"せりざわ委員","kind":"意見","question":"今、共産党からもいろいろお話があって、主張としては主張されていいのだと思うのですけれども、入りたい委員会があって、抜けたい委員会があってというのがあって、今、委員長からもバランスを見てというお話をいただいているので、そもそも私たちとしてはこの案のとおりで結構ですし、スケジュールのところも、なかなか自分たちの思うようにいかないから丁寧にというのは少しむちゃなのかと思っているので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":25,"id":"exchange-007"},{"speaker":"安藤委員","kind":"提案","question":"案として出されて、議運の場に私たちはいるので、私たちの会派の希望を伝えたということなのです。できればそのようにしてもらえればということで提案させていただいたものですので、そこはご理解いただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":29,"id":"exchange-008"}]},{"id":"topic-02","title":"公益財団法人議会選出評議員の推薦","agenda":"公益財団法人議会選出評議員の推薦","exchanges":[{"speaker":"安藤委員","kind":"意見","question":"割り振りについてご説明があったのですが、端的に、去年と比べて共産党は１人減っているので、あれなのですが、今年、スポーツ協会のほうが前回あったのが、逆でしたね。すみません。前回なかったのが、今回。ごめんなさい。勘違いでした。失礼いたしました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":48,"id":"exchange-009"}]},{"id":"topic-03","title":"ＩＣＴ推進会議からの報告事項","agenda":"ＩＣＴ推進会議からの報告事項","exchanges":[{"speaker":"せりざわ委員","kind":"質問・要望","question":"資料No.１６をご確認ください。本日、この議会運営委員会の場において確認できましたら、６月の第２回定例会から適用したいと考えております。こちらについては、資料No.１８をご確認いただきまして、タブレット端末等の使用基準の中に、「クラウド文書共有システムへのデータ格納期間」の項目を追加させていただきたいと思います。以上、２点についてご確認のほどよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-010"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6715#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":12466,"voices":71}},{"id":"r06-20240522-10","meetingId":"r06-cm05","date":"2024年5月22日","dateIso":"2024-05-22","committee":"議会運営委員会","time":"午後 １時００分～午後 １時０６分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6743#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":2791,"voices":14}},{"id":"r06-20240524-10","meetingId":"r06-cm05","date":"2024年5月24日","dateIso":"2024-05-24","committee":"議会運営委員会","time":"午前１０時３０分～午前１０時４９分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を4件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和６年第２回臨時会","agenda":"令和６年第２回臨時会","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"両方とも反対します。理由を述べしますが、２０２２年の臨時会でも同様に、第１会派の自民と第２会派の公明からの選出案が出され、同じ態度を共産党としては取りました。したがいまして、今回の選任同意の提案ですが、正副で相談して決められた提案だと思いますけれども、監査委員は第一、第三会派からセットで選任すべきだと考えますので、どちらの案にも反対したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":10,"id":"exchange-001"},{"speaker":"須貝委員","kind":"意見","question":"監査委員の選任同意については賛成します。ただ、今、国会でも様々な問題が起きていますように、やっぱり国民や区民の目が大変厳しくなっていると私は思います。それから、報酬ですが、これは区議会議員報酬と監査委員の報酬、ダブルで今、出ているわけですが、こういうことに対しても品川区議会はそろそろ改革をする時期に来たんじゃないかなというふうに申し上げておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":11,"id":"exchange-002"}]},{"id":"topic-02","title":"正副委員長の互選","agenda":"正副委員長の互選","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"臨時委員長をいつも仰せつかっているんですが、私が担当する委員会でいつも私が独占していると。そういうのじゃなくて、やっぱり交代で、そろそろそういう時期が来たんじゃないかと。風当たりも強いように、自分で勝手に考えています。何かご検討いただければありがたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":17,"id":"exchange-003"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"若林副委員長","kind":"意見","question":"１年間、大変にお疲れさまでございました。改選後、初めての議会運営委員会ということで、議員辞職勧告決議案等々、難問がありましたけれども、皆様のご協力のおかげをもちまして、比較的円滑に進められたと思います。委員長を中心に皆さん大変にお疲れさまでございました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":44,"id":"exchange-004"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6717#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":6927,"voices":45}},{"id":"r06-20240610-6","meetingId":"r06-cm06","date":"2024年6月10日","dateIso":"2024-06-10","committee":"区民委員会","time":"午後 １時００分～午後 ３時０４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を25件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"それで、「区政の現況についての情報提供を適宜的確に行い」というところは理解できるのですけれども、その後の、「区政を効率的に推進するため」に置くというのがよく分からないのですけれども、区政を効率的に推進するというのはどういう意味なのか伺いたいのと、あと委嘱とあるのですけれども、委嘱を受けない方というのは、町会長や自治会長は１００％受けて。","respondent":"宮澤地域活動課長、築山戸籍住民課長、小林地域産業振興課長","answer":"併せて委嘱ですけれども、皆様、委嘱して、１００％という形です。不安な声があるですけれども、保険証への対応は、所管が国保医療年金課となります。我々のほうで、いろいろ我々のやっている施策や現状報告ということを、この委員会でもやってきておりますけれども。","voiceIndex":33,"id":"exchange-001","title":"町会・自治会支援"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後のところは、やはりどんな対策や議論も現状を把握することから始まると思いますので、今ご答弁いただきましたけれども、ぜひ委員長のほうでも、区民委員会の運営に当たりまして、ぜひ積極的に取り入れていただきたいという、これは委員長への要望です。それと、マイナンバーのマイナ保険証は、ではいろいろ、今までは自宅にいたら全ての方に郵送されてきた。それだけ確認をお願いします。","respondent":"築山戸籍住民課長","answer":"そのとおりです。","voiceIndex":37,"id":"exchange-002"},{"speaker":"おぎの委員","kind":"質問","question":"私から１点だけ、町会に補助金を出しているところで、こちらのページで言うと１５ページから１７ページのあたりになると思うのですけれども、令和５年度の交付額の実績が出ているのですけれども、こういった実績の実際の内訳といいますか、どこの町会にどういったものが出ているなどというのは、ホームページ等で見られたりするのでしょうか。","respondent":"宮澤地域活動課長","answer":"町会・自治会から様々な事業や物品の購入等で、細かい申請を頂いておりますが、ホームページ等で個別具体的な町会・自治会名というのは公表していません。","voiceIndex":40,"id":"exchange-003"},{"speaker":"おぎの委員","kind":"質問","question":"実は先週末も、あちこちの区内町会でお祭り等がありまして、ちょうどお話をお伺いしたところ、やはり町会の参加人数が年々減ってきていると。","respondent":"宮澤地域活動課長","answer":"品川区町会自治会連合会のホームページ等でもイベント情報の取組などをアップしております。この４月の町会長・自治会長会議でも、各地区、説明して回っておりますけれども、引き続き丁寧な説明は続けていきます。","voiceIndex":42,"id":"exchange-004"},{"speaker":"藤原委員","kind":"質問・要望","question":"ですから、その辺をもう一回考えていただきたいのと、それができないのであるならば、防犯カメラをつけた町会等においても、たしか１回か２回ぐらいしか、「ここには防犯カメラがありますよ」ステッカー・シールを配られていないのです。そこをきちんとしていただきたいと思うのですけれども、いかがですか。八潮。事務事業概要なので大きい意味で全部伺いますが、その辺について教えてください。","respondent":"河合生活安全担当課長、今井八潮まちづくり担当課長、栗原創業・スタートアップ支援担当課長","answer":"防犯カメラ設置のステッカーについての助成ですけれども、基本、防犯カメラの補助につきましては、ステッカーを表示、出すことが条件となっておりますので。今年度以降は、そのイメージを皆さんの中でさらに具体的なものに整えていくといったところで、これまでどおり、みらい懇談会も開催しつつ。そういったところで、小さい子や女性など多種多様な方がチャレンジしやすいといった、品川区に来るといろいろなことにチャレンジできるということで。","voiceIndex":46,"id":"exchange-005"},{"speaker":"藤原委員","kind":"質問・要望","question":"課長、スタートアップをしっかり押さえていただいていて、委員会が今日から始まるわけですけれども、私はすごく安心しました。しっかり押さえていますね。それとも、一番最初に防犯カメラを設置したときに入っているから、一回シールもその中に入っているから駄目ですよということなのですか。言っている意味は分かりますよね。あのステッカーはどういうふうにすればいいのでしょうか。","respondent":"河合生活安全担当課長","answer":"なので、最初だけ助成して終わりではなく、維持管理のほうも助成金がありますので、そういったところの対応という形になります。","voiceIndex":50,"id":"exchange-006"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"今までの私たちの質問をもし覚えていてくださっていたらあれなのですけれども、結構、使用指導で、生活安全担当と教育委員会と認識が違ったりすることがあって混乱することがあって、連携はとても大切だし、ここはぜひ連携していただかないと困るのですけれども、私の感覚から言うと連携がうまくいっていないのではないかというのがあったので、なぜ「運営費」と、ここだけ費用の話になっているのか。","respondent":"河合生活安全担当課長","answer":"連携のところで教育委員会との連携というのは、運営しているときに、情報共有なども含めて、学校に対する連絡とか、そういうのは教育委員会を経由して行うこともありますので、事業全体の情報共有というところで、教育委員会と連携しているという形になります。","voiceIndex":53,"id":"exchange-007"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"単に名目というか、それが「費」となっているので、ここにだけ「費」がついているということですね。分かりました。連携はぜひしていただきたいのですが、若干、今まで具体的な連携の中で混乱が見られたので、混乱していると思ったことがあったので、その辺を確認させていただきました。それからもう一つ、ごめんなさい。それも確認させてください。","respondent":"宮澤地域活動課長","answer":"そこを所管している福祉計画課と連携しておりまして、支え愛活動というのは地域センターが事務局となって、地域の皆さんと一緒に活動しています。ただ、その活動の中で福祉計画課とも連携しているということです。","voiceIndex":55,"id":"exchange-008"},{"speaker":"安藤委員","kind":"確認","question":"まとめて、文化観光戦略課のほうですけれども、資料に基づいて言いますと２２ページなのですが、（４）羽田空港周辺エリア連携事業とありますが、羽田空港周辺の自治体と連携し、海外に向けた観光ＰＲを行うとありますけれども、ここでＰＲの中に、確認ですけれども、今、上空を新ルートで通っているではないですか。","respondent":"三井スポーツ推進課長、大森文化観光戦略課長","answer":"デフスポーツ啓発事業のほうで、当事者参加も大事だというところでお話しいただきましたが、啓発イベント等を実施する上で、障害者支援課とも連携しまして、品川区の聴覚障害者協会といった協会の会長などにも話を聞きながら。委員のご質問、羽田空港周辺エリア連携事業の中での羽田新ルートの周知といったことですが、そういったことはしておりません。","voiceIndex":66,"id":"exchange-009"},{"speaker":"安藤委員","kind":"意見","question":"スポーツのそもそもの振興目的については、推進計画があるということで、そこに書いているということだと思いますけれども、みんなの笑顔がという話もありましたが、やはりスポーツを通して幸福で豊かな生活を営むということが全ての人々の権利であるというスポーツ基本法や、あるいはスポーツの国際憲章、基本的人権であるといったところもすごく大事なところだと思いますので、そこを第一にというか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":69,"id":"exchange-010"},{"speaker":"せお委員","kind":"確認","question":"最初に気になったのですけれども、スポーツ推進課で、少年少女スポーツ担当の職員が１名なのですけれども、昨年も見させていただいたら１名で、これは、内容を見ると結構、量があると思ったのですけれども、１名で運営できているのか、それだけ確認させていただければ。","respondent":"三井スポーツ推進課長","answer":"少年少女スポーツ担当はスポーツ振興担当の係長が兼務でやっているところでございまして、実際の業務内容・事務分担は、スポーツ推進課全体で事務分担を考えながら進行しているので、事務作業などは１人でしているわけではないというところになります。","voiceIndex":71,"id":"exchange-011"},{"speaker":"せお委員","kind":"質問・要望","question":"もう一点、これも確認ですけれども、例えば主に文化観光戦略課のところで、区民プロデュース型講座などが主にだと思うのですけれども、こういう講座や講演会は、今は結構、オンラインで可能なものとか、可能であれば、そういったのをやっている方というか、区民プロデュース型でやっているなどではなくて、一般的にそういうのも多いと思うのですけれども、そういったものも同じ助成でできるのか。","respondent":"大森文化観光戦略課長","answer":"応募には必ず対面式でという規定はございませんので、オンラインでの講座というところでの申込みがあれば、当然そこは乗ってくるという形での認識で結構です。","voiceIndex":73,"id":"exchange-012","title":"町会・自治会支援"},{"speaker":"藤原委員","kind":"質問・要望","question":"大きく聞きます。去年、前年度までは文化観光課でしたよね。今回、文化観光戦略課になりましたけれども、何で「戦略」をつけたのですか。それと、戦略の先には何を求めているというか、何が目標なのですか。戦略とは、どうするつもりですか。以上です。","respondent":"大森文化観光戦略課長","answer":"その先におきましては、区内に観光等、文化等で区外からの誘致をすることによる、区内の経済を上げていくといったところにつながればと考えています。","voiceIndex":77,"id":"exchange-013"},{"speaker":"吉田副委員長","kind":"確認","question":"すみません。手話通訳者の手配なども必要だと思います。実務的にも、やはり障害者支援課との連携はどうしても必須かと思いますので、それは連携されるという理解でよろしいのですねという、ここに表記がないので確認させてください。","respondent":"三井スポーツ推進課長","answer":"デフリンピックにつきましては、障害者支援課と一緒に、それぞれ予算はついているのですが、こちらとしても、もちろん、例えば聴覚障害の方と会議するに当たっても手話通訳が絶対必要ですし、それは障害者支援課の予算で取っている手話通訳の予算を使って。","voiceIndex":80,"id":"exchange-014"},{"speaker":"おぎの委員","kind":"質問","question":"私からも１点だけ、少し細かくなってしまうかもしれないのですが、しながわ学びの杜のシルバー大学の、学びの項目についてですが、幾つになっても学ぶというのは、すごく生きがいが持てていいと思うのですけれども、非常に多彩な各種学びの科目というのでしょうか、ありますけれども、これはいつ誰が決めているのでしょうか。","respondent":"大森文化観光戦略課長","answer":"これはもう体系的に、シルバー大学１年生から３年生という３年間のカテゴリーになりまして、３年生の中で経験を活かして、講師や、講演内容の助言を頂いたり、生涯学習係の職員のほうでいろいろなものをネット等で調べて、いろいろな講座の内容を決めているところです。","voiceIndex":83,"id":"exchange-015"},{"speaker":"おぎの委員","kind":"意見","question":"見ると、毎年開催されているような根強い人気のものもあれば、時代に即したものもあるのかなと思いますので、区民のニーズを拾って、また皆さんの楽しみとなる科目・講座ができるといいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":85,"id":"exchange-016"}]},{"id":"topic-02","title":"しながわシティランの開催に向けた進捗","agenda":"しながわシティランの開催に向けた進捗","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"資料の分からないところで、４番のコンテンツパートナーというのは具体的にはどういうことをするのかを教えてください。もし、さらに次回の委員会などで、そういうところが深まれば、微修正などもあり得るのか、その点をお聞かせください。","respondent":"三井スポーツ推進課長","answer":"本当は、警察と話すと、交通規制のことを考えると早ければ早いほどいい。ただ、そうはいっても参加できないので、そういったバランスを考えながら、ぎりぎりのところで９時スタートと決めているところです。","voiceIndex":90,"id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"今回やってみて、やりながら、徐々に地域の拡大など、いろいろな試みを重ねながらやっていくとは思うのです。なので、先ほどお伝えしたような意見というのは、結構、走る愛好家の方から、そういう話も出ているので、そういった方々の声もできる限り取り入れながら、みんなに愛されるような大会にしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":92,"id":"exchange-018"},{"speaker":"石田（し）委員","kind":"質問","question":"１点だけ、協賛のところですけれども、これはスポーツの枠を超えて地域全体で取り組んでいくのだろうと思っていて、そのような中で、協賛企業に関して、地域産業振興課ではどういう対応をして、スポーツ推進課とどういう連携をして、地域を盛り上げようとしているのか教えてください。","respondent":"小林地域産業振興課長","answer":"しながわシティランの開催に当たりましては、協賛というところは大事なところでございまして、例えばですけれども、東京商工会議所の会員企業というのは区内でたくさんいるわけですけれども、そういうところに区長あるいは副区長から直接出向いて。","voiceIndex":94,"id":"exchange-019"},{"speaker":"石田（し）委員","kind":"質問","question":"ぜひ、せっかく、こういったものを催すので、いろいろな人たちを巻き込んで、先ほどスタートアップのほうも、せっかくだったら、あちらは通らないけれども、五反田バレーに応援してもらえるような。せっかく同じ机にいるのですから、連携してください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-020"},{"speaker":"ゆきた委員","kind":"質問","question":"そこで、しながわシティランでの心停止に対する救護体制と、また、それ以外の医療体制についての計画というのはどのようになっているのかというところで、先ほど消防と警察との調整が６月下旬ということであったので、この辺で救護所の設定などといった計画もされていくのかというところを、詳しく決まっていればお聞きできればと思います。","respondent":"三井スポーツ推進課長","answer":"そのスタッフがＡＥＤ等を持ちながら、実際の当日の大会、心停止等の対応もできるようにと考えているところですが、今後、今年度にかけて、救護の実際のマニュアル等は、医師会等と相談しながら、計画を進めていきたいと考えております。","voiceIndex":97,"id":"exchange-021"},{"speaker":"ゆきた委員","kind":"意見","question":"東京マラソンでは、距離も規模も違いますが、モバイルＡＥＤ隊やＢＬＳ隊などが参加されて、救護スタッフも、消防と救護所にも救急隊員が待機していたりもしているので、今お話があったとおりですけれども、さらなる救護体制の徹底をしていただければと思いますので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":99,"id":"exchange-022"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"いろいろ議論にはなっているかと思うのですけれども、できるだけ、いや、そういう日になってしまうと、みんなやらざるを得ないので、行くしかないと思うのですけれども、事前に、むちゃな危険な暑さのときに日程が入らないようにアドバイスというか、品川区から実行委員会などにサジェスチョンしてあげたほうがいいのではないかと思うのですけれども、それについては、今年は何か工夫があったのか。","respondent":"宮澤地域活動課長","answer":"熱中症の対策のところで、前年度、実施が終わりまして、今年度に向けてという中で、各地区実行委員会で議論は当然しております。","voiceIndex":104,"id":"exchange-023"},{"speaker":"安藤委員","kind":"意見","question":"去年は大変な状況だったので、恐らく少しずつ改善はされていると思うのですけれども、それでもなかなか限界はあると思いますので、さらなるアドバイスや支援などをお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":106,"id":"exchange-024"},{"speaker":"安藤委員","kind":"意見","question":"歴史的な物価高が続いておりまして、電気料金が上がるということで、本当に区内の経済、中小企業は大変だと思いますので、具体的にはちょっとあれですけれども、やはり区内中小企業の支援策については、今年度、力を入れて調査する必要があると思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":109,"id":"exchange-025"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6725#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":40297,"voices":110}},{"id":"r06-20240610-7","meetingId":"r06-cm06","date":"2024年6月10日","dateIso":"2024-06-10","committee":"厚生委員会","time":"午後 １時００分～午後 ２時４１分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"筒井委員","kind":"意見","question":"品川改革連合の筒井ようすけです。どうぞよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":8,"id":"exchange-001"}]},{"id":"topic-02","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"体制のところでは、もう１つの健康推進部のほうで、保健師の数が、２３区の平均からも、人口対比で少ないというところをずっと、これを増やすことが必要なのではないかということで議会の中で何回も取り上げてきたところなのですけれども、この保健師の数が、昨年度は、トータルで全ての健康課から国保医療年金課まで合わせて、昨年のところでは４８名だったのが、今年度は４９名ということで。","respondent":"松山障害者支援課長、菅野高齢者福祉課長、豊嶋生活福祉課長、若生健康課長","answer":"私から、障害者支援課の会計年度任用職員について、ご説明申し上げます。資格としては、ほとんどの方が社会福祉士の資格をお持ちです。資格としては、社会福祉士の資格を持っている方が多いと認識しております。生活福祉課も同様に社会福祉士の方が３１名の中の大多数を占めております。一方、採用も人事課のほうで毎年度強化をしていただいているところでして、一定数、採用活動を図っているところなのですが、やはり年々。","voiceIndex":44,"id":"exchange-002"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それなので、この点については、人材確保をどうしていくかというふうなところは、看護協会とかでもガイドラインみたいなものを出していたりしまして、戦略を持ってやっていくということが必要なのではないかということも出したりしていますので、そういうものも含めて、保健師は２３区でも最低レベルという、それを改善をさせて、現場でも、本当に生きがいを持って働けるような。","respondent":"遠藤健康推進部次長、五十嵐保健予防課長、若生健康課長、東野福祉計画課長","answer":"そのほかになのですけれども、災害時医療だとか、健康危機管理の場合のバックアップだとか、そういう部分を私どものほうでやらせていただくのですが。先ほどもご説明させていただきましたが、今年度、自殺対策計画の中間見直しを行う予定になっておりますので、そちらを実施します。健康プラン２１のほかに、がん対策推進計画も今年度改定をします。福祉部は、昨年度、３計画を改定しましたので、大きな改定をするような計画はございません。","voiceIndex":49,"id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ありがとうございました。４億４,６４０万円の予算が組まれているわけですけれども、これがいつから実施されるのか、あと、対象がどこまでなのかとかという詳しい中身については、厚生委員会にぜひとも報告していただきたいと思うのですけれども、いつ頃、報告をしていただけるものなのか、その点についても伺えたらと思います。","respondent":"菅野高齢者福祉課長","answer":"区は、もちろんそれとは別に、独自にこの手当は支給するのですけれども、事業者、現場が混乱しないように、東京都のスキームも見ながら、うちのスキームを最終的には構築しようというふうに見ておりましたので、東京都のほうが出たというところで、それを踏まえて、今。","voiceIndex":54,"id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問・要望","question":"おおよそ、例えば７月からとか、８月からとか、そういうことは、なかなかまだ分からないということでしょうか。そういうものが固まった時点では、ぜひとも厚生委員会に、こういうふうな中身でやりますよということはご報告をいただきたいと思うのですけれども、そのところの確認もさせていただけたらと思います。もう１つ、続けて伺います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":56,"id":"exchange-005"},{"speaker":"やなぎさわ委員","kind":"確認","question":"確認なのですけれども、福祉部のほうの事務事業概要の超短時間雇用促進事業に関してですけれども、これ、社会福祉法人げんきの企画で、「みっけ」という事業が始まっていると思うのですが、これは森澤区長も非常に力を入れておられて、品川区から超短時間雇用を全国に広めるという意気込みで、私も非常に期待をしていますけれども、現状の実績というか、もしお分かりになれば、教えていただければと思います。","respondent":"松山障害者支援課長","answer":"超短時間雇用についての実績ですけれども、昨年度、モデル実施をいたしまして、区内の事業所としては２件成立して、今現在、おっしゃられたように、就労支援センターに超短時間総合窓口という、「みっけ」という愛称をつけまして。","voiceIndex":61,"id":"exchange-006"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"別件になりまして、これも福祉部のほうなのですけれども、在宅介護支援事業のところのケアラー懇談会、６０ページのところで、ケアラー懇談会の実施ですけれども、ケアラー懇談会、実績で８回、昨年度開催されていると思うのですけれども、開催が基本的に平日の日中の対面というふうに記憶しているのですけれども、その辺の８回の内訳というか、もし分かれば教えていただきたい。","respondent":"菅野高齢者福祉課長","answer":"以前は在宅介護者のつどいと言って、１００人とか、１５０人規模で、もっとたくさんの人を集めた、そこで会食をしたりとか、労うとか、そういった会合だったのですけれども、コロナでその辺が難しかったというところで、コロナ明けは、今、例えば、大井林町倶楽部とか。","voiceIndex":65,"id":"exchange-007"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"要望みたいになってしまうのですけれども、やはり平日の昼間が中心で、土曜日も行われているということですけれども、参加できる方が限定されてしまうかもしれないので、例えば、Ｚｏｏｍとか、そういうものも少し検討されてみてはいかがかと。","respondent":"菅野高齢者福祉課長","answer":"Ｚｏｏｍとか、そういったオンラインですることによって、その辺りのところがうまくできるかなというところも検証しつつ考えていきたいと思います。","voiceIndex":67,"id":"exchange-008"},{"speaker":"やなぎさわ委員","kind":"質問","question":"別なのですけれども、健康推進部の保健衛生編のところなのですが、先ほど、ご説明の中で、感染症のところで梅毒が急増しているというようなことでお話がありましたけれども、梅毒が増えているということで、いろいろ報道もされていて、いろいろな理由が巷では言われているのですけれども、品川区として、もし何か原因を、受け止めというか、あるようでしたら伺いたいのですけれども、いかがでしょうか。","respondent":"五十嵐保健予防課長","answer":"どちらかというと、結構高齢の方の発生届も上がってきているような状況ですので、何が原因かというのは難しい部分もあるのかなと思うのですけれども、やはり今、知識があまりない方も多いので、なるべく普及啓発をさせていただいてと思っているところですが、発生届自体が。","voiceIndex":69,"id":"exchange-009"},{"speaker":"やなぎさわ委員","kind":"確認","question":"分かりました。今度は社会保険編のほうなのですけれども、国保の未納に関して、督促等に関してなのですけれども、前年度の厚生委員会でもいろいろお話があって、督促状が赤い封筒で送られてきたりするのが非常に怖いというようなお話があったりしたと思うのですが、その後、そういったところの変化とかということは、検討されたり実施されたのかという確認だけお願いいたします。","respondent":"池田国保医療年金課長","answer":"実際には、一応、警告の意味もありますけれども、実は、見ていただきたいという意味合いがありますので、赤なり、黄色の封筒になるときもありますということで、これについてはやらせていただいているところです。","voiceIndex":71,"id":"exchange-010"},{"speaker":"やなぎさわ委員","kind":"質問","question":"基本的には封筒のデザインは変わっていないということでよろしいでしょうか。","respondent":"池田国保医療年金課長","answer":"封筒デザインは変更は特にありません。","voiceIndex":73,"id":"exchange-011"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これはこれで私は評価できることだなというふうに思っているのですけれども、でも、そういう講座は、様々、フレイルだけでなく、意識啓発の講座の仕組みが必要ではないかなというふうに思っていまして、地域包括支援センターがあるところでは、地域包括支援センターが、こういう講座を行っていると思うのですけれども、品川区は地域包括センターがないので。","respondent":"樫村高齢者地域支援課長、菅野高齢者福祉課長、池田国保医療年金課長","answer":"意識啓発が非常に重要ということは、区としても認識してございまして、こういった啓発をするために、各種、シルバー成年式だったり。避暑シェルター等も、今もう既に前倒しで設置していますので、そういったところにお立ち寄りいただくときに、職員のほうで見守っていただくとか。ただ、利用率についてですけれども、こちらは少し古くなってしまいますけれども、令和６年１月の診療での利用率では。","voiceIndex":76,"id":"exchange-012"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それまではその保険証が使えるのか、それとも１２月２日から資格確認書ということになっていくのか、そこのところの仕組みも教えていただきたいと思います。資格確認書を区のほうでマイナンバーカードをつくっていない人、それから、利用登録をしていない人に出していくことになると思うのですが、それは、いつ頃、区としては行うことになっていくのか、それについても伺いたいと思います。","respondent":"池田国保医療年金課長","answer":"資格書について、いつから発行するかですけれども、これは実際に１２月２日にもう保険証はございませんので、１２月２日に新規で加入された方には資格書の発行という形になってまいります。ですので、今年度は、資格書と保険証が混在するような形になるところです。","voiceIndex":80,"id":"exchange-013"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ということは、後期高齢のほうは来年の７月末までは使えるということで、それの前に資格確認書が発行されて送られてくる、来年の９月末までの国保のほうは、使えなくなる前に資格確認書が送られてくるという、そういう仕組みで送られてくるということで確認させていただいていいでしょうか。把握されていたら、どれぐらい廃業する医療機関があるのか、分かったら教えていただきたいと思います。","respondent":"池田国保医療年金課長、赤木生活衛生課長","answer":"保険証の部分で、資格確認書と資格の内容のものということで２つできると思うのですけれども、資格確認書がマイナ保険証を登録されていない方に対してお出しするもので、マイナ保険証を登録されている方については。先ほどのマイナンバー保険証、マイナ保険証の導入に当たって、診療所であったりとか、その辺りの部分で、廃業であったりとかという関係性というご質問があったかと思うのですけれども、生活衛生課として、診療所であったりとか。","voiceIndex":82,"id":"exchange-014"},{"speaker":"鈴木委員","kind":"質問・要望","question":"実際、知り合いの方がかかっているところが、もうこれを機会に辞めるのだという話を伺ったりしていまして、そういうものもぼつぼつ出てきているよねという、そういう話が出てきていますので、ぜひそこはつかんでいただきたいのと、本当に、実際に１月の段階で５.６３％しか使われていなくて、登録者も４７.４６％しかしていないということそのものが、やはりこのマイナ保険証を。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-015"},{"speaker":"ひがし委員","kind":"確認","question":"健康推進部の事務事業概要の５９ページのところなのですけれども、いろいろと気になる事業もあるのですけれども、今日は概要ということなので、１点だけ、どうしても気になるので確認させてください。今後、課ができたことについて、どういうことを行っていく予定なのかがあれば、教えていただければと思います。","respondent":"若生健康課長","answer":"令和５年度の実績の部分ですので、健康課のほうでやっていたのでお答えしますが、令和４年度から令和５年度で患者数が増えているというところについて、令和５年度はコロナが５類に移行しまして、その辺りから、医師会の休日診療所のところで。","voiceIndex":87,"id":"exchange-016"},{"speaker":"ひがし委員","kind":"質問","question":"病院とか、休日診療のところで、医師会とかと協力してやっていると思うのですけれども、そういう会議体があるのかとか、あとは、小児のところでいうと、現場から、例えば患者がいっぱい来るけれども診察し切れないみたいな声とかはないのかというふうに思うのですけれども、今までそういうお声とかはあったのか、そういう情報共有はどのようにされているのか教えていただければと思います。","respondent":"遠藤健康推進部次長","answer":"例えば、小児の救急などですと、昭和大学が中心にやられていますので、定期的に打合せというか、お話しする機会がありますので、そういうところでいろいろな情報を言っていただいたりという形はあるのですけれども、特段、どちらかというと。","voiceIndex":89,"id":"exchange-017"},{"speaker":"ひがし委員","kind":"質問・要望","question":"今、何か考えていることがあれば教えていただきたいのですけれども。","respondent":"遠藤健康推進部次長","answer":"それはこれまでもやっているので、そういうお声が出ていたというところですけれども、今回、私どもの課ができましたので、そういう意味では、もっと定例的にきちんとやっていこうというような形で、今、調整させていただいて、年に数回という形になりますけれども。","voiceIndex":91,"id":"exchange-018"},{"speaker":"筒井委員","kind":"質問","question":"私からは、健康課では、健康づくり、高齢者の健康づくりということも含めてやられていると思うのですけれども、高齢者地域支援課がやられている高齢者の健康づくりがあるのですけれども、これはどういったすみ分けで事業を決めているのかなと思いまして、健康課の健康づくりのほうが、昔から、どちらかというと、全世代型で、高齢者地域支援課のほうが高齢者に特化したものとか。","respondent":"若生健康課長","answer":"実際に、予算的には介護保険の事業で予算を確保している、例えば、ふれあい健康塾ですとか、出会いの湯ですとか、そういった事業については、こちらに執行委任をいただいて、地域の健康づくり団体と健康課が連携して事業を実施しているということもありますけれども。","voiceIndex":95,"id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6723#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":32903,"voices":100}},{"id":"r06-20240610-8","meetingId":"r06-cm06","date":"2024年6月10日","dateIso":"2024-06-10","committee":"建設委員会","time":"午後 １時００分～午後 ２時４２分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"えのした副委員長","kind":"意見","question":"建設委員会副委員長を務めします自民党・無所属の会、えのした正人です。１年間どうぞよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":3,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"それぞれご説明ありがとうございました。都市環境部長の冒頭の概要説明の中で、低炭素社会から脱炭素社会への移行という点が強調されましたので、環境対策および再開発について伺いたいと思います。前者と後者で何が違うのか、伺いたいと思います。併せて、いずれにしても気候危機と言われている中、ＣＯ２の総量を減らすことは急務だと思いますが、その点についても伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"いずれにしてもＣＯ２を削減しなければいけないということは急務だと私は思いますが、そこで再開発についてこの間も私は批判してきましたが、ＣＯ２を減らすと言いながら、再開発事業によってタワーマンションや高層オフィスビルを今後もつくり続けると。これは矛盾ではないかと思いますが、いかがでしょうかと。それに伴って、事業への補助金も膨らんでくるという関係にあるのか、伺いたいと思います。","respondent":"中道都市開発課長","answer":"再開発と環境の関係性です。再開発でつくる建物につきましては、開発諸制度といったものを運用して建物をつくってまいります。そうした中には、環境に関する項目があります。","voiceIndex":59,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問","question":"私は、ＣＯ２を減らすという大きな目標と再開発事業を進めるというのは、矛盾するのではないかと伺いました。これまでもそういう説明がありましたが、今、問題になっているのは、そもそもＣＯ２を基準日から比べて品川区も５０％以下にまで削減するという目標を掲げているときに、再開発事業をさらに広げていくということは矛盾するのではないかと思いますが、改めて伺いたいと思います。","respondent":"中道都市開発課長","answer":"総事業費が上がったからといって、それに伴ってその分を全て補助金で賄うというものではありません。事業計画や資金計画なども見て、適正に対応しております。","voiceIndex":61,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"ＣＯ２削減とこれだけ地球規模で叫ばれながら、品川区が事業者と連携して、再開発を続ける。ぜひ、再開発事業は見直していただきたいと思います。今日は個々には詳しく聞きませんが、今日ご出席の方々、例えば公園の維持管理、区道の維持管理、交通安全の信号機だったり点字だったり、様々区民の要望に対応する際に、限られた予算の中で四苦八苦している話をよく伺います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":63,"id":"exchange-005"},{"speaker":"のだて委員","kind":"質問","question":"都市環境部のほうから伺いたいと思います。１ページのところに、「輝く笑顔住み続けたいまちしながわ」ということで将来像が書かれております。２２ページにもあります、先ほども言いましたが特定整備路線のところです。その中で、都の中での土地収用適用基準も改定しました。こうした強硬手段は私はやるべきではないと思いますが、区としてはどのように受け止めているのか、伺いたいと思います。","respondent":"高梨都市計画課長","answer":"区としましては、この記載の違いによって、東京都が態度ややり方を大きく変えて進めるといったような認識は持っておりません。引き続き、十分な対話、丁寧な説明等を行っていただきながら、区と連携して事業が進められていくものと把握しています。","voiceIndex":65,"id":"exchange-006"},{"speaker":"のだて委員","kind":"質問","question":"住み続けたいまちというところでは、安心・安全のまちにしていくということですが、安全・安心のまちにしていくというところで、特定整備路線や再開発によってやはり住民が追い出されていることになっております。いかがでしょうか。いかがでしょうか。特定整備路線のところでは、今回記載が変わったことで対応は変わらないという……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-007"},{"speaker":"のだて委員","kind":"質問・要望","question":"いかがでしょうか。こうしたことが実際分かったわけですから、区としても実態調査をしていくべきではないかと思います。防災まちづくり部のところを伺いたいのですが、２３ページにコミュニティーバスのことが書かれております。そうしたところを区でもご覧になっていると思いますが、それを受けて、台湾の地震での対応に関しての教訓ですとか、区の対応に活かすべきことは何か、伺いたいと思います。","respondent":"高梨都市計画課長、中道都市開発課長、櫻木地域交通政策課長、大友公園課長、羽鳥防災体制整備担当課長","answer":"土地収用法等で定められたものですので、新たに東京都が大きく態度を変えて記載を変えたというものでなく。そうしたところで対応しておりますので、追い出しではございません。コミュニティーバス選定時から、引き続き交通サービスから少し離れた圏域外であるということは変わってはいないという状況だとは認識しておりますが。指針をつくるに当たりましては、地域の意見を取り入れつつ、公募指針の検討をしていきたいと考えております。","voiceIndex":69,"id":"exchange-008"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうしたところを受け止めて、本当に住み続けられるまちにしていっていただきたい。これを求めておきたいと思います。実態調査はしないということなのか、伺います。コミュニティーバスですが、技術革新等いろいろあるということで、昨年も伺ったときに、幅が狭い車体が発売されるという話もありました。そういったことの検討はどうなっているのか。ぜひ運行していただきたいと思いますが、いかがでしょうか。","respondent":"高梨都市計画課長、櫻木地域交通政策課長","answer":"具体的な被害の実態等が明らかになった暁には、また国等と協議して、実態調査という段になる可能性はないとは言い切れないと思いますが、現段階として。委員ご指摘いただきましたとおり、車幅の狭いものが実用化できないかという期待はしていたところですが、残念ながら、現時点ではまだ実用化に至っていないという状況だと認識しております。","voiceIndex":76,"id":"exchange-009"},{"speaker":"つる委員","kind":"質問","question":"横串の関係なのでちょっと伺います。環境課で１５６ページ、しながわＳＤＧｓ共創推進プラットフォーム専門部会（環境）というところです。既存の品川区環境活動推進会議が政策提言を行う会議体になるという流れですが、メンバーは、既存の会議の委員構成というのは変わらずに、そのまま専門部会としてそちらに移行するというイメージでよろしいのか、教えてください。","respondent":"中西環境課長","answer":"ご指摘のとおり、メンバーに関して変更はございません。といいますのは、品川区環境活動推進会議は任期２年間でやっておりまして、昨年度が１年目でございましたので、本年が２年目というところで会議の名称を変えて活動を進めております。","voiceIndex":80,"id":"exchange-010"},{"speaker":"つる委員","kind":"確認","question":"これは、今回の２定でいろいろと議論があるかと思うので、そこに委ねたいと思います。分かりました。１点だけ、この既存の品川区環境活動推進会議に関するホームページを確認すると、委員構成のところで区長指定で３人とあります。その中で「学識ケンケン者」となっているのです。ぜひ後でご確認いただき、修正されたほうがいいかなと思いますので、よろしくお願いします。","respondent":"中西環境課長","answer":"大変失礼いたしました。早急に対応いたします。","voiceIndex":82,"id":"exchange-011"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"提案","question":"所管事務調査についての前に、今、道路大会について、正副委員長および１名というご説明がありました。それだけに、委員長、副委員長および委員１名、建設委員会として委員を代表派遣するというのはやめるべきだと私は思います。けれども、地域公共交通機能の充実・整備ということで、コミュニティーバスについて所管事務調査で深められたらと思いますので、提案させていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":87,"id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6721#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":33250,"voices":88}},{"id":"r06-20240610-9","meetingId":"r06-cm06","date":"2024年6月10日","dateIso":"2024-06-10","committee":"文教委員会","time":"午後 １時００分～午後 ３時０２分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の１、幹部職員紹介","agenda":"の１、幹部職員紹介","exchanges":[{"speaker":"あくつ委員","kind":"意見","question":"公明党あくつ広王です。どうぞよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":7,"id":"exchange-001"}]},{"id":"topic-02","title":"の２、事務事業概要","agenda":"の２、事務事業概要","exchanges":[{"speaker":"あくつ委員","kind":"確認","question":"今日は事務事業概要ということで、１点だけ、品川区の全体の状況について伺います。いわゆる担任の先生がいらっしゃらないと、配置ができていないというようなことを伺ったのですが、私のような昭和世代の人間からは、ちょっと考えられない状況なのですけれども、実際そういったことが区内でも起きているのかどうか、まず確認させてください。","respondent":"中谷指導課長","answer":"そのような場合に、基本的には東京都の要綱に沿いながら補充申請というのをやっていくわけなのですけれども、一番大事なことはスピーディーに人員が補充されるですので、日頃からこの話題に関しましては校長会とも連携をしまして。","voiceIndex":41,"id":"exchange-002"},{"speaker":"あくつ委員","kind":"確認","question":"全国的に起きているということで私も認識はしているところなのですが、１点だけ確認させてください。そこだけやはり保護者の皆さんも心配されているところなので、そこだけ最後に確認させてください。","respondent":"中谷指導課長","answer":"こういったピンチなところをしっかりチャンスと捉えて、子どもたちに不利益がないような形で、教育課程を進めてまいりたいと考えています。","voiceIndex":43,"id":"exchange-003"},{"speaker":"あくつ委員","kind":"意見","question":"教育委員会はじめ学校現場でも必死の努力をされているということは私も認識しておりますので、引き続きそういった様々な工夫と併せて、教員の確保というところを、やっていただいていると思いますけれども、くれぐれも引き続きお願いしたいというところで終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":45,"id":"exchange-004"},{"speaker":"高橋（し）委員","kind":"質問","question":"３４、３５ページに服務関係のことが出ているのですけれども、東京都の、都費の負担の先生方はもう本当に日頃、各職場で一生懸命、教育活動をしていただいていると思うので、そこには敬意を表しております。東京都教育委員会は公表しているのですけれども、品川区教育委員会として、都費負担の先生方のそういった懲戒についての公表やあるいは説明についてはどのようにお考えでしょうか。","respondent":"中谷指導課長","answer":"毎回この文教委員会の場で、体罰等の不適切な指導を行っているものを含めての調査結果を定期的に報告しています。毎年やっておるものですので、この中で、懲戒処分の内容につきましてもご説明をさせていただきたいと考えています。","voiceIndex":46,"id":"exchange-005"},{"speaker":"高橋（し）委員","kind":"質問","question":"体罰などについては報告あるのですけれども、そういったことでないいわゆる不適切な指導とか、そういうことに関しての報告はないと思うのですけれども、その点についてはいかがですか。","respondent":"中谷指導課長","answer":"体罰等の「等」の中に、今ご指摘いただいた不適切な指導であったり暴力であったりという、カテゴライズされているものを一覧でお示しすることによって、ご説明させていただきたいと考えていますので、よろしくお願いいたします。","voiceIndex":48,"id":"exchange-006"},{"speaker":"高橋（し）委員","kind":"質問","question":"ちょっと今日は初日なので、そこまでとしていただいて。区負担の教職員のうち、区独自教員の方がそういった懲戒に値するような、あるいはいろいろな処分をした場合の取扱いはどのようになっているのでしょうか。その処分についての判断をするのは、教育委員会の人事担当課になるのでしょうか。それを含めてお願いします。","respondent":"中谷指導課長","answer":"こちらにつきましては、東京都が東京都教育委員会からというものに対して、区の固有の教員に関しては品川区教育委員会からということになりますので、そのプロセスでもって同様に対応いたします。もしも処分等のことが起きてしまった場合にはご説明をさし上げたいと考えています。","voiceIndex":50,"id":"exchange-007"},{"speaker":"高橋（し）委員","kind":"確認","question":"そうすると、人事ですから、教育委員会の指導課の中で、恐らく区の条例等に基づいてそういった処分を行うのではないかということの確認が１つと、こちらについては区の職員の話ですけれども、区の職員についてはホームページ等で、懲戒処分というのは、もちろん詳細が分からないように、プライベートなことが分からないように公表されているのですけれども、区の職員というカテゴリーで考えたときに。","respondent":"中谷指導課長","answer":"こちらについても今お話しいただいたとおり、処分がもしあった場合に、被害の影響を受けてしまうようなお子さんについてはくれぐれも十分に配慮を期した中での公表というところになろうかと考えていますので、そこを十分配慮した上で。","voiceIndex":52,"id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"今年の４月１日に新たな教育目標を適用ということでありますが、これはちょっと確認したら、国の第４期教育振興基本計画が改定されたことに伴って文言整理がなされ、こういう形になっているというふうな理解をしておりますが、それでいいのかということと、あと一方で教育大綱というのがありますが、その教育大綱と教育目標あるいは基本方針との関係性について、ちょっと確認させていただきたいと思います。","respondent":"米田教育次長","answer":"教育目標の改定ですけれども、委員からお話もありましたように、国の教育振興基本計画の改定に伴いまして、特に教育目標の前文にあります「誰一人取り残されず、全ての人の可能性を引き出す共生社会の実現に向け」というようなものを文言に入れるとともに、項目について。","voiceIndex":55,"id":"exchange-009"},{"speaker":"田中委員","kind":"確認","question":"そのタイミングとして、昨年の国の教育振興基本計画改定に伴って教育目標等が変わった、改定されているということであると、先ほどあったように令和２年の新しい長期基本計画に基づいて教育大綱が令和３年に改定されているという、そういうタイミングなのですが、今の次長のお話の１０年間を見通したものだということですので、要はその教育目標なりがもう既に直近で変わっているわけですが、教育目標。","respondent":"米田教育次長","answer":"このような手続になろうかと思います。","voiceIndex":57,"id":"exchange-010"},{"speaker":"田中委員","kind":"質問・要望","question":"分かりました。今後、区長が１０年以内に長期基本計画を変えるかどうかというのも今後のことでありますので、それはそれらに基づいてということですね。学校教育というのは学校の中が基本的には果たされる環境だと思っておるのですけれども、すみません、若月世代からの理解を深めたいという思いから、ちょっと確認をさせていただきたいです。","respondent":"米田教育次長","answer":"前々教育長のときに、プラン２１というようなことで実施をいたしました。そのとき、多分今に比べれば学校のことは学校の中でということで、決して地域に開かれていなかったわけではないと思います。","voiceIndex":59,"id":"exchange-011"},{"speaker":"田中委員","kind":"質問","question":"地域力を活かすことはすばらしいことだと思いますし、それに基づいてその学校の特色ある学校運営というのがなされているということが事務事業に書いてあるので、分かるのですけれども、一方で特定のところでしかその教育が受けられないという、教育の均等化というか一体化というか、そういう観点から言うと、地域の特色ある、例えば何かに長けた方が地元にいらっしゃって。","respondent":"米田教育次長","answer":"品川区は品川区立学校教育要領というのを設けておりまして、国の学習指導要領以外のところで、そういうような形で９年間を見通したということが特徴です。","voiceIndex":61,"id":"exchange-012"},{"speaker":"田中委員","kind":"確認","question":"最後に１点だけ確認。一番最初の全体像の中で、プレス発表にもありました品川区教育振興基本計画が今年度策定されるということなのですが、この基本計画は全体像の中で言うとどこに、事務事業概要には書いてなかったので、どういう形で位置づけられていくのか確認したいと思います。","respondent":"米田教育次長","answer":"教育振興基本計画については、これから教育委員会全体として定めていくような形になりますけれども、先ほどの確認みたいな形になりますけれども、教育大綱までが区長部局と連携しつつというようなところになりますので、教育振興基本計画は。","voiceIndex":63,"id":"exchange-013"},{"speaker":"西村委員","kind":"質問","question":"１点だけ伺えればと思います。大きなところのご質問でということなのですが、少しだけ入り込んでしまって申し訳ないのですけれども、教育総合支援センターの事務分掌のところで、不登校ですとか特別支援ですとか担当が特化されたことで、特により強化されている点ですとか、これまで行き届かなかったところに対応ができていくという点がありましたら、お聞かせいただければと思います。","respondent":"丸谷教育総合支援センター長","answer":"今、４月、５月、６月に入りましたけれども、それぞれが円滑した運営を進められるようになってきております。","voiceIndex":65,"id":"exchange-014"},{"speaker":"西村委員","kind":"意見","question":"特に今、不登校の子の支援で様々な学習参加の形態を用意していただいていると思っているのですけれども、なかなか早期発見ですとか、早期対応が難しい状況なのではないかと思っていまして、こういったご相談を受けている担当の方がいち早く学校の状況をキャッチアップして、整備をしていただくということがすごく重要だと思っていますので、引き続きよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":67,"id":"exchange-015"},{"speaker":"山本副委員長","kind":"質問","question":"私からも１点だけ、部活動地域移行の推進に関して質問させてください。今年度から１５校３０部活を対象に進めているというところだと思います。各学校の部活動地域移行対象種目については選定をされていると理解しておりますが、現在の民間委託の状況についてお教えください。","respondent":"中谷指導課長","answer":"中には文化部もあったり、運動部ですと卓球部などが複数選ばれているというところがあります。は今年度しっかりこの導入をした上で、その成果と課題というところも含めてしっかり把握していくというところでやってまいりたいと考えていますので、よろしくお願いいたします。","voiceIndex":68,"id":"exchange-016"},{"speaker":"山本副委員長","kind":"質問","question":"選定が終わって、これからやっていくというところなのですけれども、一部聞いたところによりますと、選定はしているものの、従来の顧問の先生が異動してしまっていない、指導者を待っているような状況があって、緊急的にその指導者を臨時的に探したりしている学校があると聞いているのですけれども、そのような状況のところがどの程度あるのかというところと、実際にその民間委託の指導者の方は。","respondent":"中谷指導課長","answer":"そういった意味では丁寧な打合せの下に、円滑にスタートができるようにということで進めてまいりたいと考えています。","voiceIndex":70,"id":"exchange-017"},{"speaker":"山本副委員長","kind":"質問・要望","question":"ぜひ、丁寧に進めていただきたいということと、子どもたちにとってはその一学年は一度きりしかないところですので、部活動が滞らないように、切れ目のない部活動ができるように、十分なサポートをよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-018"},{"speaker":"あくつ委員","kind":"確認","question":"１点だけ、これも確認させてください。","respondent":"芝野保育入園調整課長","answer":"今現在、いろいろな相談が来ておりまして、今後、具体化し新規開設になる園も予定しているところなのですが、ちょっとここではまだご説明できないので、場を改めましてまたご報告させていただきたいと思います。","voiceIndex":87,"id":"exchange-019"},{"speaker":"あくつ委員","kind":"提案","question":"私が住んでいる海側の地域というのは保育園の需要がまだまだというか、人口がやはり予想以上に増えているというところもあって、やはり地域地域で非常にその保育ニーズの違いがあるというところで、今課長がおっしゃられたとおりだと思うのですけれども、ただその事業者からのご提案と品川区のニーズというのものが本当にマッチングするというのは非常に難しい状況というのは分かるのですが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":89,"id":"exchange-020"},{"speaker":"田中委員","kind":"質問・要望","question":"１点目は児童相談所に関してでございまして、いよいよ今年の１０月に区立の児童相談所ができるということで、今の段階ではまだ準備段階だと考えていますが、組織として１０月以降、また恐らく実施運営体制を再構築することになるのか、もう既にそこが視野に入った形での体制に整っているのかというところをお伺いしたいのと。","respondent":"原児童相談所担当部長","answer":"委員ご指摘のとおり、重症化、あるいは重篤化、これを極力抑えるためのネットワーク、そういったものも地域に根差した形でのケースワーク活動や、日頃のよく顔の見える関係というようなことを言われていますが、それをただ単に言葉だけではなく。","voiceIndex":90,"id":"exchange-021"},{"speaker":"田中委員","kind":"質問・要望","question":"併せて子ども未来部の事業でありますが、ちょうど教育委員会の皆様とも一緒の委員会なので、両者に関連する質問として子ども食堂がありますが、１つはその子ども食堂を運営していただいている区内のネットワーク、ボランティアの皆様のご協力には強く感謝をする一方で、その背景として、何ゆえ子ども食堂を開設しないといけない状況になってしまっているのかという、本来であれば子ども食堂がない状態が。","respondent":"飛田子育て応援課長","answer":"今後のところですが、委員おっしゃるとおり、子ども食堂がないようなことが一応理想だということも一つはあるかと思うのですが、最初はそういう貧困とかそういったところから始まり、今はみんなで楽しく食事をしてという、そういう役割もあるところもありますので。","voiceIndex":92,"id":"exchange-022"},{"speaker":"田中委員","kind":"質問","question":"特に学校給食の厳しい状況も理解はいたします。ただ、子どもファーストで子どもの視点で、いろいろな知恵をぜひ出していただく中で、文教委員会所管の教育委員会と子ども未来部の連携によって、子どもの食事面においての対応もぜひしっかりしていただけるように期待をしながら、質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-023"},{"speaker":"西村委員","kind":"質問・要望","question":"私も児童相談所の開設準備をしていただいているので、ちょっと２点ほど伺いたいのですが、現状東京都がしていたものを区が独自でしていくという課題とか苦労がたくさんあるだろうと思っておりまして、この辺りの現状の難しさがあればお聞かせいただきたいと思うのですが、例えば一時保護所の運営ですと、全国的にも課題になっている通学をどうするのかとか、こういったところの区のお考えとか取組があれば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":97,"id":"exchange-024"},{"speaker":"西村委員","kind":"質問","question":"これからのところでご質問をさせていただきまして申し訳ありませんでした。よく分かりました。本当にこども家庭庁の方とお話をしていましても、この人材採用のところが本当にどこの自治体も大変だと伺っておりましたので、大変安心をしております。もう一点だけ、すみません。","respondent":"染谷子ども家庭支援センター長","answer":"やはり区のほうで実施していくにあたって、１８歳未満のいわゆるヤングケアラーという方たちについて支援、接点を持っていくというのは、学校などの関係機関を通じることで、比較的関係を取りやすい部分ではあるのですけれども、それ以上の年齢になってくると。","voiceIndex":101,"id":"exchange-025"},{"speaker":"せらく委員","kind":"質問","question":"児童相談所から１点と、あと病児保育についてお伺いしたいと思います。医療機関との連携についてお伺いしたいのですけれども、東京都でやっているときは都内の病院と連携をして、例えば入院だとかもやられたと思うのですけれども、区立になると、病院などは区内で医療機関と連携するのか、それとも都内でどこか連携先を探していくのか、どういう方向であるのかをお聞かせいただければと思います。","respondent":"原児童相談所担当部長、中島保育施設運営課長","answer":"医療機関との連携につきましては様々なパターンがございまして、日常的な児童相談所の運営という部分では、一時保護所の入所時における健診、あるいは入所中のちょっとしたけが・病気といった場合には、やはり区内の地域の医療機関。場所も西側に偏在しているということもありますので、より区内がカバーできるよう新規開設を目指して、場所も拡充するなど、病児保育のニーズに応えてまいりたいと思います。","voiceIndex":104,"id":"exchange-026"},{"speaker":"せらく委員","kind":"確認","question":"児童相談所との医療連携なのですけれども、区内にお住まいの方で一時保護されて、多摩の地域のほうの病院に入院をしてしまったというケースがあったとお聞きしたところだったので、なるべく近場で見つかるといいのかなというところでお伺いをさせていただきました。地域との連携のほう、どうぞよろしくお願いします。病児保育なのですけれども、ニーズがあるということは確認できました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":107,"id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6719#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":37800,"voices":110}},{"id":"r06-20240610-5","meetingId":"r06-cm06","date":"2024年6月10日","dateIso":"2024-06-10","committee":"総務委員会","time":"午後 １時００分～午後 ３時２６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を25件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"区長室が新たに編成されて、新たな組織になったところで、秘書担当のご説明もしていただいたのですが、去年の議事録を読むと、秘書担当が区長が思ういろいろなトップマネジメントでやっていきたいことを、企画課だったり財政課だったり、それぞれの所管にスムーズにつなげていくとご答弁されていて、そうすると、これまでは企画経営部のところで主立っていろいろ議論がされて。","respondent":"崎村企画課長","answer":"秘書担当課長については、令和５年度から設置をさせていただいて、今、運用させていただいていますけれども、今、委員からお話がありましたように、区長が替わりまして、より区長の意向をスムーズにつなげるという意図もあり、秘書担当課長を設置させていただきましたけれども。","voiceIndex":81,"id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"それと、１２ページのいじめ防止対策推進事業ということで、これも新たに区長部局にできたということですけれども、相談窓口の設置とご説明いただいたと思うのですが、こうした相談は区長部局のいじめ防止対策推進事業のほうにも相談は来ているのか、どれぐらいあるのか伺いたいのと、4)、ｃのところで、重大事態のところでは、区長の諮問に応じて再調査すると書いてあるのですけれども、この間。","respondent":"石井コンプライアンス推進担当課長","answer":"いじめ問題調査委員会につきましては、現在進行管理をされております１２件の重大事態全てについて再調査を行うのではなく、現行、教育委員会の附属機関としていじめ対策委員会というものがございまして、その中でいじめの全体像を調査するものであり。","voiceIndex":83,"id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"再調査のところは、不備があるとか、再調査が必要だというのは、どこで決まるのですか。教育委員会のほうからはあまりそういうのが来ないと思うのですけれども、それが不備だという基準というのは、誰がどう決めて、どう再調査につながるのでしょうか。","respondent":"石井コンプライアンス推進担当課長","answer":"これは品川区のいじめ防止ガイドラインのほうで定めているところですけれども、それを受けて、内容を精査し、文部科学省のいじめのためのガイドラインがありますので、そういった内容と照らし合わせて、十分な調査が尽くされているかといった。","voiceIndex":85,"id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"概要ですので、細かいところまでは行かないように、ジェンダー平等推進担当のところで、２８ページですけれども、２）の苦情・相談の申出・対応というところで、７月１日施行というところなのですけれども、ジェンダー平等推進の条例をつくるに当たっても、本当に多くの反対意見といいますか、トランスジェンダーの方への偏見といいますか、そうした意見が多数寄せられてきていたと思うのですけれども。","respondent":"木村人権・ジェンダー平等推進課長","answer":"苦情・相談の申出についてなのですけれども、これは７月１日から始まるところではあるのですが、ご相談というか、ご意見という形で、お電話やメール等でいただくことはあります。それに関しては、今の時点では真摯にお答えするというような形で回答をしています。","voiceIndex":87,"id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"意見","question":"もしやりたいと思ったら、相談するということですね。本当に多岐にわたるジェンダー平等を実現しようとすると、本当に幅広く大変だという思いを私もしているのですけれども、やはり確実に進めていかなくてはいけないところだと思いますので、引き続き私たちも、普及啓発も含めて、具体化に向けて協力していきたいと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":89,"id":"exchange-005"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、今後も、別になるのか。それから、５ページのＳＤＧｓとあるのですけれども、ＳＤＧｓというのは時限的なもので、２０３０年まであと６年で、これはどうするのかという話で、これ、２０３０年に向けて、もう中盤を越えて、終結というか、まとめに入っていかなければいけないという中で、品川区としてどうするのですかというところを、ぜひ教えていただきたいと思います。それから、施設整備課です。","respondent":"崎村企画課長、井添ＳＤＧｓ推進担当課長、長尾施設整備課長","answer":"先ほど委員からは、支援というところではなく、企画課が主体的にむしろやったほうがという、そこのところですけれども、当然。ただ、行く行くは各所管が実施している事業がＳＤＧｓのゴールに向かって、達成に向かって推進できるようになれば。こちらの計画の中で、３０年から４０年程度の長期スパンの中で、各公共施設についてどのように考え方、整備。","voiceIndex":91,"id":"exchange-006"},{"speaker":"西本委員","kind":"質問・要望","question":"やはり平等に、議員というのは同じ立場ですから、情報はきちんと出すべきところは出す、それから、１日遅れてやるとかではなくて、その日、順番はいいです。解釈の助言というのは何ですか。分かっているのではないですか。別に問題が解決するための手段としては、納得する部分もあるのですけれども、今後、どういう役割分担で各委員会に、文教委員会と総務委員会に報告をしていただけるのでしょうか。","respondent":"勝亦総務課長、石井コンプライアンス推進担当課長、與那嶺戦略広報課長","answer":"公益財団法人の補助金といたしまして、既にご報告申し上げていますように、移転を検討していますので、移転費用等の補助。一方で、学校の中でどのように取り組んでいくか、学校の取組としてのものについては、文教委員会でご審議いただく事項ですので。我々が今回、４月に名前が変わって取り組んでいくこと、これから取り組んでいきたいというところでいきますと、まず。失礼いたしました。１件、ご質問の回答が漏れておりました。１ページ、法規立案・解釈等の助言です。","voiceIndex":95,"id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"ありがとうございました。これはもちろん正副委員長にお任せしますが、両方またがっているわけですから、やはりどうしても関わってきますよね。可能かどうか分かりませんが。でも、今のお話でも、４０周年はいいですよ。４０周年はそれは別枠ですよ。なので、きちんと根拠がある中で説明を、これから委員会をやっていく中で、していただきたいと強く要望したいと思いますので、ぜひよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":100,"id":"exchange-008"},{"speaker":"須貝委員","kind":"質問","question":"コンプライアンス推進担当のほうでお聞きしたいのですが、民間企業は、企業の中で契約案件、それから株式の情報案件で、あとはコンプライアンス、違法行為があったときに、民間企業内で調べて、それぞれその会社をいい方向にというのですか、間違いない方向に進むべく対処できる。悪い言い方をすれば、それによって退職される方も出てきてしまう可能性もあるので、それについてどうなのか、教えてください。","respondent":"石井コンプライアンス推進担当課長","answer":"そう考えているところです。","voiceIndex":102,"id":"exchange-009"},{"speaker":"須貝委員","kind":"質問・要望","question":"恐らく今年の秋にはマイナンバーに移行しないと使えないので、資格証か何か出てくるという話まで聞いているのですが、詳しいことは分からないのですが、このような状況で、国の法律ですから、移行せざるを得ないのでしょうけれども、区役所として相当の混乱を招くのではないかと思うのですが、その辺についてどのようにお考えなのですか。それで、何か対応策というのは考えられているのですか。","respondent":"宮尾人事課長","answer":"健康保険証のマイナンバーカードとしての利用ですけれども、もちろん国の考え方、通知等の考え方をしっかりと実現していく、守っていくということは大前提のことではありますけれども、今、委員がまさにおっしゃったように、進めるに当たって混乱を生じさせないように、あるいは。","voiceIndex":104,"id":"exchange-010"},{"speaker":"須貝委員","kind":"質問・要望","question":"それがなければ医療機関にかかれないのかという話まで、延長というのは出ていますけれども、その辺はしっかり私はやってほしいと思います。そうすると、ほとんどこの電気自動車の、せっかくＣＯ２を出さない有効な機能が全く使えないという状況になるではないですか。区民サービスを第一にするのだということを考えていただきたいと思います。この間、中国でフェリーに電気自動車を載せて、島に渡ったと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":106,"id":"exchange-011"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ご説明ありがとうございました。１点だけ確認をします。７月７日に行われる選挙が、この投票支援カードなどが実現をするのかどうかという確認をさせていただきたく思っておりまして、もしこれを進めていただいているようでありましたら、具体的なこともお知らせいただければと思います。","respondent":"今井選挙管理委員会事務局長","answer":"当日、初めての試みですので、既にあります、指さしなどで対応しておりますコミュニケーションボードとともに、投票支援カードについては受付に置かせていただきたいと考えています。","voiceIndex":108,"id":"exchange-012"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ありがとうございました。私の要望としては、それぞれの封筒の中に入れてほしいというのがあったわけなのですが、いろいろなところでやっているところもあれば、そうでない、ダウンロードして使うという様々なやり方で、それぞれの自治体において取り組んでいるのも確認をしていますが、品川区はダウンロードしていただく形ということで、確認をさせていただきました。どうぞよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":110,"id":"exchange-013"}]},{"id":"topic-02","title":"令和６年度ＳＤＧｓ未来都市等の選定結果","agenda":"令和６年度ＳＤＧｓ未来都市等の選定結果","exchanges":[{"speaker":"西本委員","kind":"質問","question":"再三聞いているのですけれども、品川区政におけるウェルビーイングとは何ですか。そこからお答えをお願いしたいのですけれども。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"ウェルビーイングにつきましては、１９４６年のＷＨＯ、世界保健機関の憲章で初めて言葉として出てきたものですが、肉体的、精神的、そして社会的にも満たされた状態、かつ、ウェルビーイングとしてそれが続いていく、持続していく状態と理解をしております。","voiceIndex":115,"id":"exchange-014"},{"speaker":"西本委員","kind":"質問・要望","question":"だから品川区はどうするのですか、どこに絞るのですかということを言っているのです。なので、資料１に「ウェルビーイングの視点から」と書いてあります。何をどうするのか分からない。なぜかというと、「子どもとともに成長する新時代のＳＤＧｓしながわ」なのです。分かりません。向上とは、一体何の向上ですか。幸せの向上ですか。ウェルビーイングの向上とは何だろうと疑問に思うのですが、いかがですか。","respondent":"井添ＳＤＧｓ推進担当課長、久保田企画経営部長","answer":"それは多分にあるかと思いますので、ただ、ウェルビーイング、一人一人違う幸福の考え方というのはあるということは大前提で、それを一人一人のウェルビーイングを高めていくというところを、より区民の方に伝わる言葉で。今、課長が説明しましたけれども、ウェルビーイングの向上ですから、区民により幸せになってもらいたいというのが品川区としての考え方だと思います。","voiceIndex":117,"id":"exchange-015"},{"speaker":"西本委員","kind":"質問","question":"それと、これ、既に以前の総務委員会で報告されたということなので、中身のことはあまり詳しくはできないかもしれないのですけれども、資料１を見ても、品川区で今までやっているよねと。これ、全部見ると、新規というのもあります。だけど、皆さん、やっていたでしょう、これ。それをまとめただけですよねという感覚でいいのですか。何か新しいことはあるのですか。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"おっしゃるように、品川区がこれまで継続して長年取り組んできた事業、それから、新規と書いてあるものは、今年度、令和６年度に予算をつけていただきましたものですとか、拡充につきましても、予算を増額していただいたような事業になっております。","voiceIndex":120,"id":"exchange-016"},{"speaker":"西本委員","kind":"質問・要望","question":"今までの品川区が取り組んできたことが評価されたということですから、それは自信を持っていただいていいのかと思うのですが、別に新しいことではなくて、表現の仕方をもう少し考えていただければいいのかと思いました。それから、ＳＤＧｓのどの項目を達成したいのかというのが、いろいろ種類があるではないですか、１７項目。それをどこの部分を目指しているのかと思うので、そこだけ教えてください。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"今後の予定というところで、３年間、進捗管理を内閣府からしてもらいながら、区としてもＳＤＧｓの未来計画を８月を目安につくってまいります。そちらにつきましては、特に資料１の右側に書いてありますような事業の中で、それぞれＫＰＩ、目標ですね。","voiceIndex":122,"id":"exchange-017"},{"speaker":"須貝委員","kind":"質問・要望","question":"先ほど企画経営部長の温かい、それから、しっかりこれからウェルビーイング、ＳＤＧｓに向かって、誰一人取り残さない、そういう社会をつくり上げていく。その意気込みを聞いていて、感銘いたしました。ぜひ企画課長、それから財政課長は、企画経営部長とともに、品川区の区民を一人も取り残さないように、頑張っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":124,"id":"exchange-018"},{"speaker":"松本委員","kind":"提案","question":"そもそも私が不勉強で確認しておきたいので、これ、あくまで選定というのは、新年度、令和６年度に入ってからの選定ということなので、予算としては、今年の３月の段階で、令和６年度、審議が終わって通っていますけれども、これ、仮に選定されなかった場合に、ここに記載されている、品川区として新規でやろうとしている事業というのが幾つか書かれているのですけれども、予算との関係では。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"かつ、この自治体モデル事業の中で、経済、社会、環境という３側面をそれぞれまたがるような、３側面をつなぐような取組が補助金の対象事業になってまいりますので、例えば、社会の中での子ども施策１つとかというのは、モデル事業として提案しても。","voiceIndex":125,"id":"exchange-019"},{"speaker":"松本委員","kind":"質問・要望","question":"補正予算もしっかりと確認させていただきまして、審議させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":127,"id":"exchange-020"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そういう中でも一歩進めていくというところは、否定するものではないと思っています。過去にも質疑等があったのでしょうか。見ていないので、ごめんなさい、分かれば教えていただきたいです。２３区であるのかどうかも教えてください。あまりない斬新な感じがして、官民の連携というのは、すごく言われるようになってきているのですけれども、こういう部分は今現在どんな状況になっているのか。","respondent":"こしば委員長、井添ＳＤＧｓ推進担当課長","answer":"石田ちひろ委員、恐れ入りますが、ＳＤＧｓ推進ファンドについては、行財政改革特別委員会の内容になります。そのため、理事者は答えられる範囲でお願いします。例えば、来年の３月にしながわシティランを開催予定ですが、そちらの協賛企業などを皮切りに、区内の民間事業者の方などにも出資を募ってまいりたいと考えているところです。","voiceIndex":129,"id":"exchange-021"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"新妻副委員長","kind":"質問・要望","question":"すみません、１点だけ。この桜は、いつぐらいから植えられていたものなのでしょうか。かなり年数がたっていてこういう状況になってしまったのか、あまり年数はたっていないけれども病気になってしまったということなのか、お教えいただきたいと思います。","respondent":"佐藤経理課長","answer":"この桜ですけれども、正確なところは調べ切れなかったのですが、私が入庁したのが２５年ぐらい前なのですが、そのときには既にありましたので、３０年近くあるというところで、今回の状態になったと認識しております。","voiceIndex":137,"id":"exchange-022"},{"speaker":"西本委員","kind":"意見","question":"これは可能かどうか分かりませんが、私の思いだけです。これからつくり上げていくという観点なのでしょうけれども、でも、私たちも、ブランディングというのをあまりやっていないので、そういうのを調査するのもいいのかと思ったりするので、これから未来にかけて、品川区の在り方をどうしていくべきなのかというところの観点でテーマが決まるといいのかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":140,"id":"exchange-023"},{"speaker":"石田（ち）委員","kind":"意見","question":"一人一人が意識を変えて、みんなで変えていくとならないと、本当に実現しないと思いますので、そういった意味では、区の中、庁舎の中でもそうですし、職員も、そして施策も含めて、ジェンダーの視点でというのは、どう進めていけるのかというところは、調査研究していきたいと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":142,"id":"exchange-024"},{"speaker":"西本委員","kind":"意見","question":"すみません。今の意見に対して。でも、今、いろいろ分かりにくくなってきている部分があるので、もう少しジェンダーという意味も、さらに男性、女性というくくりではなくて、もっと広いところから捉えられるような調査をしてもいいのではないかと感じています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":144,"id":"exchange-025"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6727#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":46651,"voices":147}},{"id":"r06-20240611-14","meetingId":"r06-cm06","date":"2024年6月11日","dateIso":"2024-06-11","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ３時０３分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を36件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"筒井委員","kind":"意見","question":"品川改革連合の筒井ようすけです。どうぞよろしくお願い申し上げます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":9,"id":"exchange-001"},{"speaker":"あくつ委員","kind":"意見","question":"区議会公明党のあくつ広王です。どうぞよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":10,"id":"exchange-002"}]},{"id":"topic-02","title":"今後の委員会運営","agenda":"今後の委員会運営","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"資材高騰などがあるというのは承知をしておりますけれども、やはりこの事業費が１６０億円も上がっているという中で、５６０億円ということを示しているだけでは区民の理解が得られないと思いますが、いかがでしょうか。そうした委員会が形骸化しないように、今度の計画策定委員会でもしていただきたいと思うのですけれども、いかがでしょうか。","respondent":"山下新庁舎整備課長、泉広町事業調整担当課長","answer":"昨年度は先ほど申し上げましたように、アクセシビリティ整備の手引き、素案を策定する段に至りまして、ご説明の機会をいただくですとか、今後、基本設計をまたまとめていく中では、区民説明の機会も含めて検討を進めておりますので。２点、ご質問いただきました。１点目の今年度、予定しています対話型市場調査や土地鑑定評価におけます諸条件とは何だろうというお話です。","voiceIndex":56,"id":"exchange-003"},{"speaker":"のだて委員","kind":"質問","question":"新庁舎のところでは手続を進めていきたいということですけれども、やはりそれが今、本当に進めるべきかと思うのです。物価高騰の中で、区民の生活も苦しい状況になっていると。事業費が増えればその分、区民の負担も増えることになると思いますので、そうしたところでも、やはり区民の理解が得られないのではないかということでお聞きしました。そのことについて、答弁いただければと思います。","respondent":"小林新庁舎建設担当課長","answer":"庁舎につきましては、先ほど課長からお話がありましたように、様々建物の老朽化であったりあるいは設備の老朽化、様々な状況が進んでいる中では一刻も早く改築を進めていくべきと考えていますので、当然、理解を得ながら、しっかりと先に進めてまいりたいと考えているところです。","voiceIndex":59,"id":"exchange-004"},{"speaker":"のだて委員","kind":"質問","question":"一刻も早く進めるべきだというお話でしたけれども、庁舎としては、耐久性はまだ１０年以上もつということですから、やはり区民参加をしっかり位置づけて検討していくことが必要だと思います。やはりしっかりと情報公開と区民参加を位置づけて再検討していくと。この基本計画のメンバーに有識者が３名入っているということですけれども、この有識者を選定した理由を伺いたいと思います。","respondent":"吉岡政策推進担当課長","answer":"検討会は６月の下旬の予定ですけれども、今のところ、庁内の検討会なりますが、６月２４日の予定をしています。","voiceIndex":61,"id":"exchange-005"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうした中で、今回、１２月に保険証がマイナンバーカードに一本化されていくというような、紙の保険証がなくされてしまうということで、これが区民にも大きな被害があると思うのですけれども、そこの区の認識を伺いたいと思うのと、あと、私の問題意識としては、標準化のところで、これまで区が行ってきた区の取組、独自によい取組を進めてきたというところもあると思うのですが。","respondent":"西澤ＤＸ戦略担当課長、横田デジタル推進課長","answer":"１つ目の人員削減についてご説明します。ＤＸ推進の考え方の目的にも書いてありますが、ＤＸ推進の目的は２つあります。は区民の利便性向上と、あとは業務効率化による生産性向上になります。今後、令和６年１２月２日に保険証の新規発行が終了いたしまして、１年間の猶予期間を経て、保険証の利用が終了する点ですとか、全員に配布される予定です資格情報のお知らせ、資格確認書など新制度の周知はもちろんのこと、今。","voiceIndex":63,"id":"exchange-006"},{"speaker":"のだて委員","kind":"質問・要望","question":"最後の標準化のところですけれども、そうすると、区の持ち出しはあるということか、ないということなのかを伺いたいと思います。そのために医療従事者、事業者の負担が膨大になるということで、この間も保険証をなくすのはやめてほしいという声が様々上がってきたということですので、そうしたことはやはりやめていただきたいと、やめるべきだと思います。先に言ったところのご答弁をいただければと思います。","respondent":"横田デジタル推進課長","answer":"システムの標準化で、区の持ち出しがあるかですが回答としてはあるというところになります。国の標準化の対象事業費、国の対象部分については基本的には全て賄われる予定なのですがランニングコストですとか、その他、区が調整している部分について少し持ち出すことになります。","voiceIndex":66,"id":"exchange-007"},{"speaker":"のだて委員","kind":"質問・要望","question":"この実行委員会のメンバーがどういった方になるのかを伺いたいのと、今回のファンドの中では、子どもの意見を集約していくと、活かしていくということが盛り込まれていますけれども、この子どもの意見収集というのはどのようにするのか、この子どもというのが、実際、何歳というか対象年齢、小・中学校、高校生とか、そういったことも含めて、伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-008"},{"speaker":"あくつ委員","kind":"質問・要望","question":"確認からです。今日は、今回１回目ということだったので、ＳＤＧｓモデル事業のことについて、今、のだて委員からプラットフォームとこども会議についての質問がありましたけれども、これはファンドの話ではないということで、私どもは認識をしていますが、これから先、ここについては、この特別委員会の中で審議をしてもいいのかどうか、まずこれを確認させてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-009"},{"speaker":"あくつ委員","kind":"質問・要望","question":"答えられると答えてしまって、さっき課長が答えていたから、それはルール違反ですので、そこについては確認をしていただきたいと思います。今回、令和７年１月ですから、来年から始まるこの策定委員会は６回程度ということになっておりますけれども、これで区民の意見をしっかりと吸い上げられるのかということがどういう認識でいらっしゃるのか、確認をさせていただきたい。","respondent":"泉広町事業調整担当課長","answer":"この中でしっかり区民ニーズが把握というか、それがしっかりそこに踏まえられていくのかというご質問ですけれども、現在、跡地等活用検討委員会の中で、区民ニーズの把握に努めているところで、そこについては一定、活用のテーマですとか。","voiceIndex":75,"id":"exchange-010"},{"speaker":"あくつ委員","kind":"確認","question":"繰り返しになりますけれども。もう１点、荏原四中跡の整備のことについて、確認をさせてください。マイスクールということで、これは文教委員会になるのでしょうか。運営体制の検討に当たっては、過去の事例を踏まえ、適切な運営主体を検討することということで、民間の力を活用するという先ほどのご説明でもありましたけれども、ここについて、どのように受け止められているのか、確認をさせてください。","respondent":"吉岡政策推進担当課長","answer":"ただいま、ご意見いただきましたとおり、基本計画の検討会というところで、１番から１２番までというところで、非常に多岐にわたる所管を、横串を刺して検討を進めていくです。","voiceIndex":77,"id":"exchange-011"},{"speaker":"あくつ委員","kind":"質問","question":"今日は初回ということで、また１年間お世話になるのですけれども、そういった意味で、ここについて、障害児者総合支援施設の例を挙げましたけれども、あのときも品川区は、多様な、いわゆる品川区の運営主体というか、品川区の事業者が適切な関係を保ちながら品川区全体のレベルを上げていくのだ、障害者支援のレベルを上げていくのだということで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-012"},{"speaker":"山本委員","kind":"質問・要望","question":"これはとてもよい取組だと思っておりまして、ぜひ進めていただきたいと考えていますが、この中で１点、ご質問なのですけれども、民間資金の積極的な活用により、自立的な好循環を形成していくという目標を掲げていらっしゃるというところの中で、この表にあります金融機関や民間事業者等の事業に対する出資、資金協力というところですが、こちらの性質は寄附的なものなのか。","respondent":"泉広町事業調整担当課長、吉岡政策推進担当課長、西澤ＤＸ戦略担当課長、横田デジタル推進課長、井添ＳＤＧｓ推進担当課長","answer":"委員構成につきましては、今、活用検討委員会は２０名ということで、幅広い区民ニーズを集約していくというような趣旨で。交流ですので、多くの方々、多くの区民の皆さんに使っていただきたいというところもありますので。具体的には、現状の紙で申請している業務を各課にヒアリングして、件数の多い申請業務を重点的に実施していく必要があると考えております。引き続き、東京都ですとかGovTech東京、他区の動向を注視しながら、区民の利便性向上ですとか有効性を勘案しながら。","voiceIndex":81,"id":"exchange-013"},{"speaker":"山本委員","kind":"質問・要望","question":"ご回答、それぞれありがとうございました。庁舎跡地のところは理解をいたしました。最後、１点、委員会の人数のところについては、ぜひ多くの区民が注目するこの跡地活用ですので、相応の人数の委員会としていただきたいという要望です。理解をいたしました。令和７年度までに全てというのが間に合わないとしても、優先度をつけて区民ニーズが高いところですので、進めていただきたいと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-014"},{"speaker":"筒井委員","kind":"質問","question":"私から１点、政策評価のところで、今年度は評価対象分野、地域社会ということですけれども、令和５年度は防災・強靱化、環境ということで、具体的にイメージがつきやすかったと思うのですが、今回、地域社会というとかなり抽象的な表現というか項目になると思いまして、具体的にどのようなことを取り上げていくのか、現時点で分かる範囲で教えてください。","respondent":"吉岡政策推進担当課長","answer":"地域社会ということで、一言で書かせていただいているのですけれども、地域、大学、商店街ですとかＮＰＯといったところの連携事業といった部分を事業としては評価をしていくといったところで、地域がどうつながっているか。","voiceIndex":89,"id":"exchange-015"},{"speaker":"新妻委員","kind":"提案","question":"ただいまご説明がありました、ちょっと期間が延びましたということなのですけれども、職員提案制度、今年度もプレス発表でも確認をさせていただきまして、何点か職員の提案が実現されておりまして、現場で本当に区民の声を聞きながら業務を行っている職員の皆様こそ、いろいろな改善をしていく必要があるのではないかというのが、一番よく分かっていることと思うのですが、日常の業務の中でも。","respondent":"岡秘書担当課長","answer":"ですので、所管のほうでその事業提案に対しまして、予算編成、どういったお金がかかってというところをもう一度検討しまして、その後、財政課のほうに出して、その後、区長査定を経て、予算要求をするという流れになっておりますので。","voiceIndex":92,"id":"exchange-016"},{"speaker":"新妻委員","kind":"提案","question":"ありがとうございました。予算化につきましては、スケジュールを追って、予算化になっていくということなのですが、提案があったもの全てが予算化されますように、そこのこともまた職員とのやりとりもしていただきながら、よい案につきましては、ぜひ実現に向けて進んでいくようにお願いをしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":94,"id":"exchange-017"},{"speaker":"石田（秀）委員","kind":"提案","question":"これは１つだけお願いしておきます。それはどういうことか。これを提案できる人というのは多分、５人はいない、日本に。３人ぐらい。次、１つは、これは委員長にお伺いだ。この前、議会改革推進会議で、「世田谷区の庁舎を見にいきましょう」という話が、私が聞き間違いでなければあったと思うのだけれども、これは新庁舎をやろうとしたときに、ここでは行くとかいう話にはならないのですかという質問だけ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":95,"id":"exchange-018"},{"speaker":"つる委員","kind":"質問","question":"それとも、連携して、そこの部分は切り出しでやっていくのかというのをまず教えてください。","respondent":"西澤ＤＸ戦略担当課長、田口人材育成担当課長","answer":"そのために、職員が効率的かつ効果的にデジタル技術を使いこなして、職員の業務効率化と区民の利便性向上を図っていけると考えておりまして、デジタルツールの活用に関しては、デジタルＤＸ推進担当のほうで実施すると考えております。こちらのほうはＤＸを庁内で進めるに当たって、やはりベースとなる知識がないと、導入がなかなか浸透していかないというところがありますので、そのＤＸ、ＩＣＴに関する知識を底上げしていくというところが。","voiceIndex":99,"id":"exchange-019"},{"speaker":"つる委員","kind":"確認","question":"分かりました。ウェルビーイング・ＳＤＧｓ推進ファンドのところですが、先ほど来、評価を含めて、これは公明党としても当然、全体の取組、そして今回のファンドを活用してのというところは非常に評価をしているところです。ちょっと確認ですが、答弁の中では、寄附的なという「的な」とついていて、ただ、最後のほうに委員のほうから、将来的にはリターンも期待できるようなことも検討してもらいたい。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"先ほどの答弁と重複いたしますが、あくまでこちらは目的としているのが地域課題・行政課題の解決ですので、出資企業へのリターンですとか、あとは運用益を出すというところは、現在は考えておりません。将来的なリターンというところも現在については考えておりません。","voiceIndex":102,"id":"exchange-020"},{"speaker":"あくつ委員","kind":"質問","question":"ちょっと説明の仕方をもう少し工夫をされたほうが、ファンドという言葉、今回モデルを選ばれる際にプレゼンをされたということですけれども、分かりやすくするためにそうしたのだと思うのですが、そこら辺の説明をもう少し工夫されたほうがよいかと思いますけれども、いかがでしょうか。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"もちろんファンドの英語の言葉の意味としては、資金ですとか基金というところがございまして、今回このファンドという名称を私どもが使いましたのも、いろいろな民間企業、区だけではなくて、いろいろなところから資金を調達いたしまして。","voiceIndex":106,"id":"exchange-021"},{"speaker":"つる委員","kind":"質問・要望","question":"ごめんなさい。ちょっと自分が投げかけたもので、ちょっと質問したいのですが。元金融のプロの方がいらっしゃって、言葉のというところもありました。先ほどのそういう無形のリターンのお話がありましたけれども、対価を受け取らない方法については、「ファンドレイジング」と呼びますとかという金融のネット情報ですけれどもあるわけです。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":110,"id":"exchange-022"},{"speaker":"せらく委員","kind":"質問","question":"私からは、ふるさと納税について、少しお伺いしたいと思います。本日、頂いた資料で、流出・流入額の推移というところがあるのですけれども、こちらは品川区のホームページにもふるさと納税のページがございまして、流出・流入、件数と金額が書かれているのですが、ちょっと流入のほうが頂いた資料と誤差があるようなのですけれども、こちらについて教えていただけますか。","respondent":"吉野税務課長","answer":"実際には、事務事業概要のほうでも記載しておりまして、その中で一応、今回のふるさと納税部分とそれから一般の寄附部分を含めて記載しています。","voiceIndex":112,"id":"exchange-023"},{"speaker":"せらく委員","kind":"質問","question":"一般の寄附部分とふるさと納税分を合わせたものがホームページに記載をしているということでしょうか。","respondent":"吉野税務課長","answer":"ふるさと納税部分なのですけれども、こちらは子育て応援課の応援プロジェクト部分と、ふるさと納税の部分、それから一般の寄附分という形で載せていただいております。","voiceIndex":114,"id":"exchange-024"},{"speaker":"せらく委員","kind":"質問・要望","question":"分かりました。その部分も区民として、問題意識を持っていただきたいというお考えがあるのかを含め、ホームページ以外でもこういったふるさと納税の流出について、区民にお伝えしている手段がもし今、ありましたら、教えてください。","respondent":"吉野税務課長","answer":"現在はホームページしかないのですけれども、今後、その点に関しまして、方策等を考えていきたいと思います。","voiceIndex":118,"id":"exchange-025"},{"speaker":"せらく委員","kind":"質問・要望","question":"分かりました。広報戦略課のほうともご協力していただきまして、そういったよりよい方法で伝えたり、ふるさと納税に貢献できるような方策を考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":120,"id":"exchange-026"},{"speaker":"西村委員","kind":"提案","question":"概要ということで、１点だけお伺いしたいと思います。職員提案制度のほうが、管理職を除く全職員ということで、なかなか募集がまだもう少しというところだったのですけれども、研修に関しても、全ての職員の方が受けられるようになっているのだろうとは思いますので、併せて伺えればと思います。","respondent":"田口人材育成担当課長","answer":"それとは別に、特別研修としまして、手挙げで自分が伸ばしたいスキルを伸ばせるようにということでセレクトできるような研修についても設定をしております。管理職についても全て含まれていますかということですけれども、管理職についても同様に含まれております。","voiceIndex":122,"id":"exchange-027"},{"speaker":"西村委員","kind":"提案","question":"職員研修のほうがインプットであれば、職員提案制度はアウトプットかと思っておりまして、風通しのよい庁内を目指していただきたいと思うのですが、やはり通常の業務にプラスアルファで研修が入ってこられていると思いますので、メンタルケアのほうも同時にしていただきながら、例えばハードクレーム対応研修とかですと、今、ニュース報道などでも話題になっておりますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":124,"id":"exchange-028"},{"speaker":"山本委員","kind":"質問・要望","question":"先ほどの調査事項概要の質疑のときにもお話しさせていただきましたが、東京都が進める仮称「Tokyo Tokyo Point」については、全庁的に進める施策というところもございまして、現状はまだ都から詳しい情報が出ていないというところですけれども、出てきた際には、こちらの行財政改革特別委員会のほうでテーマとして挙げていただくことを要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":127,"id":"exchange-029"},{"speaker":"のだて委員","kind":"質問・要望","question":"これまでもやられていると思うのですが、今回も委員からテーマが様々ありますので、今後の１年間の日程等、組んで出していただければと思いますので、よろしくお願いします。それと先ほどもどこか視察にいくとかという意見がありましたけれども、そういったことも審議を深めていくために取り入れていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":129,"id":"exchange-030"},{"speaker":"あくつ委員","kind":"質問・要望","question":"先ほど石田秀男委員からありました庁舎の視察というところで、世田谷区というのも一つだとは思うのですけれども、同じところへ行っても、メンバーがかぶるところもあるでしょうし、新たな知見を得るというところで、別のところの庁舎を見るという手段もあるのかなと。視察はぜひ行かせていただきたいなと思うので、ご調整をお願いできればと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":131,"id":"exchange-031"},{"speaker":"筒井委員","kind":"質問・要望","question":"庁舎の見学については、２３区以外でも近隣のところとかでもいいのかなと。様々な選択肢を広げていっていただきたいと思います。先ほど山本委員からもありましたけれども、「Tokyo Tokyo Point」については健康イベントとかとか様々、本当に全庁に関係するところですので、ぜひこの委員会で取り上げていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":135,"id":"exchange-032"},{"speaker":"せらく委員","kind":"質問","question":"先ほど、議会改革推進会議のほうで世田谷区に行かれるということでお話があったのですけれども、会派によっては所属していなかったり、行財政改革特別委員会だけ所属していたりすると思うのですが、同じ認識を持って話をしていく中では、そういった別の会議体の視察にも参加できるような形に、有志というか任意にしていただけたら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":137,"id":"exchange-033"},{"speaker":"石田（秀）委員","kind":"意見","question":"今の委員長の感覚で結構です。だけれども、今までの例でいうと、議会改革とか広報とか、あれはまた全然違った意味の諮問機関だから、それとこの行財政改革特別委員会と今、そこでリンクがあるからどうという話は、今まで１回もない。そういうのも含めて、制度的にどうしたらいいというのもあるかもしれないので、それだけはお願いしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":139,"id":"exchange-034"},{"speaker":"あくつ委員","kind":"提案","question":"関連してです。これは東京都ですけれども、都有地の活用ということで、先ほど石田秀男委員からの質問にあったような活用の仕方もされていると。いわゆるデベロッパーがいろいろな提案をされた中で、そういったものを都有地、中にはマンションもありますけれども、そういったところ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":141,"id":"exchange-035"},{"speaker":"山本委員","kind":"意見","question":"視察についてですけれども、当会派も新庁舎整備に関する視察は賛成でございまして、具体的には例えば中野区とか、それから少し前かもしれませんけれども、横浜市の市庁舎なんかが参考になるのではないかと考えております。それから先ほどあくつ委員がおっしゃった庁舎跡地の視察についても、ぜひ、可能であれば、実施して知見を深めたいと考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":142,"id":"exchange-036"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6729#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":40275,"voices":143}},{"id":"r06-20240612-19","meetingId":"r06-cm06","date":"2024年6月12日","dateIso":"2024-06-12","committee":"災害・環境対策特別委員会","time":"午後 １時００分～午後 ２時１９分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"ゆきた副委員長","kind":"意見","question":"副委員長の、ゆきた政春です。１年間どうぞよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":3,"id":"exchange-001"}]},{"id":"topic-02","title":"調査事項概要","agenda":"調査事項概要","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それと、あと先ほど最初の説明のところで、地域防災計画のところで教訓も取り入れていくとおっしゃっていて、本当に様々な各大災害から学ぶことというのは大切だと思いますし、それが命を救うということにつながりますけれども、やはり避難所の状況を見ても、１９９５年の阪神・淡路大震災における避難所と同じような光景が能登でも繰り返されているということが多々言われていますので。","respondent":"平原防災課長","answer":"女性職員は単に数が増えているというだけではなくて、防災課の中で女性職員のみで防災を考えていただくという集まりをやっておりまして、そういった中からまた出てきた意見を次の施策として取り入れるということを今進めているところです。","voiceIndex":31,"id":"exchange-002"}]},{"id":"topic-03","title":"今後の委員会運営","agenda":"今後の委員会運営","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"福祉避難所も４割が開設できなかったということになっているのですけれども、開設できないかもしれないという想定はあるのか伺いたいと思います。","respondent":"平原防災課長","answer":"避難所を開けなかったということの想定ですけれども、区の場合には５２の区民避難所のほかに補完避難所という形で、例えば区民避難所が定員がいっぱいになってしまいました、あるいは開けませんでした。","voiceIndex":34,"id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうしたら今度、環境のほうに行きたいと思うのですけれども、今ご説明いただいて、ＣＯ２の排出量の計算というのは、そもそもどういうふうにするものなのか伺えたらと思うのですけれども、それと、オレンジで塗ってある、家庭部門、業務部門、自動車部門のところで、やはり家庭部門の削減量が少し少ないというところが見えるのですけれども、これはやはり、頑張っているけれども。","respondent":"中西環境課長","answer":"その時世時世によって変わってくる部分はあるのですが、一応そういったことが考えられるかなと考えているところです。","voiceIndex":36,"id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"分かりました。そして、２０３０年までというと、あと６年ですよね。それで、もう半分までというのが、見通しが、すごく頑張らないといけないのですけれども、それをどのように頑張ればというイメージがつくようなものがあれば伺いたいと思うのです。","respondent":"中西環境課長","answer":"環境課としても、できることとすれば、区民の皆様、事業者の皆様に行動変容をどのように促していくかといったところが非常に大きなテーマになってくるところですので、例えば東京都の家庭の省エネパンフレットなどでも、例えば「温度を２８度設定にすると。","voiceIndex":38,"id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"意見","question":"行動変容というところでは、私たち一人一人というところでもあると思うのですけれども、やはりこれ以上の超高層再開発を検討していかなくてはいけないのではないかというところまで来ていると思いますし、大本の部分での、やはり企業等が出すＣＯ２等です。以上です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":40,"id":"exchange-006"},{"speaker":"こんの委員","kind":"確認","question":"食品ロス削減推進法が２０１９年に策定されて、そこには、地域の特性に応じた施策を策定することを自治体の責務としているということがあると思うのですけれども、そうなると、今ここに書かれていることは品川区として進めているのですが、法に照らして計画など立てていくというお考えは、品川区としては今どういう状況になっていましたでしょうか。確認させてください。","respondent":"中西環境課長","answer":"食品ロスに関します計画といったところですが、そのものずばりという計画は立ててございませんが、品川区環境基本計画の中で、進捗管理指標などといった中で、例えばフードドライブに協力してくださった区民の方を増やしていきましょうといったことに関しましては。","voiceIndex":41,"id":"exchange-007"},{"speaker":"こんの委員","kind":"確認","question":"そうすると、その中にうたっているということなので、特段これを取り出してということではなく、その中でという理解でよろしいのかというのが確認と、そうなると、よりこれを推進していくというところを、今後の特定事件調査の中で、資料を出していただきながら進めるということになるとは思うのですけれども、その辺、今の段階はやはり啓発から具体に、フードドライブ等々。","respondent":"中西環境課長","answer":"“もったいない”推進店の拡大というものもこれから図ってまいりたいと考えておりますので、そちらを進めながら、推進店の皆様にも様々、例えばドギーバッグを使った効果といったところのお話も伺いながら、今後どういう展開をしていったらいいかといったところは。","voiceIndex":43,"id":"exchange-008"},{"speaker":"須貝委員","kind":"質問","question":"防災のほうでお聞きしたいのですが、能登地震があって５か月、もうすぐ６か月に近づいているのですけれども、いまだに新聞・テレビで報道しているのですが、解体が依然、進まない。そういうことは一体、どういうふうに区として考えられているのか。東京都で考えることなのかもしれませんけれども、私はその辺の考え方をお聞きしたい。どんな状況か、避難道路が安全かどうかも分からない。","respondent":"平原防災課長","answer":"災害時といいながらも、もちろん私有財産ですので、本来は自己責任という形にはなるのですけれども、それでは、委員ご指摘のとおり、復興が進みませんので、全壊判定、大規模半壊で、それは公費解体の対象となるということを積極的に進めて。","voiceIndex":45,"id":"exchange-009"},{"speaker":"須貝委員","kind":"質問","question":"そうしたら何もできないのだと。私がしつこく地震保険も言いました。それで、今現在、全て逆行しているではないですか。そうですよね。でも、結局、大口の鉄鋼や、車もそうですけれども使うところ、大口のＣＯ２が減らない限りは、これはなかなか改善は難しいのではないですか。努力はしているのは我々が見ても分かるのですが、実際、大丈夫なのですかということを、もう一度、ご見解をお聞かせください。","respondent":"中西環境課長","answer":"そういった中で、大口の鉄鋼の産業といったところでも、今、研究についたところではありますが、水素エネルギーを活用した電力を使ったりといったところの、新しい、いわゆるメタネーションといいましょうか、技術革新といったところが進んでおるのかと思ってありますので。","voiceIndex":47,"id":"exchange-010"},{"speaker":"須貝委員","kind":"質問","question":"本当に一生懸命取り組んでおられると思います。だけど国が何で、ＣＯ２削減をやれと言っているのでしょう。やれと言うのにお金はくれない。「何か間違ってはいませんか」と思うのです。リニア新幹線も、たまたま記事があったので読んだら、今の新幹線の４倍の電力を使う。これは何か間違っていないのですかと、私は思ってしまうので、すみません。これは見解だけで、今日はこれでやめます。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-011"},{"speaker":"まつざわ委員","kind":"質問","question":"これはあくまでも町会・自治会でやるものですから、なかなか区がどう入っていくのかというのは難しいというのは、もう何回も答弁して分かっているのですけれども、ここはやはり地区防災計画に、ある程度、初めから入れ込んで、町会・自治会でやるのは分かっているのですけれども、やはりそこは３１％と女性職員が増えていくならば、てこ入れをして、例えばモデル地区をつくるではないですけれども、一回。","respondent":"平原防災課長、伊藤災害対策担当課長","answer":"在宅避難と避難所の施策の関係ですが、在宅避難を中心に据えたというのは、基本というような形で考えているのですけれども、あくまで割合的なところもあるのと、これまでの沿革で、避難所避難に重きを置いたことに伴って。委員のご質問にございました、消防団の自主防災組織への加入ということなのですけれども、まず例年９月から１１月まで実施しています地域の総合防災訓練ですけれども、やはり過去のアンケートにおきましても、人命救助や消火訓練等々は。","voiceIndex":51,"id":"exchange-012"},{"speaker":"吉田委員","kind":"質問・要望","question":"要配慮なので、もしかして厚生委員会マターになるのかなと思いましたけれども、その辺について確認させてください。それの進捗状況というのも、この環境に関することの中に入ってほしいと思って伺うのですが、もし入っていないのだったら、後の次の項目のところでぜひ取り上げてほしいという要望を出さなくてはいけないので、その辺について確認させてください。","respondent":"平原防災課長、中西環境課長","answer":"避難行動要支援者に関する避難についてですけれども、今回の切り口、在宅避難、避難所と大きく２つ書かせていただきましたが、これは避難の場所の問題ですけれども。事業者の環境経営に向けた支援といったところかと思います。","voiceIndex":56,"id":"exchange-013"},{"speaker":"高橋（伸）委員","kind":"提案","question":"ご説明ありがとうございました。防災に関することなのですけれども、これは確認です。これは毎年１回やっているのですけれども、今年は荏原第五中学校からのご提案で、「授業中に有事が起きた」を想定して、同時に、初めてなのですけれども、引き取り訓練をやります。これは初めての試みなので、どうなるか分からないのですけれども、初めて学校側からそういうご提案がありました。","respondent":"平原防災課長、中西環境課長","answer":"教育委員会との協議ですけれども、冒頭でご説明させていただきました品川区地域防災計画の大規模修正を受けまして、区職員の動きを定める災害時業務マニュアルというものの再整備を今進めているところです。今後、“もったいない”推進店を拡大していく中で、どのように打ち出していくかといったことも含めまして、私どものほうで検討させていただきたいと考えております。","voiceIndex":60,"id":"exchange-014"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"どうもありがとうあります。そこをぜひ一回、きちんと精査していただきたいというのが私の要望で、以上とさせてもらいたいと思います。環境なのですけれども、１５６店舗あって、今年度は目標値としてどれぐらいの店舗というのを考えているのか、１点だけお知らせいただきたいと思います。","respondent":"中西環境課長","answer":"目標値といったところですが、できる限り増やしてまいりたいとは思ってありますが、１つ目標としては、できることならば１００店舗ぐらいは増やしてまいりたいと考えています。","voiceIndex":63,"id":"exchange-015"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"塚本委員","kind":"質問・要望","question":"それから環境のほうでは、いわゆる二酸化炭素、ＣＯ２の削減でいくと、表１でいくと、家庭がなかなか成績が低いというところで、一方で表２のほうの助成事業でいくと、家庭用で出ている助成のいろいろな、エコジョーズや蓄電池システムなど、実績が予算より物すごく上がっていて、この辺のギャップというのですか、助成はがんがん家庭用に進んでいて、だけどＣＯ２はあまり下がっていないみたいなところの。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-016"},{"speaker":"ひがし委員","kind":"質問・要望","question":"先ほど吉田委員からもありましたが、高齢者、障害者、そして乳幼児などの要配慮者に対する支援のところで、要配慮者支援計画や個別の支援計画というところは、しっかりとこの防災の委員会の中で、進捗の共有と、あと仕方などについても詳しく説明をしていただきたいと思いますので、その点を要望させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-017"},{"speaker":"鈴木委員","kind":"意見","question":"これからの取組のところなのですけれども、もしも、いろいろ計画を組んだときに、ゆとりがあったらというところでいいのですけれども、以前に東京ガスの災害対策などというので、見学に、視察に行かせていただいたり、それから、災害時の給水拠点というところで、戸越公園の給水の施設を視察に行ったときがあるのですけれども、そういうのは随分前に行ったところなので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":71,"id":"exchange-018"},{"speaker":"こんの委員","kind":"質問・要望","question":"もう一つ、防災訓練のほうは、先ほど地区単位の防災訓練といったところのご説明がありましたが、各町会で、それとは別に、いろいろな町会独自でやっている、町会の皆さんとコミュニケーションを取るという目的と防災訓練を抱き合わせにしているところもあったりするので、そういう町会の防災に関する意識が結構、何というのでしょうか、温度差があるので、町会で独自でやっている防災訓練の状況なども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-019"},{"speaker":"須貝委員","kind":"質問・要望","question":"大半は区有施設とか、そういうところで収容するのでしょうけれども、それ以上の方が出たときに、ここに行けば助かる、ここに行けば住める、ここにいれば当面大丈夫だというような場所を確保していただきたいということを、取り上げていただければありがたいと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-020"},{"speaker":"まつざわ委員","kind":"質問","question":"先ほど鈴木ひろ子委員もおっしゃっていましたけれども、視察というのですか、無理に遠くに行くこともないのかなと思っているのですけれども、例えば２３区首都直下地震で同じようなことが起こる東京都において、他地区のそういう状況を見るというのはすごく勉強になるのかなというのは、聞いていて思いましたのと、例えば私自身が災害コンテナやトレーラーハウスというものにすごく興味があって。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6731#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":27613,"voices":82}},{"id":"r06-20240614-10","meetingId":"r06-cm06","date":"2024年6月14日","dateIso":"2024-06-14","committee":"議会運営委員会","time":"午後 １時００分～午後 １時４０分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を8件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"議長会への要望事項","agenda":"議長会への要望事項","exchanges":[{"speaker":"こしば委員","kind":"質問・要望","question":"順番に説明します。１つ目のふるさと納税に関する要望。寄附金の減少分を補填するための安定した財源確保を求めます。特別区が自らの地域活性化をできるよう求めます。続きまして２つ目、少子化対策及び子ども・若者支援に対する要望です。３つ目、トイレトレーラー・災害コンテナに対する要望です。東京都には、別途、特別区にトイレトレーラーを各区に１台設置することを求めます。最後に６つ目です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-001"},{"speaker":"こんの委員","kind":"質問・要望","question":"１つ目が、介護人材に関する要望です。２点目です。居住支援に関する要望です。こちらは入居を断らない住居の対策を求めて、その要になる居住支援法人、こちらへの支援、安定した活動が担えるように支援の充実を図っていただきたい、こういう内容の要望です。防災対策に関する要望です。国と都に求めたいと考えています。この対策として、トイレトレーラーの配置促進など、こうしたものを求める要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":8,"id":"exchange-002"},{"speaker":"山本委員","kind":"質問・要望","question":"国と都へ合わせた要望が７件、国のみへの要望が１件、合計８件となります。紛争や円安等に起因する物価高騰が続いており、国民の暮らしと事業者の経営や雇用を守るため、十分な財政的支援等５つの具体事項を要望しております。続いて、スポーツ振興に対する要望です。対象地域の皆様の安心・安全な暮らしを守るため、検討会での検討内容の開示、新ルートの見直し等４項目を要望しております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"これはやっぱり、議会ごとにどういう共通要望を出していくかというのは非常に重要な議論だと思っていまして、議会の審議というか、検討の過程の見える化にもなりますし、結構苦労してそれぞれの会派も作っているので、ぜひそれは改善していただきたいなというふうに思いますので、ぜひ正副で検討していただければと思います。これは要望です。新たな追加点などを中心に説明したいと思います。最後になります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":10,"id":"exchange-004"},{"speaker":"須貝委員","kind":"質問・要望","question":"最後に、全国市議会議長会を通じて行う要望として、首都直下大地震が近々に起こる可能性が高いので、大地震や大火災等が発生した場合に、区民を支援する職員が区内にとどまれるような大きな施設、そして２番目に大量の避難民が生まれた場合に、区民が一時避難できる施設、そして３番目に感染症などが流行した場合に、病人隔離所として利用できる施設。","respondent":"まつざわ委員長","answer":"それぞれご説明ありがとうございました。維新および無所属からは、期日までに提出はございませんでした。ご意見があれば、お願いいたします。","voiceIndex":11,"id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"ほぼ全ての会派から出されている、例えば学校給食無償化や、１８歳までの医療費の無償化への財政措置や、介護士の処遇改善などについては、これはかなり共通しての要望として上げるべきなのではないかと思いました。そのほか、出産費用や学用品等の無償化や教員不足の解消、あと保育士の待遇改善なども共通して上げられている要望かなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-006"}]},{"id":"topic-02","title":"令和６年第２回定例会","agenda":"令和６年第２回定例会","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"無所属議員から辞退の申し出とあったのですけれども、これはその方の質問は、今後、今年度の違うところに移るのか、それとも今年度はなしということになるのか、その扱いだけ教えてもらいたい。","respondent":"大澤区議会事務局長、あくつ副議長","answer":"無所属議員の中で順番をあらかじめ決めておりましたので、今回辞退ということで、延期はございません。議会運営委員会、様々な場所等で一般質問というのは我々区議会議員にとって権利であって、義務とまでは言えないのかもしれませんけれども。事務局として正式に理由をお聞きしているわけではございませんので、この場でのご説明は控えさせていただきたいと思います。","voiceIndex":19,"id":"exchange-007"},{"speaker":"須貝委員","kind":"質問・要望","question":"今回やりませんと、やりたくないからやりませんというのだったら、では何のためにここにわざわざ大勢皆さんが集まって、これでどうですか、こういうふうに行きますよというのを決める必要もなくなりますよね。それは過去の、２年前、３年前のことがあったので、私はそのときに、再度襟を正してきちんとやるものなのだなということを認識したので、一応意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-008"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6733#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":13589,"voices":38}},{"id":"r06-20240626-10","meetingId":"r06-cm06","date":"2024年6月26日","dateIso":"2024-06-26","committee":"議会運営委員会","time":"午前１０時３０分～午前１０時４８分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を5件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"議長交際費の支出基準の改正のことなのですが、幾つかお伺いします。現在でもやってはいると思うのですが、現在の公表内容がこの規定によって仕方とか公表が変わるのか、そこを２つ目としてお伺いします。","respondent":"渡辺議長","answer":"改正後には、ホームページで公表するというのが今まで記載されていなかったので、まず載せさせていただいたというところです。それと、内容については変わりないという形で、これまでも全て全額公表ということでやっていますので、それに倣ってという形になります。","voiceIndex":16,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"公表のところは了解しました。あえてその改正前に比べて支出基準が緩くなったのか厳しくなったのか、変わったのかというところはお答えいただきたいのと、もし変わらないとしたら、今回基準を変更した理由がよく分からないのですけれども、根本的なところなのですけど、今回基準を変更した理由を改めてお伺いしたいと思います。","respondent":"渡辺議長","answer":"厳しいかどうかは継続性なので、これまでもやはりかなりオープンに、全てオープン情報ということを心がけてきている流れがありますので、それに沿っていると思います。","voiceIndex":18,"id":"exchange-002"},{"speaker":"安藤委員","kind":"意見","question":"公開のところは、どなたが議長になってもこういうふうに改正にきちんと入れることでそれが担保されるという点はすごくいい改正だと思います。内容については、運用しながら、これから、これまでもやっておられたということですので、今まで以上に議長の交際費というところに注目して、私たちとしても注視していきたいなと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":20,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"廃案または慎重な運用を求める意見書を上げた地方自治体も幾つか出てきているということで、以上のことから、品川区議会でも一致できる点で何らかの意見書を提出すべきではないかなという思いが今私どもにありまして、ちょっとお伺いしたいのですが、７月１０日に最終本会議がある、まだ時間もまあまああるということで、意見を交換して検討しながら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"案文自体を具体的にここでたたくということではなく、そういう動きを区議会として検討していく必要があるのではないかという方向性について、皆さんのご意見があれば伺わせていただければということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-005"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6735#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":6505,"voices":39}},{"id":"r06-20240701-6","meetingId":"r06-cm07","date":"2024年7月1日","dateIso":"2024-07-01","committee":"区民委員会","time":"午前１０時００分～午前１０時４６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第４５号議案、令和６年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"第４５号議案、令和６年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今回補正予算ということで、本予算ではなく補正予算で組んだ理由があれば伺いたいのが１点と、それとインクルーシブコンサートですけれども、裏面を見るとＯｎｔｅｎｎａ啓発ブースという表記になっていて、どういうイメージなのかというか、自由に健聴者の方もつけてステージに参加するようなイメージなのか、それとも、事前にそういう方も含めて練習して披露するものなのか。","respondent":"三井スポーツ推進課長、大森文化観光戦略課長","answer":"今回、デフリンピックの認知度向上の事業の追加ということで補正予算を上げた理由になりますが、まずきっかけとしては、都の補助金の上限が上がったということと、補助率が上がったということがございまして。各会場のホワイエにＯｎｔｅｎｎａの貸出ブースを立てまして、そちらで貸出しの個数が、こちらの資料に５０台から１００台ということで、業者のほうから、その日の使用の予約状況によって。","voiceIndex":6,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"分かりました。勘違いしていました。スポーツ推進課としては、来年のデフリンピックをきっかけに、聴覚障害をお持ちの方自身がスポーツをできる環境を整えるということも重要なのではないかと思うのですけれども、その辺は、担当課としてはどう考えていらっしゃるのか伺いたいと思います。","respondent":"三井スポーツ推進課長","answer":"１点目の、聴覚障害のどんなところについて理解を深めていくのかということで、これは障害者支援課とも連携していく話になるのですが、区のほうで、皆さんご存じのとおり、手話言語条例も制定されていますので、手話言語ということで、そちらについて、まずは。","voiceIndex":9,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"最後、仮囲いアートについてお伺いしたいのですけれども、現在想定している工事現場は何か所ぐらいで、２００万円という予算ですけれども、どの辺なのか、具体的にもし検討しているところがあれば伺いたいのと、オリパラ時はこういったアートというのは、例えば庁舎の壁に掲出していたと思うのですけれども、どうせなら区有施設など、ある程度恒久的な、長く掲示できるところに。","respondent":"大森文化観光戦略課長","answer":"区有施設の壁面、オリンピックのときに庁舎につけた経緯もあるということですけれども、足場を組んだりとか、あと、スケールが大きくなっていくと、どうしても予算の面でも負担がかかるというところもあるので、そういったところが解消されていけば。","voiceIndex":11,"id":"exchange-003"},{"speaker":"ゆきた委員","kind":"確認","question":"インクルーシブコンサートの実施について、（２）の広報・啓発活動では、啓発ブースに啓発グッズとありますが、ここには（３）で紹介されているＯｎｔｅｎｎａも入ってくるのかというのが１点と、先ほど導入の形態で、リースということでお話があったと思うのですけれども、再確認で、事前に予約を取って台数を確認して、導入台数が決まるという認識でよろしかったでしょうか。","respondent":"三井スポーツ推進課長、大森文化観光戦略課長","answer":"初めに、（２）の広報・啓発活動の啓発グッズについてですが、こちらには、Ｏｎｔｅｎｎａは含まれていないという状況になっておりまして、基本的には今、まだこれからになりますが、想定ではメモ帳等を想定しているところで。Ｏｎｔｅｎｎａの貸出しにつきましては、事前予約ではなくて、その場で啓発しながら、興味をお持ちいただいた方に、先着という形にはなってしまうのですけれども、貸し出していくという形で考えてあります。","voiceIndex":14,"id":"exchange-004"},{"speaker":"ゆきた委員","kind":"意見","question":"さらには、区有施設とか、スクエア荏原とか、あと、区役所の中に常設の、期間限定でも啓発できるような展示もしていければ、区の発信する側からも、常に啓発していくということにつながると思われますので、そういったことも考えていっていただければと思いますが、最後に何かあればお願いします。","respondent":"大森文化観光戦略課長","answer":"Ｏｎｔｅｎｎａの貸出しにつきましては、業者が持っていて、区で持っているわけではないのですが、業者が持っている個数が１００と言われているところがあるので、イベント等がかぶらなければ、最大、イベントで１００個を貸し出していただける形になるので。","voiceIndex":17,"id":"exchange-005"},{"speaker":"おぎの委員","kind":"質問・要望","question":"来年デフリンピックが行われるということで、どの程度の進行で進んでいるのか分からないので、分かる部分があったら教えていただきたいのですが、まず、競技が幾つかあると思いますが、会場は品川区の会場を使う予定になっているのでしょうか。","respondent":"三井スポーツ推進課長","answer":"会場ですが、残念ながら、品川区は会場がない状態になっています。近くで言うと大田区とか、そちらに会場があるということを聞いております。","voiceIndex":19,"id":"exchange-006"},{"speaker":"おぎの委員","kind":"質問・要望","question":"アートのところでは、子どもの絵とかもあったらいいなと思って、文教委員会のほうになってしまうと思うのですけれども、オリンピックと違ってパラリンピックとかデフリンピックとかは、いかにその障害を克服して、知恵を絞ってやっていくかとか、そういったところが見どころかなと思うので、そういった競技の体験なども子どもたちができたらいいなと考えていますが、いかがでしょうか。","respondent":"三井スポーツ推進課長、大森文化観光戦略課長","answer":"今お話のあった、子どもたちも体験できるようなものがあったらいいということで、毎年、パラスポーツチャレンジデーというものを実施しておりまして、パラスポーツチャレンジデーでは。それとは別で、当然、お子様を巻き込んだ周知啓発というのは考えていきたいと考えております。","voiceIndex":21,"id":"exchange-007"},{"speaker":"石田（し）委員","kind":"質問","question":"これを一つのきっかけとして、ずっと行政の課題と言われている縦割りの部分を取っ払って、一つの事業を横断的に、みんなで取り組む必要があるのかなと思うのですが、この辺というのは現在、部としてはどのように考えて取り組もうとしているのかというのを教えてください。","respondent":"三井スポーツ推進課長","answer":"実際、補正予算の審議をしていただいて、議決されましたら、各部署と連携しながら、先ほども説明しましたが、一応、スポーツイベントはもともと啓発ブースとか、サポーターに来てもらうというのは考えているのですが、それ以外でも出せる区内イベントがあれば。","voiceIndex":26,"id":"exchange-008"},{"speaker":"石田（し）委員","kind":"質問","question":"今のを受けて、区内のイベントの多くは地域活動課か、商業のいわゆる商店会がメインになってくる。この辺というのは担当として、皆さんはどのように考えているのか教えてください。","respondent":"宮澤地域活動課長","answer":"７月開催も多いところですが、９月、１０月に開催する地区もありますので、連携しながら。","voiceIndex":28,"id":"exchange-009"},{"speaker":"石田（し）委員","kind":"意見","question":"ぜひ、まずはここの部で、両方の部でしっかり連携を取っていただきながら、ほかの部ともさらに深めていただけたらと思います。応援していますので。我々もアイデアがあれば、どんどん発信していきたいと思うので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":30,"id":"exchange-010"},{"speaker":"せお委員","kind":"質問","question":"先ほどのＯｎｔｅｎｎａの話に戻ってしまうのですけれども、細かい話でごめんなさい。仮囲いアートですけれども、こちらにいらっしゃる理事者の方たちが知っている範囲でいいのですが、今まで仮囲いアートというのは、何か区で取り組まれたことがあったのかというのをお聞きしたいです。","respondent":"大森文化観光戦略課長、辻文化観光スポーツ振興部長","answer":"Ｏｎｔｅｎｎａは、中途半端な言い方で申し訳ございませんでした。現段階では、９月１日の大ホールでやるほうは、１００台を借りることができるという見込みになっております。東京都はそれまでも、オリンピックのときに仮囲いを使って、かなりやっていましたので、先ほどもお話にありましたけれども、恒久施設ですと、足場を組んだり、かなり大がかりになってしまうということもありますので、そういう意味では。","voiceIndex":32,"id":"exchange-011"},{"speaker":"せお委員","kind":"質問・要望","question":"仮囲いアートも、私は結構以前から障害者のアートとかを、今、部長もおっしゃっていたように、比較的ほかのところにアートを設置するのに仮囲いアートというのは簡便なので、子どもの絵とかもそうですし、障害児者の絵とかも結構目立つので、やってほしいというのは要望していたので、ぜひこれを機にというか、これを区全体に広めていただきたいと、それは要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-012"},{"speaker":"藤原委員","kind":"質問・要望","question":"具体的に教えていただきたいのですけれども、サポーター任命の対象者が、区にゆかりがあり、デフリンピック啓発に発信力のある方となっているのですが、具体的にはどういう方なのですか。","respondent":"三井スポーツ推進課長","answer":"発信力があるというのは、ご自身でもやられていたり、あとはデフリンピックをそもそも理解しているという方も考えているようなところです。","voiceIndex":37,"id":"exchange-013"},{"speaker":"藤原委員","kind":"質問","question":"「区にゆかりがあり」は、区に住んでいるということなのですか。","respondent":"三井スポーツ推進課長","answer":"できれば区に住んでいる方が一番いいのですが、そうすると、大分狭まってしまうので、区在住・在学というのをだんだん広げていって、それでも……。出身も含めて、なるべくまずは区在住から広げていって、何かしら、選定がなかなか難しいとなったら、区に少しでもゆかりのある方という形になるかなと思います。","voiceIndex":39,"id":"exchange-014"},{"speaker":"藤原委員","kind":"質問","question":"よく分かりました。サポーターの方が多く集まってくれるといいですね。私もこの事業に賛成しておりますので、わくわく、そして盛り上がることをこのように期待しておりますので、今日はこれで質問を終わりにします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-015"},{"speaker":"吉田副委員長","kind":"質問","question":"たくさんいらっしゃるといいなと思うのですけれども、どれくらいの方にお願いしていく予定なのか、その辺の選定と、それから、どう想定している人数で、その後、多分、こういうことをお願いしますとお願いするようになると思うのですけれども、その辺のスケジュールといいますか、少し急いだほうがいいかなと思いますので、伺います。","respondent":"三井スポーツ推進課長","answer":"予算上は一応、２人を見込んでおります。ただ、予算上は２人を見込んでおりますが、実際にお願いする方によって、謝礼の金額等は調整、交渉になるかなと思いますので、今後そちらで進めていきたいと考えております。","voiceIndex":44,"id":"exchange-016"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"デフリンピックについては、聴覚障害者協会の方も、長年デフリンピックの誘致ということを求めておられましたし、手話言語条例の制定というところで、品川区としても、いいタイミングかなと思います。ただ、手話は結構難しいというところもありますので、じっくり広げていく必要があると思うのです。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"賛成いたしますが、少し意見を言わせていただきたいのですが、大崎でかなり再開発の相談を受けるのです。かなり反発や異議も出ているところがあります。それは要望として述べしますが、事業全体としては、もちろんデフリンピックは聴覚障害啓発の大事な事業で、目的ですので、賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-018"}]},{"id":"topic-02","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"参考までに、当日、地域センターの庁有車ということですが、何の業務でどこからどこに向かっていたのか、分かれば教えてください。","respondent":"宮澤地域活動課長","answer":"当日、朝になります。地域センターを出発しまして、まず、大崎にある清掃事務所に向かう途中だったところで、事故が発生してしまったです。","voiceIndex":61,"id":"exchange-019"},{"speaker":"安藤委員","kind":"意見","question":"状況とか時間帯とかによって、精神的な焦りとか、いろいろなこともあると思うのですが、あってはならないことですので、今後とも職員の方に徹底、啓発など、よろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":63,"id":"exchange-020"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"前回の委員会で要望させていただいたことなのですけれども、前回の区民委員会があってから今回の区民委員会の間に、この、中小企業の景況という冊子が配られました。そうすると、区民委員会の所管の事務も充実するのではないかと思いますので、まず簡単でよいので、明日、区から報告をしていただけるよう、このタイミングですけれども、委員長にお計らい願いたいのですが、委員長、いかがでしょうか。","respondent":"高橋（伸）委員長","answer":"今ご発言があった内容については、明日というのは、急にこれはできることではないと思いますので、正副で検討させていただき、持ち帰りということで考えていただきたいと思います。よろしいですか。","voiceIndex":68,"id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6751#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":13993,"voices":72}},{"id":"r06-20240701-7","meetingId":"r06-cm07","date":"2024年7月1日","dateIso":"2024-07-01","committee":"厚生委員会","time":"午前１０時００分～午後 ３時０９分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を95件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第５７号議案、品川区小児慢性特定疾病審査会条例","agenda":"第５７号議案、品川区小児慢性特定疾病審査会条例","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"品川で認定されている数と、１年間で新たに認定される数がどれくらいあるかも教えてください。それから、この審査会は、小児慢性特定疾病医療費の申請がされて、医療費の支給認定をしないときに審査会を開くことになると思うのですけれども、それはどれくらいあるということで想定されるのか、伺いたいと思います。","respondent":"五十嵐保健予防課長","answer":"審査会につきましては、基本的には基準が決まっておりますので、ほぼ認定されるものと考えていますが、疑義が出た場合に審査会を設置することになってありますので、１年間に１回か２回あるかどうかぐらいの回数と考えております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木委員","kind":"質問・要望","question":"この医療費の申請がされたときは、基本的に保健予防課で審査をして、認定が基準に合っているよというところはそのまま認定されるということで考えていいのか、そこのところで疑義があるというときに審査会にかかるという仕組みなのかも確認させていただきたいと思います。それなので、この認定を受けるということが、医療費のほかにどんなメリットがあるのか、そのメリットについても伺いたいと思います。","respondent":"五十嵐保健予防課長","answer":"小児慢性特定疾病を申請するメリットにつきましては、現在、マル乳やマル子などがありますので、医療費にお金がかなりかからなくなっているところから、どのぐらいメリットがあるかというところは難しい部分があるかと考えていますが。","voiceIndex":7,"id":"exchange-002"},{"speaker":"鈴木委員","kind":"質問","question":"そうすると、保健予防課で審査する人というのは、何か資格のある人とか、そういうところで審査がされるのか、その点を伺いたいのと、そのことによって新たな業務が増えることになると思うのですけれども、人員の配置というのはあるのか、その点についてもお聞かせください。","respondent":"五十嵐保健予防課長","answer":"審査につきましては、今、雇い上げでお願いしている医師がおりますので、その方にお願いできるのではないかと考えているところです。","voiceIndex":9,"id":"exchange-003"}]},{"id":"topic-02","title":"第４５号議案、令和６年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"第４５号議案、令和６年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"接種率はどの程度で見込んでいるのか。これまでは無料だったのですけれども、それが今度３,５００円の自己負担ということになるので、自己負担のことを考えると、接種率も下がるのかなという思いがするのですが、その辺りは区としてどう想定されているのかも伺いたいと思います。","respondent":"五十嵐保健予防課長","answer":"今までの接種率を考えまして、今まで無料で打っていたときの接種率が大体５０％ということでしたので、今回、５０％の方が接種するということを見込みまして、５０％ということで今回のお金に関しては計算させていただいているところです。","voiceIndex":25,"id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問・要望","question":"自己負担が３,５００円ということなのですけれども、これはこれから三者協で決めていくということで、この三者協というのはどことどこなのか、三者協とは何かというのを教えていただきたいのと、それからあと、自己負担が３,５００円ということなのですけれども、これは２３区統一でいくのか、他区の状況なども分かったら教えていただきたいと思います。","respondent":"五十嵐保健予防課長、阿部品川区保健所長","answer":"３,５００円ですが、他区に関しましては、まだ３,５００円ぐらいかなと言っているところと……。ただ、３,５００円が３,５００円になるのか、３,６００円になるのか、３,４００円になるのかとか、その辺のところはまだ詳細が決まっていないのですけれども。","voiceIndex":27,"id":"exchange-005"},{"speaker":"鈴木委員","kind":"確認","question":"そうしますと、三者協というのは、いつ頃されて、いつ頃決まるのかということと、３,５００円がまだ決まっていないということは、では、その３,５００円も、自己負担が３,６００円になるのか、３,４００円になるのか、そこら辺はまだはっきりと決まっていなくて、三者協で決まったものを品川区の自己負担とするという考え方でいいのか、その点の確認をお願いします。","respondent":"五十嵐保健予防課長","answer":"多少のお金を積んでいらっしゃる区もありますので、そういう区に関しては３定で出すというふうに話を伺っているところです。","voiceIndex":30,"id":"exchange-006"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それからもう一つ、次に子どものインフルエンザワクチンのことなのですけれども、生後６か月から１２歳というのは、何人分で、接種率はどの程度ということで見込まれているのか、また、１３歳から高校３年生相当というところも、何人分で、接種率はどう計算しているのか、伺いたいと思います。そもそもインフルエンザワクチン接種にかかる費用というのは幾らぐらいかかるのか。","respondent":"五十嵐保健予防課長","answer":"１３歳から高校３年生につきましては、４,８００件と考えているところです。今までの接種の形を見させていただいてやらせていただいているところですが、６か月から４割程度の接種をされているので、そのぐらいを見込んでいるところになってあります。","voiceIndex":32,"id":"exchange-007"},{"speaker":"鈴木委員","kind":"質問","question":"そもそもインフルエンザワクチンの接種にかかる費用がどれくらいなのか、あと、自己負担が幾らぐらいになるのかも伺ったので、分かったら教えてください。","respondent":"五十嵐保健予防課長","answer":"小児のインフルエンザワクチンにつきましては、任意接種ですので、必ず幾らというのが決まっているものではございませんが、大体４,０００円、５,０００円ぐらいで接種されているものですので、２,０００円の補助がありますと、二。","voiceIndex":34,"id":"exchange-008"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"高齢者新型コロナウイルスワクチン接種事業についてお伺いしますが、このワクチンは、どこの製薬会社のどういうワクチンなのか、もし分かればお教えいただきたいです。","respondent":"五十嵐保健予防課長","answer":"まだきちんと示されておりませんので、まだそこのところは分かっていないところになってあります。","voiceIndex":37,"id":"exchange-009"}]},{"id":"topic-03","title":"第７０号議案、指定管理者の指定について、および(5)第７１号議案、指定管理者の指定についての２議案","agenda":"第７０号議案、指定管理者の指定について、および(5)第７１号議案、指定管理者の指定についての２議案","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"この施設は、今まで若竹大寿会が１０年間、指定管理者でやってきていただいたところ、人材確保ができず、赤字が続くということで、指定管理者を辞退したいということになって、１０年間という指定管理期間でしたけれども、今回改めて公募という形になったということになると思うのですが、今回の奉優会は、２,８０３名という人員を抱えたすごく大きな社会福祉法人ということなので。","respondent":"菅野高齢者福祉課長","answer":"具体的な人材確保、例えば派遣の方が何人とか紹介業者とかというところまでは踏み込んで確認できておりませんが、一定程度人材確保ができる、１２月から運営をお願いできるというところを提案してきておりますし、こちらのほうも見込んで、お願いした次第です。","voiceIndex":55,"id":"exchange-010"},{"speaker":"鈴木委員","kind":"質問・要望","question":"この奉優会は、北品川ゆうゆうプラザの指定管理も受けられたということで、私たちも開所式に行かせていただいて、施設の理事長とか職員の方とご挨拶とかもさせていただきましたけれども、そのときの区の報告を見ていたら、令和５年４月の段階で２,４２８人だった職員が、１年後に２,８０３人ということで、１年間で３７５人も増えているのですが。","respondent":"菅野高齢者福祉課長","answer":"主に人員のことについてのご質問ということで承らせていただきます。現在の若竹大寿会が公表している当施設における人員体制については、常勤換算で約６０名ぐらいと認識しております。その辺りのことも踏まえながら、各法人、今回提案書を書いていただきました。","voiceIndex":57,"id":"exchange-011"},{"speaker":"鈴木委員","kind":"提案","question":"別のことなのですけれども、今回、若竹大寿会が撤退する一因となったのに、看護小規模多機能型居宅介護があるということでいろいろ書かれていますが、実際にモニタリングでも、若竹大寿会で看護小規模多機能型居宅介護の利用率５０％前後というのはずっと来ていたと思うのですけれども、その中で、医療依存度の高い利用者の受入れの課題だったりとか、重度の方を受け入れるために。","respondent":"菅野高齢者福祉課長","answer":"そして看護小規模多機能型居宅介護と認知症グループホームにつきましては、合わせて看護職員が４人、常勤換算では３.３人ということで配置させていただいておりまして、奉優会につきましても、提案するに当たっては。","voiceIndex":59,"id":"exchange-012"},{"speaker":"鈴木委員","kind":"提案","question":"１２月からこちらの事業所ということになるわけですよね。それと、今回、若竹大寿会が指定管理者を辞退するというところは、人材不足と赤字経営が理由だったということなのですけれども、こういう事態となって、区として、そこを引き継ぐ指定管理者に対しての配慮というのですか、同じような事態にならないための支援というか、そういうところはどのように考えられているのかということも伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"１２月から始まるまでの引継ぎのスケジュール等につきましては、提案の中でも、引継ぎの期間を３つの期間に分けて、例えば最初のところは職員とかの意向確認とか、あとは中期だと、法人の方との備品の整理とか、その辺のやり取りについてとか、あとは。","voiceIndex":61,"id":"exchange-013"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それと最後に、今日の報告書の中で、８ページのところに、それぞれの選考基準に対する候補者の状況というのが点数で書かれているのですけれども、奉優会とほかの事業者、それぞれ項目ごとの点数を出して、その合計がここで報告されている点数ということになるのだと思うのですが、そういうところで、毎回要望として、前も出させていただいたと思うのですが。","respondent":"菅野高齢者福祉課長","answer":"指定管理者の報告書の点数等の内容につきましては、こちらについては、指定管理の基本方針の中で、選定予備委員会や選定委員会の審議内容を取りまとめたものを報告書として公表しておりまして、応募事業者の名称、候補者選定方式・理由、選定委員名簿、会議要旨、評価項目・配点。","voiceIndex":63,"id":"exchange-014"},{"speaker":"鈴木委員","kind":"質問・要望","question":"最後です。今後の検討として、それはぜひ公表していただきたいということで要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-015"},{"speaker":"ひがし委員","kind":"質問・要望","question":"今の説明で、人員確保のことだったりとか、看護小規模多機能型居宅介護を継続できることが確認できて、安心しております。なかなか手を挙げてくれないという最近の状況の中で、４事業者が手挙げをしてくれたということは大変うれしく思っておりまして、４事業者、手を挙げてくれた、今回増えた理由だったりとか、所管で工夫をした点などあれば、教えていただきたいと思います。","respondent":"菅野高齢者福祉課長","answer":"実際に８事業者来て、施設を見ていただく中で、その結果、４事業者に手を挙げていただいたというところで、なぜかというところの具体的なところはうまく説明できないところもあるのですけれども、その結果、いろいろと理解していただいて、提案を出していただけたと考えています。","voiceIndex":68,"id":"exchange-016"},{"speaker":"ひがし委員","kind":"確認","question":"先ほど鈴木委員への答弁の中で引継ぎのお話が出ていまして、まず意向確認をしていくというようなワードがあったと思うのですけれども、こちらは、前回指定管理をしてくださっていた若竹大寿会のときに働いていた方々が、もしそのまま残りたいと希望した場合は、勤務できるように調整していただけるということでいいのでしょうか。","respondent":"菅野高齢者福祉課長","answer":"職員の方の意向確認という部分につきましては、基本的には法人同士のやり取りというところになりますので、区としてはあまり細かいところまではというところはあるのですけれども、ただ、若竹大寿会が次回の指定管理施設、手を挙げないというお話をしたときに、法人からは。","voiceIndex":70,"id":"exchange-017"},{"speaker":"ひがし委員","kind":"質問・要望","question":"神奈川のほうでされているという話を聞いて、品川区で働いてくださっている方々、通勤の問題とかもあるので、できればその環境で働いていただきたいなと思うのと、あと、利用者の目線で考えても、急に全員変わってしまうとやはり心配だろうなと思うので、そこは業者間でしっかりと調整していただけるということが確認できたので、その点について、区でも少しでも関われるところがあれば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-018"},{"speaker":"やなぎさわ委員","kind":"質問","question":"先ほどのひがし委員の質問とも重なる部分があるのですが、今回、４事業者が応募に至ったということで、区としては、多いと思っていますか、少ないと思っていますか。","respondent":"菅野高齢者福祉課長","answer":"多いか少ないかというのは主観的な部分になってしまいますが、公募要項の中では、選定予備委員会と選定委員会があるのですけれども、選定委員会のほうには、選定予備委員会で審査した結果、３者を諮りますとしていますので、何が正解なのか難しいところはありますが、３者。","voiceIndex":74,"id":"exchange-019"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"私もすごくうれしいなと思って、もともと赤字続きだった施設なわけで、令和２年度だと、特別養護老人ホームと地域密着型多機能ホーム合わせて３,３００万円赤字で、令和３年度は３,０００万円で、直近の令和４年度でも１,３００万円赤字という、そういった施設に対して、４者に応募していただけるというのは非常にうれしいことだと思っているので、それで。","respondent":"菅野高齢者福祉課長","answer":"提案につきましては、結果のほうは通知等させていただきまして、特に個別に今後のことについてというようなフォローまでは今のところさせてはいただいておりませんが、今回、鈴木委員からも報告書の書き方についてのお話もありましたが。","voiceIndex":76,"id":"exchange-020"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"先ほどひがし委員への答弁のところで、周知方法を、ホームページ、プラス手紙の送付もしたということで、もしかしたらそういったところが手を挙げた事業者が増えたことにつながったかもしれないと思うので、なぜかというのは正直まだ分からないというお話だったので、今回見学された８者含めて、どうして応募されたのですかとか、そういうようなことを逆に事業者に。","respondent":"菅野高齢者福祉課長","answer":"今回は特に、さらにお手紙を出したというところもあるのですけれども、多分興味を持っていただきまして来ていただいたのかなというところで、結果、詳しい説明や施設の形態を見て、４者になったのかなというところで。","voiceIndex":78,"id":"exchange-021"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":80,"id":"exchange-022"},{"speaker":"筒井委員","kind":"質問","question":"私からは、３ページの会議要旨で、奉優会の財務評価について、「資金の回転状況に問題はないが、利益率の低下が懸念材料」と書いてあるのですけれども、その辺り、今後の見込みとして大丈夫なのかということと、あと、人員が４００人近く急激に増えられたというようなお話を伺ったのですが、奉優会は外国人の方を積極的に採用されているという感があるのですけれども、この定員増の理由は。","respondent":"菅野高齢者福祉課長","answer":"外国人採用の専門部署を設けて、ＥＰＡや技能実習制度を活用し外国人職員の受入れを行っているというところで提案もございましたので、この４００人増えたのがイコール外国人というわけではないと、ちょうど４００で一緒ですけれども。","voiceIndex":82,"id":"exchange-023"},{"speaker":"筒井委員","kind":"質問","question":"利益率の低下、今は別に特段そんなに問題ないという認識でいいのでしょうか。今、ご説明がよく分からなかったので。","respondent":"菅野高齢者福祉課長","answer":"公認会計士の分析の結果を基に、区としては判断しています。","voiceIndex":84,"id":"exchange-024"},{"speaker":"筒井委員","kind":"質問","question":"外国人の人材の件なのですけれども、今、積極的に雇用されているので、それはそれでいいのでしょうけれども、今後、急激な円安で、外国人の方もわざわざ日本で働かなくてもいいというようなことも徐々に起きてくるかと思うので、引き続き、外国人の方が日本に来なくなったときのこともぜひ考えていかなければいけないのかなと思うのですけれども、その辺り、どのように品川区としてはお考えでしょうか。","respondent":"菅野高齢者福祉課長","answer":"外国人人材については、国が円安だというところの、そういった不安材料というのも報道等では耳にしております。一方で、国の審議会等においても、外国人人材の、例えば訪問サービスへの活用についてとか、検討会がいろいろ行われております。","voiceIndex":86,"id":"exchange-025"},{"speaker":"若林委員","kind":"提案","question":"選定委員会の会議要旨、委員の意見の中で、奉優会に関して「苦情解決の方法、情報公開に対する姿勢等についての提案は、一般的な内容に終始する内容となっている」と。この表現は、どういう評価なのでしょうか。","respondent":"菅野高齢者福祉課長","answer":"多分委員が今おっしゃったのが、６ページの委員の意見の一番下の部分、奉優会の一番下の部分かなというところで、会社としては大きな法人というところで、その中で苦情の体制についても、例えば第三者委員を設けるとか、いろいろな体制がとれているというところで。","voiceIndex":89,"id":"exchange-026"},{"speaker":"若林委員","kind":"意見","question":"それで、では、そういうことも含めて、選定予備委員会と選定委員会の最終的な採点、数字ですね、総合点数、それがほかの法人は下がったりしているわけですが、奉優会についてはどちらも３１６点ということで、上がりもしなかったし下がりもしなかったしというところの数字と思うのですが、選定予備委員会と選定委員会の意見が全く、１００％同じということはあり得ないので。","respondent":"菅野高齢者福祉課長","answer":"傾向としては、選定予備委員会は書面の審査だけで、選定委員会のほうが法人のプレゼンテーションとヒアリングがあるというところで、外部委員の方も入るというところなので、どうしても選定委員会のほうが少しからめにというか厳しく点がつくような傾向があるのですけれども。","voiceIndex":91,"id":"exchange-027"},{"speaker":"若林委員","kind":"確認","question":"過去の例からいうと、経験的には逆に点数が上がったなというぐらいの高い評価が得られたと理解いたしました。移行されて、１２月以降、本当に職員の方と利用者の方、それから職員自体の慣れというのか、いわゆる仕事がうまく回っていくという状況になるには何か月もかかると思うのです。そこら辺、区としてはどのような関わりを持ったりするのかというのを最後に確認させてください。","respondent":"菅野高齢者福祉課長","answer":"特に高齢者の施設におきましては、利用者と施設のおなじみの関係というのが、やはり利用者にとってはすごく大事なところだなと認識しておりますので、引継ぎにおいては、先ほど現職員の意向確認とかいう部分もありますが、十分に行っていただきまして。","voiceIndex":93,"id":"exchange-028"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"ぜひ、これは若竹大寿会も含めて、赤字だったということは非常に重く受け止めていただきたいなと思っています。これはもう何度も言っているのだけれども、要は、民間でやろうとしたら、家賃の問題もあったりすると、例えば高齢者のグループホームなんて、６０坪あって９人でワンユニットでは運営できないなんて、こんな話が出るわけではないですか。そういう意味も含めて、賛成します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":97,"id":"exchange-029"}]},{"id":"topic-04","title":"令和６年請願第７号、国に対して訪問介護の基本報酬引き下げの撤回を求める意見書の提出を求める請願","agenda":"令和６年請願第７号、国に対して訪問介護の基本報酬引き下げの撤回を求める意見書の提出を求める請願","exchanges":[{"speaker":"ひがし委員","kind":"確認","question":"今年のニュースで、訪問介護事業者の去年の倒産率が過去最多だったというニュースを見ました。ただいま区には特に声は届いていないけれども、現状としては把握しているということなのですが、その声の拾い方としては、向こうから連絡が来たみたいな形なのか、それとも、こちらから業者に確認をとっているのかという点を確認させてください。","respondent":"菅野高齢者福祉課長","answer":"参考として、ハートページという事業所紹介のものを毎年更新させていただいているのですけれども、その中では、昨年度に比べて、訪問介護の区内の事業者数は、４事業者ぐらい、昨年は５７事業者だったのですけれども、今年は５３事業者というところで。","voiceIndex":117,"id":"exchange-030"},{"speaker":"ひがし委員","kind":"質問","question":"少なくとも４事業者が何らかの理由で少なくなっているというところは、今、人材不足が叫ばれている中で、すごく深刻なことなのではないかなと思います。居住支援手当が出されるということなのですけれども、これの今の進捗を教えていただければと思います。","respondent":"菅野高齢者福祉課長","answer":"区としては今年度、基本的に介護職員の方の給与というのは介護報酬を原資としているのですけれども、そういうのもなかなか難しいという部分もあって、居住支援手当を新規事業として打ち出しています。","voiceIndex":119,"id":"exchange-031"},{"speaker":"ひがし委員","kind":"質問・要望","question":"現状としても、品川区内だけではなくて、全国的に訪問介護、また、医療従事者の給与の問題、少な過ぎるのではないかというのが出ていますし、私としてもやはり医療従事者・介護従事者の給与の面というところは処遇改善していただきたいなというのは、本当に思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":121,"id":"exchange-032"},{"speaker":"鈴木委員","kind":"質問","question":"こういう形で、国の委員会でも、厚生労働委員会の中でも全会一致で意見書が上がるということのものだというところで、こういう意見書が上がったということに対して、区としてはどのような受け止めをされているのか、伺えたらと思います。そういうところでは、品川区内の訪問介護事業所の経営状態がどんな状況になっているのか、区として把握されているようでしたら、その点についても伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"国の動きも見つつ、区としては国の動向を見たいというところではあるのですけれども、そもそも介護報酬というのが、引き上げた場合、サービスの充実とか職員の処遇改善が期待できる一方、利用者の自己負担とか税金や保険料といった、区民の負担も増えるというところで。","voiceIndex":125,"id":"exchange-033"},{"speaker":"鈴木委員","kind":"質問・要望","question":"反映されていないにもかかわらず、そういうところで大手のところは出すわけですから、大手の利益率が高いところが出されて、平均を押し上げるという形になってしまったわけですけれども、それでも、そういうふうに大きく利益率を上げているところと赤字のところと、すごい格差があるという、大手のところ、また、サービス付き高齢者向け住宅のようなところ、そういうところと、小規模の。","respondent":"菅野高齢者福祉課長","answer":"国の動きというところで、区ではどうかというところなのですけれども、そういった部分で、先ほど最初の説明でお話しさせていただきましたが、他区の状況なども情報共有させていただきながら、課長会などを捉えて。","voiceIndex":127,"id":"exchange-034"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そこら辺の状況も、区としてつかんでいるところを伺いたいのですけれども、それで、先日伺ったのが、紹介料というのは年収の３０％を紹介会社に紹介料として払わなければならなくて、安いところで２５％というところもあるということなのですけれども、３か月働いたら紹介料は戻ってこないということで、私が聞いた事業所では、３か月働いて、４か月目に来なくなってしまって、連絡しても連絡がとれなくて。","respondent":"菅野高齢者福祉課長","answer":"その辺のところは各事業者がすごく苦労されているのかなというのは推測できますので、引き続き区内の事業者のそういった動向については、注視してまいりたいと考えています。","voiceIndex":129,"id":"exchange-035"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それからもう一つ、厚生労働省が今回、処遇改善加算をつけているのだということを言っているのですけれども、これはどれぐらい処遇改善加算がつけられているのかというのを区として把握していたら伺いたいのですけれども、これまで６段階の加算になっていたと思うのですが、加算をつけている事業者が何％ぐらいあるのか、つけていない事業者もあるのか、そこら辺、分かったら教えていただきたいと思います。","respondent":"菅野高齢者福祉課長","answer":"逆に、ヘルパーがもう２０年ぐらい働いていて、どんどん高齢化していて、つなぎ手というか、次の方がいらっしゃらないみたいなお話も聞いているというところは、処遇が悪いから辞めるとか、そういった部分ではないのかなと考えていますので、その辺りの取得等については。","voiceIndex":131,"id":"exchange-036"},{"speaker":"鈴木委員","kind":"質問","question":"加算というのは手続も大変ですし、それを整えないと加算がつかないので、整えるのも大変だし、手続上もすごく大変なのですよね。それからもう一つなのですけれども、総合事業。総合事業は……。区独自に決定するものですので、せめてこれを上げられないかなと私は思っているのですが、その点についての実態と考え方を伺いたいと思います。（「よく読んでよ。","respondent":"菅野高齢者福祉課長","answer":"区の総合事業の単価につきましては、基本的に介護給付費の訪問介護とかの単価を見ながら、３年ごとに同じように改定をしています。","voiceIndex":133,"id":"exchange-037"},{"speaker":"鈴木委員","kind":"質問・要望","question":"要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":135,"id":"exchange-038"},{"speaker":"やなぎさわ委員","kind":"確認","question":"ほとんど議論は出尽くしたかなと思うのですけれども、すみません、ちょっとだけ。確認なのですが、先ほどハートページで５７者確認したということで、これは、先ほどちらっとお話がありましたけれども、ハートページは、品川区のハートページだったとしても、区外の事業所もちょっと載っているではないですか。それは品川区だけですか。それとも掲載されているのが。","respondent":"菅野高齢者福祉課長","answer":"ハートページの部分についての説明ですけれども、区外も掲載されています。","voiceIndex":137,"id":"exchange-039"},{"speaker":"やなぎさわ委員","kind":"質問","question":"ということは、区内以外のところは、区民が利用されているところは掲載の可能性があるという仕組みですか。","respondent":"寺嶋福祉部長","answer":"過去の経緯がありましたので、私から説明します。品川区内の事業者は全て載せるという方向性でやっています。それから、区外については、例えば区境のところに住んでいる方が、隣接区の訪問介護を使ったりする可能性があるので、利用実績がある事業者については載せます。","voiceIndex":139,"id":"exchange-040"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"分かりました。それはいいのですけれども、ハートページは年に１回の更新で、先ほど訪問看護は都の管轄でということで、情報が回るのが遅いということだったので、ケアマネジャーが情報収集していらっしゃるということだったので、それは非常にいいことだと思って、リアルタイムに情報が入ってくると思うので、ぜひそれは活かしていただきたいなと。何かあれば。","respondent":"菅野高齢者福祉課長","answer":"ケアマネジャーにも確認すると同時に、区としては、保険者として実地指導等もしておりますので、その機会も捉えて、そういった加算の取得についてとか事業者の状況把握についても、していきたいと考えています。","voiceIndex":141,"id":"exchange-041"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"実態が反映されていないよと非常に多くの方が思っていらっしゃると思うので、当然、アンケートに答えなかった人たちにも問題があるということもあるかもしれないのですけれども、アンケートというのは当然重要な、実態を知る、分析する上で非常に大事だと思うのですが、それを踏まえた上で、さらにそれが適正かどうかというものも併せて、二重で確認してこそ、データというのは活かされるかなと思うので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":143,"id":"exchange-042"},{"speaker":"筒井委員","kind":"質問・要望","question":"基本報酬引き下げの代わりに処遇改善加算があるので、それが代わりになってカバーされるというようなお話もあったのですけれども、この処遇改善加算は、支給の対象が、働いている職員そのものでなく、施設に支給されるということで、要件とかもいろいろ大変なのですが、結局支給対象の職員に支給されない可能性もあるということなのですけれども、品川区でそうした。","respondent":"菅野高齢者福祉課長","answer":"今回も国のほうでは恐らく介護報酬引上げによって職員の方たちの月収が６,０００円上がるだろうというのは、全体の見込みの中で立てているというところです。","voiceIndex":145,"id":"exchange-043"},{"speaker":"やなぎさわ委員","kind":"意見","question":"でも、今回の分はきちんと就業規則に載せるということで、違反すると恐らく罰則の対象になりやすい、非常に重いというか、就業規則までしっかり変えさせて支給するというもので、そういう、ある意味ひと手間かけるけれども、きちんと職員の元にお金が届くというようなスキームになっていると考えていますので、今回、４月から実施される介護職員の居住支援手当は実効性が強いのだなと考えておりますし。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":148,"id":"exchange-044"},{"speaker":"石田（秀）副委員長","kind":"質問","question":"先ほど来、答弁もありましたように、品川区では、介護利用者のサービス低下、これはあってはならないということで、それにつながらないように、それで居住支援だとか、私はもう１個、きちんと情報をとれているよともっと言ってほしかったなと思うのは、５年ぐらいたったと思うけれども、ケアマネジャーの組織をしっかりつくって、そして利用者の方々に様々。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":151,"id":"exchange-045"},{"speaker":"若林委員","kind":"質問・要望","question":"本日結論を出す。そこで、介護と障害者、障害の方の従事者の方々の処遇改善の検討を求める決議を、６月５日ですか、ご案内がありましたけれども、決議をさせていただきました。課長からもありました、上部団体等ということはまさにそのとおりであると思いますので、国に対して区が意見書を出すということの請願については、不採択で結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":152,"id":"exchange-046"},{"speaker":"ひがし委員","kind":"質問・要望","question":"本日結論を出すでお願いします。先に意見を述べします。立憲民主党は、国会でも訪問介護の基本報酬引下げの撤回等、厚生労働大臣に申入れをしています。ただ、区としても区の事業者の状況をしっかりと把握していただいた上で、今回、基本報酬が下がる分、何かしらの形で補填、また、運営の方々、働く方々を支えていけるように、対策を講じるように求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":153,"id":"exchange-047"},{"speaker":"鈴木委員","kind":"意見","question":"結論を出すで、採択でお願いしたいと思います。これは、やはり今回の訪問介護の介護報酬引下げは道理がないものだということだと思います。私は、こういう事業所がしっかりと続けられるようにすべきだし、介護現場の処遇改善というのは待ったなしで進めるべき課題だと思います。この報酬引き下げを撤回させて、引き上げさせていく、そういう方向で、区議会としてもぜひ意見書を上げていきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":154,"id":"exchange-048"},{"speaker":"筒井委員","kind":"意見","question":"訪問介護の基本報酬の引き下げということは、すなわち在宅介護をこれから推進していくという方向性とかなり大きく逆行するような事象でありまして、処遇改善加算でカバーするということもありますけれども、それもまた職員に確実に支給されるということがまだまだ不確実なものもありまして、また、そもそも訪問介護の基本報酬を引き下げるというこの事象、言葉のインパクトということを考えると。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":155,"id":"exchange-049"},{"speaker":"やなぎさわ委員","kind":"意見","question":"品川区としても様々対策していただいているのは承知しておりまして、これは区が意見を上げるということですので、区長会含めて、品川区からやはり日本の介護業界全体の底上げ・改善に向けて声を上げていければと思いますし、先ほどの６月５日の介護職員等の決議、超党派で国会で出されたということですので、今後ももちろん、４月から介護報酬の改定がされてということですので、動向をぜひ注視していって。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":156,"id":"exchange-050"}]},{"id":"topic-05","title":"令和６年陳情第２５号、心身障害者福祉会館の提案用地の検討結果についての説明を求める陳情","agenda":"令和６年陳情第２５号、心身障害者福祉会館の提案用地の検討結果についての説明を求める陳情","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"身障者会館の整備についてというのは、繰り返し陳情が出されていますけれども、昨年の９月、今年の１月にも議論がされていると思います。昨年の９月のときに、全面改修、建て替えをする方向で、東京都とも代替の施設を相談しながら検討しているということだったと思うのですが、その後の進捗というのはどうなのか、伺いたいと思います。","respondent":"松山障害者支援課長","answer":"それ以外につきましては、区の全庁的なルールに基づいて記したものですので、そちらについては、大規模改修が大体３０年、建て替えの時期の周期について６０年という目安で、記載させていただいたものです。","voiceIndex":172,"id":"exchange-051"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ということは、何かこれまでの答弁だと、もう東京都とも代替の施設を相談しながら、全面改修、建て替えをする方向で検討しているというご答弁だったので、建て替えの方向で動いているのかなと思っていたのですが、そういうことではなくて、建て替えは、あくまでも２０３４年から４３年の間にしかこの身障者会館の建て替えはしませんよというスケジュール感になるのか、その点を改めて確認させてください。","respondent":"松山障害者支援課長","answer":"この公共施設等総合計画につきましては、個別の施設の整備計画がない、あるいは予算で決まっていない場合については、目安として一律に、先ほどの大規模改修であれば大体３０年、建て替えであれば６０年という全庁的なルールに基づきまして記載させていただきましたので。","voiceIndex":174,"id":"exchange-052"},{"speaker":"鈴木委員","kind":"質問","question":"そうしますと、この総合計画の中には、２０３４年から４３年ということで建て替えの時期はなっているけれども、令和６年、今年から再来年の令和８年までの間に、建て替えについてどういうふうに進めていくかということを検討するのが、この期間だということですか。","respondent":"松山障害者支援課長","answer":"委員のおっしゃられるとおりですので、その検討の結果、時期については、まだ何ら決まっているものは区としてはないという状況です。そのため、全庁的なルールに基づいて、一律に記載をさせていただいたものです。","voiceIndex":176,"id":"exchange-053"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ということは、その検討の結果、２０３４年よりももっと早まるということもある。それで、また１月の議論の中でも、既存不適格の箇所が様々指摘されたりということもありますので、検討は令和６年から８年までということですが、そこの中でできるだけ早くに建て替えの方向も、皆さんの要望に応えていただくということで、ぜひともお願いしたいと思うのですが、いかがでしょうか。","respondent":"松山障害者支援課長","answer":"現段階でも、先ほど申しましたように、エレベーターのクロススクリーンの設置工事を今年度、これから実施予定ですので、今現在も、安全・安心の確保ということに努めている段階です。","voiceIndex":178,"id":"exchange-054"},{"speaker":"ひがし委員","kind":"確認","question":"今のご答弁のところで確認をさせてください。予算がついているということは、まず、既存不適格のお話とかもありましたように、今、施設を利用されている方々が安全に過ごせるように、予算をつけて整備をしていくということで合っているのかということを、まずは確認させていただければと思います。","respondent":"松山障害者支援課長","answer":"心身障害者福祉会館のその後の方向性の認識についてですが、委員のおっしゃられるとおり、第３回定例会で、改築を視野に入れて検討するということでご答弁申し上げているところで、具体的なものというのは、まだこれからの検討ということになります。","voiceIndex":181,"id":"exchange-055"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ただ、今のお話を聞いていると、何かそこの段階にも至っていないのだなというところで、正直、区民の皆様からも、旗の台周辺の方々からも、いつ頃になるのだろうという話はずっと聞いているところで、今、議論していますというお話だったので、まだ方向性が見えていない段階なのだというところは少し衝撃を受けているのと、やはり以前もお話ししましたが、計画を立てて。","respondent":"松山障害者支援課長","answer":"計画についてのご質問ですが、計画を立てるということは、ある程度やはり具体的な時期ですとか代替施設とかがはっきり明確になったところでの計画となりますし、こちらの陳情にありました大田区のホームページで掲載されていることも、やはり具体的な期間ですとか。","voiceIndex":183,"id":"exchange-056"},{"speaker":"ひがし委員","kind":"質問・要望","question":"方向性をまずは早めに示していただきたいのと、３年かけていろいろ決めていかなければいけない問題もあるとは思うのですが、３年かからない中、早めにできるといいと思うので、そこはしっかり方向性というところを示していただいて、大田区の整備計画のように、細かく載せられるというところを心待ちにしておりますし、それについて議会としてできることというのはもちろん協力するので。","respondent":"松山障害者支援課長","answer":"前向きな姿勢ということでご答弁申し上げますと、本当に今、障害福祉計画に、心身障害者会館のことにこれだけ検討していくとはっきりと明言したのは初めてということと、あと、それから、今年度、実際にもう予算もつけてエレベーターの改修工事をするというところは。","voiceIndex":185,"id":"exchange-057"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"結論を出します。不採択でお願いします。いろいろなことで我々もいろいろな要望をしたり、こういうことも考えたほうがいいのではないかということは相当言っていますが、その中でも、これはやるという前提で、順次いろいろな問題をクリアしているのだと私は理解しておりますので、不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":189,"id":"exchange-058"},{"speaker":"若林委員","kind":"質問","question":"本日結論を出すです。障害福祉計画に言明されている計画を、しっかりと前向きに進めていただければと思います。様々ご説明をお聞きしましたので、了といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":190,"id":"exchange-059"},{"speaker":"ひがし委員","kind":"提案","question":"本日結論を出すでお願いいたします。整備計画の必要性、また方向性を早めに示していただきたいという思いは変わっておりません。ただ、せっかく今回、提案をしていただいているので、今後、議論を進めて行く中で、その場所についてもどうなのかというところを、しっかりと検討していただければなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":193,"id":"exchange-060"},{"speaker":"鈴木委員","kind":"意見","question":"結論を出すということで、趣旨採択でお願いしたいと思います。本当に全面改修、建て替えをする方向でというふうなことでずっと議論されてきましたので、これだけ遅い時期というのも総合計画で初めて……、少しびっくりしたのですが、それは基本的な形でそういうふうにしているということでしたので、なるべく早くの建て替えに向けての検討をぜひお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":194,"id":"exchange-061"},{"speaker":"筒井委員","kind":"質問・要望","question":"ここの方が書かれた1)から8)について、1)から4)は、他課、また全庁的な検討が必要ということで、なかなか早急に分割困難、また5)から8)は民間の用地なので、なかなかコメントすること自体難しいということと、また、区としても将来的には前向きなご対応をしていただけるということなので、そうした早めに対応していただくということを要望いたしまして、ただ、この陳情は不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":195,"id":"exchange-062"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"私も前年度の厚生委員会から、この心身障害者福祉会館に関する陳情を拝見していますけれども、令和６年から８年に検討ということで、少しやはりペースが遅いのかなというところで、区民の方も、非常に動向を気にしていらっしゃる方がたくさんいらっしゃるというところで、なるべく早く結果に向けての検討をしていただきたいなというところで、趣旨採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":196,"id":"exchange-063"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そこで、その提言というのは、被保険者の低所得化や１人当たりの医療費増による保険料増が、個々の自治体の努力で解決できることではないという状況の中で、国庫負担割合の引上げをしてほしい。多分、この提言というのは区長会が出したことなので、区の認識もこういう認識だと思うのですが、それが進まなかったことに対してどう受け止めているのかということを、まず伺いたいと思います。","respondent":"池田国保医療年金課長","answer":"国への提言についても、その他の国庫負担の引上げの実施とかそういったものについても、区長会を通じて引き続き要望をさせていただき、認識としましては、これ以上負担を伴わないような形でお願いしたいということでは。","voiceIndex":204,"id":"exchange-064"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ここの中でも述べているように、負担がもう限界という状況なのです。４人世帯の年収３００万円の方ですけれども、２００９年度、２００９年というのは様々な国保が改悪される前なのです、１５年前なのですが。この１５年前から国保の改悪が始まったのです。２.２５倍。この認識は区としても厚生労働省と同じかということを、改めて確認させていただきたいと思うのですが、いかがでしょうか。","respondent":"池田国保医療年金課長","answer":"国民健康保険の構造的な部分では、やはり収入のあまりない方が多いということと、それから、仕事をお辞めになられて病気がちな方、医療機関を使われる方が多いということで、保険料の基礎の部分が上がってしまうというところが構造的な部分かと思われておりますけれども。","voiceIndex":206,"id":"exchange-065"},{"speaker":"鈴木委員","kind":"質問・要望","question":"この認識をなぜ伺ったかというと、後で出てくる滞納者に対する捉え方というところに、保険料の負担が重いというところをしっかり捉えられるかどうかということで、私は滞納者に対する捉え方も関わってくると思っていたので、ここのところを確認させていただきたいということで、前から求めていたところです。それなので、これを引き下げるべきだということで求めておきたいと思います。","respondent":"池田国保医療年金課長","answer":"保険料の減免について、区独自で検討していないかですが、先ほど保険料についてご説明しましたように、まず保険料については、特別区は基準保険料で、統一保険料という形でやっておりますので、減免等についても基準といったもので考えなければいけないかなというところで。","voiceIndex":208,"id":"exchange-066"},{"speaker":"鈴木委員","kind":"質問・要望","question":"子どもの国保料というのは、本来、収入が全くない生まれたばかりの赤ちゃんからも、今回の均等割は６万５,６００円ですから、収入の全くない子どもから６万５,６００円の保険料を取るというのが、この国保料なわけです。それなので、子育て支援という観点からも、ぜひ無料にすべきではないかと思うのですが、改めて検討していただきたいということと、この考え方について伺いたいと思います。","respondent":"池田国保医療年金課長","answer":"現在の保険料の制度の中には、従うべき基準としまして、国の基準を超えて独自に一律の保険料軽減を条例で定めることはできない仕組みになっているということもありますので、国のほうで決められたものについて行っているですので、特段、品川区で独自にやるという考えは。","voiceIndex":210,"id":"exchange-067"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これは何度も何度も要望していることなので、改めて子どもの国保料無料化、国保だけですから、こんなやり方をしているのは。相互扶助だから半額であるべきだというふうに、区も半額であるべきだということを求めているわけではなくて、その拡大というのも提言の中でも求めているわけではないですか。それから、赤い封筒についても意見を言いたいのですが、皆さんの意見の後でまた言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":212,"id":"exchange-068"},{"speaker":"鈴木委員","kind":"質問・要望","question":"この封筒は、いただいたときに本当に驚いて、大体払えない方が、気持ち的にもすごく追い込まれて弱っているというところにこれが届いたら、何かさらに具合が悪くなってしまうという、ここにも書かれていましたが、実際に届いた方からそういうふうに伺いました。それで、「差押よりも債務整理の方が納税額を生み出しやすい」。野洲市に学んでいただきたいなと思っているのですが、どうでしょうか。","respondent":"池田国保医療年金課長","answer":"なぜ、文書ばかりなのかですけれども、実際に電話でも、私どもに納付案内センターというところがございまして、お支払いが少し遅れた方については、遅れていませんかということでのご連絡もさせていただいているところですけれども、電話と、それから手紙を併用することで。","voiceIndex":216,"id":"exchange-069"},{"speaker":"鈴木委員","kind":"質問","question":"差押えをするときは、必ず面接して滞納者の実態を具体的に把握するというのも、野洲市ではされているということで書かれていたのですが、そういうことで、面接もして滞納者の実態を把握して、悪質だったり、これは適切というところで把握した上で差押えをされているのか、実際に聞き取りまでしっかりとされているのか、その点についても伺いたいと思います。","respondent":"池田国保医療年金課長","answer":"一斉催告ということで、年４回ほど一斉に催告するような場合については、アンケート形式の、生活状況についてのアンケートにお答えするような調査書が入っているところでございまして、実際に最初から生活困難な方へという形での出し方はしませんで。","voiceIndex":218,"id":"exchange-070"},{"speaker":"鈴木委員","kind":"意見","question":"相談の方が、生活保護というのはおおよそ分かると思うのですが、それ以外のところでも、例えば暮らし・しごと応援センターとか、様々そういう相談に乗ってもらえる場所でどんな支援があるのかとかということは、全部把握された上で相談に乗っていただいて、そして、そういうところにつなげるというところはされているのか、その点もお聞かせください。","respondent":"池田国保医療年金課長","answer":"というのは、実際に滞納されている方が、このような形で困っているということでの話があった際には、そういうことができますけれども、最初からはできませんけれども、ご相談を受けた際には、そういったこともさせていただいているところではあります。","voiceIndex":220,"id":"exchange-071"},{"speaker":"鈴木委員","kind":"質問・要望","question":"とにかく払うのが当たり前ですよという形ではなく、なぜ払えない状況になっているのかという、野洲市みたいに滞納はＳＯＳというところで、何で払えない状況になっているのかということを私は丁寧に聞き取っていただいて、区役所は応援しているのですよというメッセージを出していただいて、それで、生活再建につなげるというところをぜひ徹底していただきたいと改めて要望したいと思いますが。","respondent":"池田国保医療年金課長","answer":"窓口に来られた方の話をよく聞いて、話を伺わせていただいた上で、それなりに相談先をお示しすることができるところがあれば、そこをお示しするような形でやっていっておりますけれども、今後もそれを続けていくような形をさせていただきたいと考えています。","voiceIndex":222,"id":"exchange-072"},{"speaker":"鈴木委員","kind":"質問・要望","question":"暮らし・しごと応援センターという制度ができ、生活困窮者支援事業というのができていますので、そこもしっかりと中身を相談者の方が分かっていただいて、そこにもつなげるというところは加えていただきたいと思っているのですが、いかがでしょうか。","respondent":"池田国保医療年金課長","answer":"前向きにやりたいと思います。","voiceIndex":224,"id":"exchange-073"},{"speaker":"ひがし委員","kind":"意見","question":"国民健康保険料に関する陳情のところについては、品川区の保険料は２３区統一の保険料方式を採用していると理解しました。陳情には、国保料の軽減に踏み出す自治体も現れているとあるのですが、東京都内２３区の中で値下げをしているところはあるのか、まず、そのあるのか、ないのかというところと、もしあった場合はどのぐらいの金額、値下げをしているのかというところを、お知らせいただければと思います。","respondent":"池田国保医療年金課長","answer":"それと、まず赤い封筒はどのくらい送られるかですが、実際には赤い封筒というのが、私どもで差押え自体をやるのが、年間二百五、六十件はやっているところですけれども、その方には必ず送らせていただいておりますので、そのほかに、分納の約束をしていて分納が履行できない方で。","voiceIndex":228,"id":"exchange-074"},{"speaker":"ひがし委員","kind":"意見","question":"恐らくこの封筒をやめるだけではなくて、寄り添った姿勢を見せてほしいのだよというところが言いたいのかなと理解すると、先ほどお話ししていただいたように、相談の窓口のお知らせも一緒に併せて入れてくれているというのはいいところなのかなと思いますが、なかなか封筒を開けないというところになると、それはどうやったら伝わるのかなというところを少し考えています。","respondent":"池田国保医療年金課長","answer":"私どもで、国民健康保険と、それから区民税の窓口が今４階で、そういうところで連携とかということができないかということも、今後の部分では検討をさせていただいているところでございまして、税情報を共有できないかどうかということも。","voiceIndex":230,"id":"exchange-075"},{"speaker":"ひがし委員","kind":"意見","question":"半年間未納だった場合は赤色の封筒が送られてくるという、今のご説明で理解をいたしました。ほかの保険料を含め、窓口で相談しながら、どのように寄り添っていけるかというところを検討していただけるというところは、前回から進歩しているところなのかなと理解しましたので、ぜひより丁寧に、寄り添いながら進めていけるような取組をしていただければなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":236,"id":"exchange-076"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"そういった意味で、私もない頭で知恵を絞ってということで、封筒を開けてもらって、そういういろいろな区としての支援がありますよというところに気づいてもらう、それこそ先ほどの暮らし・しごと応援センターもそうですし、生活保護なり何なりというところにつなげるような取組をぜひしていただきたいと思うのですが、やはり封筒を開けていただくというところが少しハードルになるのかなという意味で。","respondent":"池田国保医療年金課長","answer":"委員のご意見については、ご意見として承らせていただきます。実際にこちらの滞納整理につきましては、またこちらで違う観点から考えするようなこともしますけれども、ただ、一つ誤解はしないでください。赤い封筒は最後に行くのだということです。","voiceIndex":238,"id":"exchange-077"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"ただ、その最後という部分でもやはり、先ほどひがし委員のご指摘もありましたけれども、区の姿勢といいますか、この陳情も含めて、そういう寄り添った姿勢というのをぜひ見せていただきたいというところから、このような陳情になっているのかなと考えていますので、恐らくこの陳情の趣旨としても、あまりにもショッキングな色だと怖くなってしまうというところなのかなと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":240,"id":"exchange-078"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"結論を出します。不採択でお願いします。理由は、先ほど来、統一保険料という話、区長会からの要望の話、相互扶助、そして、５割の軽減も行われているということでありますので、不採択ということであります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":243,"id":"exchange-079"},{"speaker":"ひがし委員","kind":"質問・要望","question":"本日結論を出すでお願いいたします。保険料が高過ぎるということと、あと、保険料をもちろん下げていただきたいという思いはあります。一方で、１８歳以下の均等割については、特別区長会でも補助を要望しているということですので、引き続き求めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":245,"id":"exchange-080"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これだけ高い均等割がかかるようになっていますので、本当に人頭税のようなこういう取り方というのはやめるべきですし、国保法で、子どもの国保料の無料化というのは区独自にできるものですし、多くの自治体でそういうことでやっていますので、２３区統一の保険料と言いながら、この子ども国保料の減免、それから免除というのは、無料化というのはできることだと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":246,"id":"exchange-081"},{"speaker":"筒井委員","kind":"質問・要望","question":"先ほど来お話が出ていますとおり、２３区では統一保険料制度を取っていること、その中でも軽減措置も取られているという努力はされていると。一方、税金と並んで社会保険料の負担というのが大きく、この国民健康保険料もそうだと思いますので、引き続き特別区長会を通じて、抜本改革、持続可能な制度のため、何とか負担軽減をお願いしていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":247,"id":"exchange-082"},{"speaker":"やなぎさわ委員","kind":"意見","question":"本日結論を出すで、採択でお願いします。品川区から、１８歳以下の均等割無料化という波をぜひつくっていければなと思いますので、そういった意味で採択とします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":248,"id":"exchange-083"},{"speaker":"石田（秀）副委員長","kind":"意見","question":"結論を出すでお願いします。不採択でお願いをいたします。先ほど来、何度ももうお話があるように、ここに至るまでにはもう何度も機会があって、最後の最後に赤い封筒となるのだと理解をしておりますし、その間、何度も相談できる状態もあると考えています。そういう観点からも、不採択ということであります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":252,"id":"exchange-084"},{"speaker":"若林委員","kind":"質問・要望","question":"本日結論を出す。不採択です。今後も様々工夫をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":253,"id":"exchange-085"},{"speaker":"ひがし委員","kind":"質問","question":"本日結論を出すでお願いします。色については適宜改訂はしてくれているというご答弁があったので、今後も検討いただければと思います。その間に相談窓口につながるような調整というところを、品川区としては取り組んでいくべきかなと思いますので、ワンストップの滞納者に対しての窓口など、様々検討いただければと思います。今回の陳情に対しては、不採択ということでお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":254,"id":"exchange-086"},{"speaker":"鈴木委員","kind":"質問・要望","question":"どんどん値上げをして、高過ぎるという状況にして、そして、払えないという状況にして、そして、払えない人に真っ赤な封筒で脅すというやり方というのは、やはり改めるべきですし、品川区は本当に相談に乗りますよというアピールをしていただいて、生活再建につなげる、そして、品川区に相談に行けば何とかなるという、寄り添った相談というのをぜひしていただきたいと思いますし。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":255,"id":"exchange-087"},{"speaker":"筒井委員","kind":"質問","question":"本日、不採択でお願いします。ただ、一方、封筒の外に、いろいろなお困り事はありませんか、相談を受けつけます等々、そうした丁寧な、区も支援がある旨の記載をするなどの工夫と、それに基づいて丁寧なご相談や支援をしていただけるとよろしいかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":256,"id":"exchange-088"},{"speaker":"やなぎさわ委員","kind":"意見","question":"区としましても様々お考えがあって、最終的にこの赤い色ということで選ばれていらっしゃるとは思うのですけれども、やはり寄り添うという観点で、一度少し見直しをしていただいてもいいのかなと思いますし、あと、やはり区に相談することで様々な支援につながるということを、区民の皆さんが知らないということが大きな問題なのかなと思っていて、それは区の周知だけではなくて、ある意味。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":257,"id":"exchange-089"}]},{"id":"topic-06","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"若林委員","kind":"質問","question":"言葉だけの説明ですと、どんなようなものがどういう状況で、隣接する店舗のどういう損害だったかというのが分からないので、もう少し分かるように具体的な説明をお願いします。","respondent":"樫村高齢者地域支援課長","answer":"そこにつきまして、経年劣化により根本からその支柱が倒れまして、横にある美容室の店舗の看板に、それが当たってしまって、看板を割ってしまったといったところです。","voiceIndex":264,"id":"exchange-090"},{"speaker":"若林委員","kind":"質問","question":"ゆうゆうプラザは、まだ１０年ぐらいですかね。たかだか１０年で、何で腐るという現象が起きたのか。その説明をお願いします。","respondent":"樫村高齢者地域支援課長","answer":"その支柱が、大崎ゆうゆうプラザの敷地内にはあるのですけれども、設置した時期ですとか経緯等については不明なのです。先ほど申し上げたとおり、その支柱については上に今何もない状態、ただの支柱で、上に看板とかがない状態だったと。","voiceIndex":266,"id":"exchange-091"},{"speaker":"若林委員","kind":"確認","question":"指定管理者のチェックというのは不十分だったということですか。それと、区と指定管理者のそれぞれの責任というのはどのようになっているのか、最後に確認したい。","respondent":"樫村高齢者地域支援課長","answer":"当然、大崎ゆうゆうプラザの敷地内にはありますので、区も、それから指定管理者も、点検する義務はあったのですけれども、そこにつきまして、先ほど申し上げたとおり、看板等がない状態で支柱が立っておりましたので、区も、それから指定管理者も。","voiceIndex":268,"id":"exchange-092"},{"speaker":"若林委員","kind":"確認","question":"もう答弁は分かりました。区の所有物であるということが自覚できないまま、こういう事故に至ったということで、確認をいたしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":270,"id":"exchange-093"}]},{"id":"topic-07","title":"ます。 (1)第５５号議案、品川区指定障害児入所施設の人員、設備および運営の基準等に関する条例及び(2)第５６号議案、品川区指定障害児通所支援の事業等の人員","agenda":"ます。 (1)第５５号議案、品川区指定障害児入所施設の人員、設備および運営の基準等に関する条例及び(2)第５６号議案、品川区指定障害児通所支援の事業等の人員","exchanges":[{"speaker":"鈴木委員","kind":"確認","question":"これも、児童相談所が設置されることによって、品川区が新たに認可と、それから、運営の基準のチェックというのをすることになるということだと思うのですけれども、入所施設というのは、今、品川区にはないということで確認させていただいていいでしょうかということが１点です。これは児童学園でやっていることでしたっけ。これがどこなのかというところがよく分からないので、教えてください。","respondent":"佐藤障害者施策推進課長","answer":"それで、今後のチェック体制等ですけれども、事業所に対するいわゆる実地指導という形で、訪問して、基準等に照らし合わせて書類等も含めての検査というのは、３年に１回というのを目安にするような形で国から出ておりまして。","voiceIndex":275,"id":"exchange-094"},{"speaker":"鈴木委員","kind":"質問","question":"そのために、区の職員が、なかなかどれくらいというのは難しいのかもしれないのですが、新たに、東京都が行っていったことを品川区で行わなければならないとなったことで、障害者施策推進課でどれくらいの人数が増えたのかというのを、分かる範囲で教えていただけたらと思います。","respondent":"佐藤障害者施策推進課長","answer":"検査の方法としては、ただ、そこの事業所に丸ごと委託して、ここのところへ行ってきてくださいという形ではなくて、検査できる方に同行してもらって、区のほうで主体的にやりながらも、一部の仕事について業務を手伝っていただくような形ができますので。","voiceIndex":277,"id":"exchange-095"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6749#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":73303,"voices":299}},{"id":"r06-20240701-8","meetingId":"r06-cm07","date":"2024年7月1日","dateIso":"2024-07-01","committee":"建設委員会","time":"午前１０時００分～午後 ２時３９分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を66件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"省エネ法のほうです。省エネは重要なことだと思いますけれども、今回の改正で新たな制度がつくられたということで、このケースに当たる場合というのは、どういう場合が考えられるのかというところを伺いたいと思います。それと、区内で想定される件数を伺いたいと思います。","respondent":"森建築課長、川原住宅課長","answer":"ただ、1)の接道が足りていないような状況の建物についてはそれなりに数が、それなりといっても件数は多くないとは思いますけれども、あるかなとは思うのですが。こちら、事前に許可が下りた場合には、必ず工事の施工主は看板を立てるという決まりがありますので、地域の近隣の住民の方はそちらの看板に基づいて、こういった行為がこれから行われるというところのチェック体制ができるのと。","voiceIndex":6,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"盛土規制法のほうも、住民の意見も寄せられるような形になるということで、ぜひそうした声が寄せられた際には、反映をしてやっていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"盛土のほうをお伺いしたいと思います。今回の定めといいますか新たな規制のことですけれども、新たに業者が盛土や切土を行う際に適用されるものなのか、それとも、過去にわたっているというか、既に盛土・切土をしている宅地に対してもその規制の対象になるのか、そこをご説明いただきたいと思います。","respondent":"川原住宅課長","answer":"ご質問をいただきました。新たなものなのか、それとも既に出来上がっているものの変更に対しても申請が必要なのかです。ご回答としては両者です。新設のものも、あとは開発の変更についても許可申請が必要という形です。","voiceIndex":11,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問","question":"変更も新設も両方対象だということです。そしてもう１点、品川区内も見ても、盛土、切土、様々あるかと思いますけれども、きちんとやっているところはきちんと保全されているし管理されているからいいのですが、現状において区がその場所に対して改善なり、注意なり、指摘をしている箇所はあるのか、その現状についても伺いたいと思います。","respondent":"川原住宅課長、森建築課長","answer":"どういった監視体制が取られるかというのは、今後も検討してまいりたいと考えています。建築課では場所等を把握しておりますので、所有者の方に助成等について準備がありますので、そういうことをご案内しながら、１か所でもイエローゾーン、レッドゾーンを解消していくように働きかけは行っておりますし。","voiceIndex":13,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"盛土・切土に関して現状では指摘している箇所はないということでした。ぜひ、注意警戒を怠らず、また大きな災害や豪雨、最近では、線状降水帯などなど、土砂災害の危険にさらされている地域では十分な警戒をしていただきたいと要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-005"},{"speaker":"つる委員","kind":"確認","question":"今、２人の委員からありましたので幾つか確認はできたところもありますが、質疑であって、都からの通知をまって、区としての態勢をということで今後の流れのご答弁があったわけですけれど、具体的な現状の、現実の対応というところでは、都のほうからはその当事者であるとか当事エリアだとか、そうしたところに対しては、今先ほど質疑があったような観点の注意というのでしょうか。","respondent":"川原住宅課長","answer":"しっかりと、都の通知だけではなくて区としてもどういった態勢を取れるかというのは検証を検討していきたいというふうに考えてあります。","voiceIndex":18,"id":"exchange-006"},{"speaker":"つる委員","kind":"質問","question":"それと、盛土規制法のほうで、（２）の一時的な土石の堆積というところが6)、7)とあるわけですが、区内で３００m2というと、小学校とかに設置されているプールぐらいの大きさというイメージでよいですか。それも教えてください。","respondent":"川原住宅課長","answer":"民間の許可申請というところで引き続きチェックをしていくところですが、こういった大規模なものについて、また７月３１日の施行をまって、また引き続き情報収集に努めてまいりたいと考えています。","voiceIndex":20,"id":"exchange-007"}]},{"id":"topic-02","title":"第５９号議案、品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","agenda":"第５９号議案、品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"戸越六丁目地区地区計画については、以前にも建設委員会で説明があったと思いますけれども、それから変更点などはあるのかどうかというところを伺います。それと、風営法関係の変更と、あと、そのほかにも細かい変更がありますけれども、現行の規制内容と変更はあるのかどうか、つまりこの区民への影響があるのかどうかということを伺います。","respondent":"小川木密整備推進課長、森建築課長","answer":"こちらの戸越六丁目の地区計画の変更につきましては、昨年度、本委員会で２回ほどご報告のほうをさせていただいておりまして、そのご報告させていただいた内容から、決定までの内容との変更は特にございません。区民の皆様の生活に変更があるかどうかについてですけれども、様々文言等の整理はいたしましたが、規制内容等については変更ございませんので、区民の皆様の生活等には変更がないです。","voiceIndex":34,"id":"exchange-008"}]},{"id":"topic-03","title":"第４５号議案、令和６年度品川区一般会計補正予算（歳出等 建設委員会所管分）","agenda":"第４５号議案、令和６年度品川区一般会計補正予算（歳出等 建設委員会所管分）","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"それぞれご説明ありがとうございました。ただ、何がどれぐらい改善されるのか、計画に対してどこまで充足するのか、そこがよく分からない部分でありますので、それぞれ伺いたいと思います。伺いたいのは、再配達によるＣＯ２排出の削減ですけど、これでどれぐらいＣＯ２排出量が下がるというふうに試算しているのか。","respondent":"中西環境課長","answer":"明確な数値目標といったところを掲げておるわけではございませんが、こちらの今回の東京都環境公社の補助金というのが令和８年度までの３か年の集中事業となっていますので、その３か年の中で、できる限り宅配ボックスの設置を進めていただきまして。","voiceIndex":55,"id":"exchange-009"},{"speaker":"中塚委員","kind":"確認","question":"それでもう１点、運輸部門の削減ということですけれども、運輸部門の削減、本当まだまだ削減されていない、削減しがいがある場所というか、そういうふうに思うのですけども、運輸部門の削減で一番ネックになっていることというのは何なのか、どこの部分の削減が達成されることがゼロカーボンシティの実現に対して必要なのか、区の問題意識を伺いたいと思います。","respondent":"中西環境課長","answer":"２点目の運輸部門、なかなか削減が進まないといったところで、いろいろ国のほうの調査とかも見ますと、やはり自動車を動かすといったところで、ガソリン由来のＣＯ２排出量。","voiceIndex":57,"id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"やっぱり全体の目標がもう定められていて、それを実現するためにはこの二、三年が勝負で、計画的にこれを導入するために、区としてはここまで出す、区民の皆さんはここまで協力してくれませんかという、その姿勢をもっと強く出すべきだと要望したいと思います。ぜひ、運輸部門での削減というのであれば、車両の規制こそ行うべきだと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-011"},{"speaker":"のだて委員","kind":"質問","question":"それと、債務負担行為で、勝島人道橋工事についてがありますけれども、今回この変更が必要になったのはなぜなのかと。基礎杭のところが工事期間が３か月延びたというのと、協議の時間がかかるということですけども、それがなぜ変更が必要になったのかというところ、想定できなかったのかというところを伺いたいと思います。","respondent":"中西環境課長、大友公園課長","answer":"そのままいきまして、２０３０年度には３４.１％不足するといったような数字もはじき出されておりますので、品川区といった一自治体ではありますが。勝島人道橋の債務負担行為の変更についてになりますけれども、変更の理由、当初から分からなかったのか、想定できなかったのかというご質問なのですけれども、まず。","voiceIndex":61,"id":"exchange-012"},{"speaker":"のだて委員","kind":"質問・要望","question":"ドライバーのところは不足する部分が出てくるということで、負担軽減の一助にはなるのかなというふうに思いますので、進めていっていただきたいと思いますし、そのためにも周知をしっかりしないといけないのかなと思うのですが、利用してもらわないと、結局ＣＯ２の排出削減もドライバーの負担軽減ということにもつながっていきませんので、そこの周知のところ、どのようにやっていくのか。","respondent":"中西環境課長、羽鳥防災体制整備担当課長","answer":"別の補助金の事業ですが、今年度始めた省エネ家電の事業などですと、ヤマダ電機さんのほうにもご協力をいただきまして、エアコンの販売ブースですとか。これはほかの自治体の事例を見て５００万円という金額というところで設定させていただきましたが、もちろん目標を超えて金額が集まるように努めていきたいと思いますけれど、未達であったとしても、それは区民の方の思いという形で。","voiceIndex":64,"id":"exchange-013"},{"speaker":"のだて委員","kind":"質問・要望","question":"それと、クラウドファンディングのところは一緒に進めていきたいということですけれども、もし本当に必要だというところであれば、公金、税金でしっかり対応していくということが行政の役割ではないかなというふうに思うのですが、そこのところも区のお考えを伺いたいと思います。","respondent":"羽鳥防災体制整備担当課長","answer":"トイレトラックにつきまして、まず、最初のご質問で、複数か所断水が発生した場合の対応ですけれど、先ほどもご説明させていただきましたけれど、区としては１台の導入ですけれど、現在は２２自治体が、この災害派遣トイレネットワークプロジェクトに参加しているというところで。","voiceIndex":67,"id":"exchange-014"},{"speaker":"のだて委員","kind":"質問","question":"トイレトラックは、そうすると２２自治体から首都直下地震の際も支援に来られるような自治体が契約しているということなのですかね。先ほどちょっと聞きそびれたのですけども、このクラウドファンディングが目標に達しなかった場合は、その足りなかった分は区の予算として出されるということになるのかどうかというところを伺いたいと思います。","respondent":"羽鳥防災体制整備担当課長","answer":"最初のご質問で、ほかの２２自治体であったり、災害協力協定の民間事業者がしっかり対応できるのかという部分ですけれど、こちらは、しっかり平時から連携をとって対応できるように進めてまいります。","voiceIndex":69,"id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"トイレトラックについて私も伺いたいと思います。こちらも全体としては現状より改善されるものだと思います。特にそのネットワークの中で被災地への支援というのは大きな役割を発揮していただきたいと期待しております。それだけに今回の対応は、改善するものだとは思いますが、実際の被害に比べて何がどこまで改善されるのか、引き続きどこに課題があるのか、そこを伺いたいと思います。","respondent":"羽鳥防災体制整備担当課長","answer":"避難所のトイレの耐震化であったり、マンホールトイレの設置であったり、先ほども申し上げましたが、災害時の協力協定によるトイレカーの提供の体制であったり、今回のトイレトラックの体制という形で、今までの想定避難者数に対する対策に上乗せして。","voiceIndex":72,"id":"exchange-016"},{"speaker":"中塚委員","kind":"質問","question":"例えば、今の課長のご答弁も９万人の想定。この９万人に入っていない人は誰かというと、建物が残っている人。マンション住民は１人も入っていない。なので、質問ですけれども、まず９万人の想定、これをぜひ見直していただいて、実際の被害を想定した数を対象にすべきだと思いますが、いかがでしょうか。７０人に一つというこの現状を改善させる計画と具体策を持つべきだと思いますが、いかがでしょうか。","respondent":"羽鳥防災体制整備担当課長","answer":"学校避難所のトイレにつきましても、避難所運営マニュアルの見直しも行いますので、しっかりトイレの確保についても記載してまいりたいというふうに考えてあります。","voiceIndex":74,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"国や東京都の被害想定がこうだから品川区は９万人なのです。トイレが必要になるのは９万人であるわけないではないですか。だって、帰宅困難者の人１人も入ってないのですよ。誰がどう用意するのか。そういうのを見ているわけですから。ぜひ、実際の被害を想定して必要な対応を今から準備していく、こうした姿勢でトイレ問題も進めていただきたいと思いますが、最後にいかがでしょうか。","respondent":"羽鳥防災体制整備担当課長","answer":"繰り返しになりますけれど、区といたしましては、やはり都の被害想定に基づいて対策を進めていくというところが基本となりますので、今後も様々な想定を勘案しながら、必要な対策を取っていきたいと、バランスを取っていきたいと考えております。","voiceIndex":76,"id":"exchange-018"},{"speaker":"横山委員","kind":"質問・要望","question":"それぞれ確認させていただきたいと思います。次に、応募方法について確認させてください。締切りについては特に設けていらっしゃるのか、いつ頃と考えていらっしゃるのかというところを教えていただけたらと思います。３点目に、区内業者と区内業者以外の発注分ということであるのですけれども、区内業者それぞれこういった件数対応可能なのかどうかというところも確認させてください。","respondent":"中西環境課長","answer":"応募方法ですが、まず、２段階に分ける予定でおりまして、事前申請という形で工事をする前に一度申請をいただきます。","voiceIndex":79,"id":"exchange-019"},{"speaker":"横山委員","kind":"質問・要望","question":"それぞれご答弁ありがとうございました。そのあたり、一言いただけたらと思います。次に、勝島のほうなのですけれども、こちら、１,０００万円追加の内容について確認をさせてください。全体の、例えば令和８年度以降の見積りですとかスケジュール関係に関しても、働き方改革の観点といったご答弁が先ほどあったかと思うのですけれども、そのあたりで何か変更点等がありましたら確認をさせてください。","respondent":"中西環境課長、大友公園課長","answer":"今回初めてこういった形で進めますので、申請件数ですとか、それプラスで事前にお問合せがあった件数とか、そういったものも含めながら、来年度以降の予算は検討してまいりたいというふうに考えてありますし。続きまして、全体スケジュールの変更点というところにつきまして、現状お示ししている計画どおり進めていく形にはなるのですけれども、上部工であったり橋詰め工事であったりということの設計を、今後。","voiceIndex":81,"id":"exchange-020"},{"speaker":"横山委員","kind":"質問・要望","question":"私はこの５００万円の設定というのは、ほかの２２自治体を見ましても適正なスタート金額かなと考えておりまして、そういった返礼品というのではないですけれども、例えば他の自治体を見ますとステッカーですとか、あとお名前の掲載というところがあったかというふうに思いまして、品川区のほうでも先ほどの議論の中でお名前というところがありましたけれども、こういったところの周知方法について。","respondent":"羽鳥防災体制整備担当課長","answer":"続きまして、稼働が実際いつになるのかですが、現在、２月下旬の納車予定です。納車後、すぐ研修等を行いまして、できれば今年度中に、３月中にどこかで活用できればとは考えてあります。","voiceIndex":84,"id":"exchange-021"},{"speaker":"横山委員","kind":"質問・要望","question":"災害時のトイレの在り方全体的にどのように変わっていくのかというところについても、私は気になっておるところがありまして、今回のクラウドファンディングの時期が１０月から１２月ということなのですけれども、例えば、その携帯トイレ等の配布の時期はどのくらいになっているのかですとか、ほかのマンション関係の施策の部分で。","respondent":"羽鳥防災体制整備担当課長","answer":"ほかの事業に関しましては、携帯トイレは１０月から順次配布、防災用のエレベーター用の防災チェアに関しましては、８月以降から受付をするです。もちろん、他のイベントでも周知できるように、しっかりほかの課と連携してまいりたいと考えています。","voiceIndex":86,"id":"exchange-022"},{"speaker":"つる委員","kind":"確認","question":"補正予算書の１４ページですが、先ほど来ずっと出ている今回、東京都のお金を半分使ってというところなのですけど、都というか東京都環境公社からということで、そこに基金出捐ということで、そこからさらにということだと思うのですけど、私もそれこそ確認までできなかったのですが、ここは諸収入の雑入での歳入という形になりますと、これはどういうふうだとここに入ってくるのか、要するに。","respondent":"中西環境課長","answer":"その事業を効率化するために東京都環境公社のほうに基金のほうで積立てをして、お金としては、東京都環境公社のほうに区としても申請をして、歳入として受けるといった形になりますので、こちらの雑入のところに入ってくるといった形になるものです。","voiceIndex":89,"id":"exchange-023"},{"speaker":"つる委員","kind":"提案","question":"こういうのは結構流れとしてはあるのですか。先ほどの答弁の中で、４１４kgとか１５０ｔという話がありましたけれども、この辺の見える化をやることによって、補助金の活用だけではなく、各自でこうしたところの工夫をしていただくという誘因にもなるのではないのかなと思うので、この辺りについては、改めて伺いたいなと思いますので、その辺を教えてください。","respondent":"中西環境課長","answer":"予算のお話です。私のほうで説明しましたのが、表の中のそれぞれの件数のところが決して上限で示しているわけではないといったところでお話をしたものです。宅配ボックスは今回初めて行う事業です。","voiceIndex":91,"id":"exchange-024"},{"speaker":"つる委員","kind":"提案","question":"ぜひ、予算特別委員会でご提案させていただいた部分もありますので、やり方はいろいろな方法があると思います。品川区としてのやり方で、しっかりとこの辺の提案も含めて、ぜひ検討いただきたいと思います。トイレトラックですが、これも先ほど来質疑ありました。会派としては２０１８年から繰り返して、横山委員も２０１８年から当委員会でも提案されているという中で、先ほどＡＩのところもありました。","respondent":"羽鳥防災体制整備担当課長","answer":"目標金額が未達の場合も獲得金額の１０％、また、目標を上回った場合もその金額の１０％ということで現在伺っているところです。詳細につきましては、今後、事業者のほうと確認をとってまいりたいと考えています。","voiceIndex":93,"id":"exchange-025"},{"speaker":"つる委員","kind":"提案","question":"これも先ほどクラウドファンディングのところであったわけですが、そうした、まさに今の部分のところも関連してくるかもしれないのですが、寄附を頂いた方のお名前であったわけですけれども、この間、区の会見のときに示された書類の中には、一応、トラックのラッピングの絵があるわけですけれども、これが決定の絵だという理解ではない、どちらなのかなというところと。","respondent":"羽鳥防災体制整備担当課長","answer":"ラッピングのデザインにつきましては、先日、区長の記者会見で使いました資料はあくまでイメージということで、ああいう方向性ではないというところです。実際にラッピングのデザインにつきましては、今後どういうふうにやっていくかというのは検討してまいりたいと思います。","voiceIndex":95,"id":"exchange-026"},{"speaker":"つる委員","kind":"提案","question":"日常の活用ということ、フェーズフリーでしたか、そういった観点から見たときの日常から使っていただくということも、これは質疑だとか、いろいろな場での提案等の中で話があったことであるわけですけれども、２月末頃の納車ということで、今年度の予定されている来年３月のシティマラソンとかでの活用なんていうのも、既に活用についてもいろいろな機会で話が出ているところであるわけですけれども。","respondent":"羽鳥防災体制整備担当課長","answer":"納車後の駐車場所についてですが、こちらは今、関係部署と確認をとっているところです。現在の想定ですと、地震体験車とほぼ同じサイズ感ですので、そちらの隣に、庁舎内の駐車場に置く想定です。","voiceIndex":97,"id":"exchange-027"},{"speaker":"のだて委員","kind":"意見","question":"債務負担行為は必要のない勝島人道橋を進めるためのものなので必要ないと思いますが、特にトイレトラックは、避難所環境改善に向けて一つの方法だとも思いますので、これは全体として判断をして賛成します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":104,"id":"exchange-028"},{"speaker":"中塚委員","kind":"意見","question":"全体としては賛成します。ただ、質疑でも指摘いたしましたが、宅配ボックス設置助成について、しっかりゼロカーボンシティしながわの実現というのであれば、必要な目標やそのための施策など、数値目標を持つべきだと思います。トイレトラックについても、実際に発生し得る被害を想定して、トイレ環境を整えるために今からどんな準備をしていくのかという防災対策の基本に立って計画を立てるべきだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":105,"id":"exchange-029"}]},{"id":"topic-04","title":"令和６年陳情第３０号、武蔵小山パルム駅前地区（竣工令和元年１２月）５年経過。駅前通り地区（竣工令和３年４月）３年経過。の再開発失敗を検証","agenda":"令和６年陳情第３０号、武蔵小山パルム駅前地区（竣工令和元年１２月）５年経過。駅前通り地区（竣工令和３年４月）３年経過。の再開発失敗を検証","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"武蔵小山の再開発ですけれども、まちを壊し、住民を追い出し、税金依存の再開発は直ちに中止をすべきだと思います。請願・陳情の審査ですけれども、大きく２つ伺いたいのですが、１つは、これは陳情の２ページ目の真ん中辺りに陳情理由とありますけれども、官製地上げの談合公共事業ですとの陳情者からの指摘があります。これについて、区はどう思っているのかを伺いたいと思います。","respondent":"中道都市開発課長","answer":"そうしたことを踏まえまして、こちら武蔵小山につきましては、商店街や地域の方々といったところでまちづくりの検討を進めてきて、都市計画の決定またはその組合設立といった形で進んできております。","voiceIndex":114,"id":"exchange-030"},{"speaker":"中塚委員","kind":"質問","question":"いつもの答弁ですけれど、地域主体で進めていた事業だから官製地上げの談合公共事業ではないというのが区の立場だと思います。私は、どんな進め方をされようとも、そこで住んでいる地権者の方々が意に反して引っ越しを余儀なくされる、それ自体はやはり地上げそのものだと思います。どうして、今の住宅のままで暮らしておきたいという願いがかなわないのか、区の見解を伺いたいと思います。","respondent":"中道都市開発課長","answer":"ですので、地域、個人個人の方で、もちろんその同意と、組合設立時に１００％の同意というところを区としても、組合に対しては説明してお願いをして、いかに１００％に近づけるかという努力はしておりますけれども、そこの中で進んできている事業です。","voiceIndex":116,"id":"exchange-031"},{"speaker":"中塚委員","kind":"質問","question":"１００％の同意を目指しているのだと言うけれども、あまりにもそれは建前の話だと思います。上位計画の話、勉強会の話、準備組合、本組合、また、１個できたら隣がまた、同じように進んでいく、様々な段階がありますけれども、まちづくりを推進している地権者と区の職員が顔見知りになるのはどの段階なのでしょうか。そこを伺いたいと思います。","respondent":"中道都市開発課長","answer":"地権者の方と区ですが、まず地権者の代表者の方が勉強会またはその協議会というところを設立します。その段階で区のほうに、こういったことを検討したい、まちづくりを検討したいというところでご相談に来る場合が多くあります。","voiceIndex":118,"id":"exchange-032"},{"speaker":"中塚委員","kind":"質問","question":"上位計画策定のときはちょっと一旦脇において、個別のこの再開発を進めるに当たっては、勉強会だったり協議会の際に、住民が品川区役所の窓口に相談に来るというところから顔見知りになるという説明でよかったのでしょうか。","respondent":"中道都市開発課長","answer":"顔見知りというか、そこで初めてそこの地区の地権者の方１名または複数名とお会いするタイミングが、そこが一番多くあります。","voiceIndex":120,"id":"exchange-033"},{"speaker":"中塚委員","kind":"質問","question":"一方、何が言いたいかというと、再開発を進めたいと思っている方々は、陳情者の立場に立てば、推進派はこの勉強会や協議会で顔見知りになるのですよね。結局品川区は、推進者、推進をしている方々のみと顔見知りになって、こういう計画には疑問だと思っている方々は、計画ができてから声を大きく、この関係は少なくとも地域主体のまちづくりとはとても言えないと思いますが、最後にいかがでしょうか。","respondent":"中道都市開発課長","answer":"まちづくりに対して賛成反対、様々な声があるということは区のほうも認識しております。","voiceIndex":122,"id":"exchange-034"},{"speaker":"中塚委員","kind":"質問","question":"賛成反対いろいろあるといったって、区の上位計画に沿うもの以外を認めてこなかったというのが少なくともこれまでの開発事業ですから、両方の意見を聞いているなんていうのは都合のいい話であって、結局は品川区が進めたい、武蔵小山でいえばタワーマンションの開発を１棟、２棟、３棟、４棟、さらに５棟、今出ているのは６棟ぐらいかな、どんどん進めていくと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":124,"id":"exchange-035"},{"speaker":"のだて委員","kind":"質問・要望","question":"ここを見ると、今まで区が答弁をしてきた権利者の数も違うという状況になっています。実際、駅前通り地区は、この記事で書いてあるのと、あと区が答弁してきた数というのが大きく違っているのですけれども、その理由が分かればご説明いただきたいのと、あとパルム駅前地区も若干ですが人数が違うのですが、これも理由分かれば伺いたいと思います。","respondent":"中道都市開発課長","answer":"２つ目の、権利者に対しての残留またはその移転、本移転です。過去の議事録等も確認しましたけれども、私たち理事者側から移転、本移転という言葉を活用したといったところはなかったということで、こちらの部分は回答を控えします。","voiceIndex":126,"id":"exchange-036"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうすると、この記事自体はつまりは区が行ったと、書いたということですので、区も認識をした確かな数ということでいいのかなと思うのですが、そこの確認と、残留については権利を持ったまま権利変換をされたと。事業費のところもこの陳情に書いてありますけれども、ここでいう保留床処分金ですとか組合員負担金というのがどういうものなのかというところを伺いたいと思います。","respondent":"中道都市開発課長","answer":"もし仮に借家人の方が多いというふうには推測はできますが、そういうところになりますと、民民間の契約の話になりますので、区としては民民間で協議、検討がなされたというところと認識しております。続きまして、資金計画の部分です。","voiceIndex":128,"id":"exchange-037"},{"speaker":"のだて委員","kind":"質問","question":"それと事業費のところでは、組合員負担金というのがつまり、その増えた床分を事業者が購入をした額だということで、これがある意味、原価になるのでしょうか。こうしたところにこの１１１億円もの税金が投入されているということで、この事業によって住民や店舗の方が追い出されるというところに税金を投入していくということはやめるべきだと思うのですけれども、いかがでしょうか。","respondent":"中道都市開発課長","answer":"そうした命を守るまちづくりという観点から区として進めてきたものですので、適正なまちづくりというものが進んでいるというふうな認識でおります。","voiceIndex":130,"id":"exchange-038"},{"speaker":"のだて委員","kind":"質問","question":"今回示された中でも、３１店舗中２４店舗がその場で続けられなくなってしまったということです。実際今、この残留というところで数字も出されておりますけれども、残留者がどこに行ったのかということで陳情にも書いてありましたが、実際この関係権利者がこの再開発ビルに戻ってきて暮らしているというのが区の認識なのかどうかを伺いたいと思います。","respondent":"中道都市開発課長","answer":"やはり安全安心に、また次の代にも、こういったパルム商店街を含めたまちというものが継続していく、そういったところで区としては支援をしているというふうに考えておりますし、それで支援をしています。","voiceIndex":132,"id":"exchange-039"},{"speaker":"のだて委員","kind":"質問","question":"やはり、残留者については把握をしていないということですけれども、実際、区が行った計画という、一緒になって行ってきた計画の中で、今まで住み続けてきた人が出ていかなければならなくなっているという実態をどういうふうにつかむかというのはあるかもしれませんが、そうした事業の結果を検証していくということも必要ではないかと思いますが、いかがでしょうか。","respondent":"中道都市開発課長","answer":"再開発でなければいけないのかですが、もちろんそこは再開発でなければいけないということではございませんで、地区内の権利者の方々が様々なまちづくりの手法の中で、市街地再開発事業を選択して進めてきた、そこの進めるところでは、法的なものも踏まえて検討されてきたです。","voiceIndex":135,"id":"exchange-040"},{"speaker":"のだて委員","kind":"質問・要望","question":"まちとして継続をしていけるようにということですけれども、今までの武蔵小山のまちというのが、この再開発によって壊され、住民や店舗の方たちも立ち退きを迫られ、立ち退かされてしまったというのが実態だと思います。そうした再開発に多額の税金を投入して進めていくということはやめるべきだと改めて強くこれを求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":137,"id":"exchange-041"},{"speaker":"木村委員","kind":"意見","question":"本日結論を出すで、不採択でお願いします。この再開発についてですけれども、以前からいろいろ議論が行われてきておりますが、また適正な手続もきちんと踏んでいるということで、私は不採択でということになります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":141,"id":"exchange-042"},{"speaker":"のだて委員","kind":"意見","question":"結論を出すということで、採択を主張します。小山三丁目の２地区のこの再開発の住民への影響を見る上で、先行した２地区を検証することは重要だと思いますし、住み続けたい区民が住み続けられないという、この小山三丁目第１、第２地区の再開発はやめるべきだと思いますので、採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":142,"id":"exchange-043"},{"speaker":"中塚委員","kind":"質問・要望","question":"本日結論を出すということと、趣旨採択でお願いします。再開発の検証や廃止を求める陳情の趣旨はそのとおりだと思いますので、趣旨採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":143,"id":"exchange-044"},{"speaker":"のだて委員","kind":"意見","question":"共産党としては採択すべきだと思いますけれども、住民の方々にとっても賛成者、多いほうがいいと思いますので、趣旨採択に変更しても構いません。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":147,"id":"exchange-045"}]},{"id":"topic-05","title":"の(1)、大崎駅東口第４地区における再開発事業に係る事業者による近隣説明会の開催","agenda":"の(1)、大崎駅東口第４地区における再開発事業に係る事業者による近隣説明会の開催","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"請願審査に当たって、まず大崎駅東口第４東地区の計画概要について伺いたいのですけれども、もう説明会の日程も示されているので、どういうものが建つのか、区も把握されていると思いますが、ホテル、オフィス、マンションなどなど、商業施設、どんなものを建てようとしているものなのか、ご説明ください。協力企業または協力組合員という言い方もしますが、協力企業、協力組合員がどこなのか伺います。","respondent":"中道都市開発課長","answer":"西地区、東地区におかれまして、オフィスまたはそのマンションといったのがおのおの１棟ずつ、西地区は高層のものがおのおのオフィス棟とマンションが１棟ずつ建ちます。西地区につきましては、中層のオフィス棟が１棟建つというところで、合計５棟が建つ状況です。","voiceIndex":154,"id":"exchange-046"},{"speaker":"中塚委員","kind":"質問・要望","question":"再開発というのは、税金以上に、総事業費と税金の補助金は分かりませんけれど、これぐらいだと総事業は五、六百億円ぐらいですか、税金はまた１００億円ちょいぐらいですかね。なので、質問ですけれども、大崎駅東口第４東地区の見直しを求める陳情ですが、この見直しをしてほしいと、住み続けたいと、この住民の気持ちが品川区は分かりますかと質問したいと思います。いかがでしょうか。","respondent":"中道都市開発課長","answer":"これは、事業の流れといたしましては、こういったものは今後その計画が決定して事業を進めるという段階になって、さらに詳細なものが分かるというところで、そういったご説明をしたというのは聞いているです。ですので、そういった気持ちをお聞きして、準備組合のほうにはさらにそういった不安払拭をしていただきたいというところはご説明をしたです。","voiceIndex":156,"id":"exchange-047"},{"speaker":"中塚委員","kind":"質問","question":"私が伺ったのは、住民の気持ちが分かりますかと伺いました。お答えください。","respondent":"中道都市開発課長","answer":"そういった不安の声というのは区としても理解はしておりますので、そういった声を一つでも少なくするように準備組合のほうに丁寧な説明をお願いしたです。","voiceIndex":159,"id":"exchange-048"},{"speaker":"中塚委員","kind":"質問・要望","question":"ここで陳情者がおっしゃっているのは見直してほしい、あとこのまま住み続けたい、なぜこうした声が上がるのかというところに、ぜひ特に担当者は住民と向き合っていただきたいなと思うのです。もう少しこの点を伺いたいのですけれども、ここに書かれているとおり、終の住みかとして購入したので転居するつもりはない。転居したくない。これは納得いかないと。ぜひそこを伺いたいと思います。","respondent":"中道都市開発課長","answer":"一方で、ここのマンションが旧耐震のマンションでありますので、そこは、こういったまちづくりを進めるのであれば、その新しい建物のそういった魅力等も丁寧に準備組合は説明して、ご理解をいただく必要があるというところもご説明はしております。","voiceIndex":161,"id":"exchange-049"},{"speaker":"中塚委員","kind":"質問・要望","question":"でも、随分もうけられた、稼いだのだろうなとも思いますけれども、やはりこの、終の住みかとして購入したので転居するつもりはない、この思いを区がしっかりとまず受け止めていただきたいと思いますが、この点いかがでしょうかと。新しい建物の魅力どれだけ語ったって、そんな話は納得いかないという気持ち、すごくよく私は分かるのですけれども、この点も区はどうお考えなのか伺いたいと思います。","respondent":"中道都市開発課長","answer":"ですから、７割の方がいるからいいという、そういうことではなくて、やはりその中で、いかにこういった不安の声をなくしていくのかというところが、進める中では区としては非常に大事だというふうに認識しております。","voiceIndex":163,"id":"exchange-050"},{"speaker":"中塚委員","kind":"意見","question":"大体そういう人が住民に何て声かけているかというと、「１円も負担しなくて新しいマンションに入れるのですよ」、「こんなおいしい話はありませんよ」、「あなた、１円も負担しなくて新しいマンションに入れるのですよ」と。なぜかというと、書かれているとおり、１,５００万円を払わないと同じ平米が手に入らないということが分かるのです。直ちに見直すべきだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":165,"id":"exchange-051"},{"speaker":"のだて委員","kind":"質問","question":"この大崎駅東口第４東地区の現状がどうなっているのかというところも伺いたいのと、あと、先ほど少し計画概要もお話しされましたけれども、今回建てられる計画建物の高さとか階数ですとか、そういったところも伺いたいと思います。この声を聞いて、区はどのように受け止めているのか伺います。","respondent":"中道都市開発課長","answer":"計画の建物の高さ等ですが、まだ現在それは概要で検討されているというところで、そこの詳細の部分につきましては、このご報告いたしました近隣説明会で正式に、概要の部分につきまして報告、説明するというふうに聞いております。","voiceIndex":167,"id":"exchange-052"},{"speaker":"のだて委員","kind":"質問","question":"実際、準備組合のほうに指導をしているということですが、どういった指導をされているのかというところも伺いたいと思います。マンション１棟５６世帯だと思うのですけれども賛成をしていないという中で、都市計画手続を進めていいのかということが今問われていると思いますが、いかがでしょうか。","respondent":"中道都市開発課長","answer":"先ほどもちょっとお話のございました、そういった建物の、マンション１部屋の床の面積が減ってしまうといったところも、まずこの段階できちんと皆様にお話ししてください、いわゆる、後でそんなことは聞いてなかったというところをなくすように。","voiceIndex":169,"id":"exchange-053"},{"speaker":"のだて委員","kind":"質問","question":"実際今回、この陳情も出されたというところで、ほかにも、明らかに区議会に陳情を出すほど、やはりやめてほしいと思っている方がほかにも１０名いらっしゃるというふうに聞いております。こうした中でやはり行政が計画を進めていくというのはやめるべきではないかと思いますが、いかがでしょうか。","respondent":"中道都市開発課長","answer":"ですが、実際にここの地区で本当にこれをするのかしないのかというところは、地域の方で主体となって進めていくものになりますので、再開発というまちづくりを選択するのであれば、地域の方が主体となって進める、またはそういった同意の部分につきましては法的な部分。","voiceIndex":171,"id":"exchange-054"},{"speaker":"のだて委員","kind":"質問","question":"そうした中でこの都市計画手続を進めていくことはやめるべきだと、これは強く言っておきたいと思います。しかも、この準備組合の理事長や副理事長になっているというところで、やはり住民の皆さんが望まない形で無理やり開発を進めているという状況になっているのではないかと思うのですが、いかがでしょうか。なぜ、この三井不動産とＮＩＰＰＯがこの事業から降りたのかというところを伺います。","respondent":"中道都市開発課長","answer":"もともと三井不動産またはＮＩＰＰＯが事業協力者としていらっしゃいましたが、民間企業の中での経営判断というところで今回は事業協力者のほうから退いたというふうに聞いております。","voiceIndex":173,"id":"exchange-055"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうしたところを実際成り立たせるように補助金を投入して進めていくということはやめるべきだと思います。先ほど１つお聞きしたところで、会社が理事長、副理事長になって進めていて、住民のマンションなどに住んでいる方々の声がないがしろにされているのではないかというところも伺ったので、お答えいただきたいと思います。","respondent":"中道都市開発課長","answer":"準備組合のほうも、各１件ずつ丁寧な説明をしながら、この今の事業の部分について説明をして回っているという状況です。","voiceIndex":175,"id":"exchange-056"},{"speaker":"のだて委員","kind":"質問・要望","question":"マンションに住んでいる方たちを無視して進めていくつもりはないというのであれば、この声をしっかり受け止めて、話も聞きながら、抜本的な見直しをしていくということが必要だと思いますので、区としてもそのことを準備会の方々にも指導していただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":177,"id":"exchange-057"},{"speaker":"中塚委員","kind":"確認","question":"再度質問します。今のやり取りで、品川区が組合に指導していることについて、平米が変更になる、小さくなるということもきちんと説明するよう、組合に話をしているという説明があったと思いますけれども、これは本当かということが質問と、その区の指導に対して、組合は何と返事をしているのか、そこを確認したいと思います。","respondent":"中道都市開発課長","answer":"今回、都市計画を進めていきたいという目標の中で、地域にこういった計画の概要を説明するという段階で、区としてもこういったいわゆるモデル権利変換というのですけれども、そういったこともきちんと伝えながら。組合のほうも、そうした丁寧な説明というものを了解したです。","voiceIndex":179,"id":"exchange-058"},{"speaker":"中塚委員","kind":"質問","question":"そういう、その後の権利変換計画はずっと後ではないですか。別に私、再開発を擁護するつもりは１ミリもないのですけれども、そういう説明をしているのか改めて伺いたいと思うのです。なぜかというと、こういう条件がそろったら都市計画の手続に入っていいですよと許可を出すのは品川区ですから。ですから、もう１回言うと、何が整ったら都市計画の手続に入ると区は判断するのか、そこを伺います。","respondent":"中道都市開発課長","answer":"そうした中身を見て、これが都市計画として適正であるかどうかを判断して、今後都市計画法１６条、１７条といった都市計画説明会に向けて区としては進めるです。","voiceIndex":182,"id":"exchange-059"},{"speaker":"中塚委員","kind":"確認","question":"それと、何が整ったら都市計画の手続に入るのかということで、つまり適正かどうかを判断するのは区なのです。違いますか、それ伺います。つまり、これは品川区が自らつくった上位計画に合っているかどうか、法律の手続にのっとっているかどうかの確認だけであって、地権者との関係では３分の２以上を超えていれば法律的に問題ないから、区長はいつでもゴーサインを出せるというのが今の仕組みなのです。","respondent":"中道都市開発課長","answer":"企画提案書を踏まえて、そこの都市計画、都市計画事業として見合っているかどうかといった決定は区長がするというものになります。一方で、企画提案書が地域から提出されなければ、こういったまちづくりは区のほうで進めることができないというところも併せてお伝えいたします。","voiceIndex":184,"id":"exchange-060"},{"speaker":"澤田委員","kind":"質問","question":"本日結論を出す、不採択でお願いします。理由としましては、まちづくりを進めていく上で、多くの方の不安をなくすためにも、区としても話合いのサポートをしていると認識したからです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":187,"id":"exchange-061"},{"speaker":"つる委員","kind":"質問・要望","question":"ただ、この間こうした開発関係というのは、答弁でもずっとあるとおり、先ほどの質疑でもありましたけれども、あくまでも当事者間でしっかりと話合いをし、合意形成し、そしてどうしても１００％とか、数字的なところあるわけですが、１００％になればそれが一番いいわけなのですが、なかなかそうにはならない課題も一方ではありながら、まちをつくっていくというところは一方であると思いますが、ただ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":188,"id":"exchange-062"},{"speaker":"木村委員","kind":"質問","question":"本日、結論を出すということで、不採択でお願いいたします。いろいろ先ほども説明いただきましたけれども、内容としてもうほとんど同じで、適正な手続も踏んでいるということで、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":189,"id":"exchange-063"},{"speaker":"のだて委員","kind":"意見","question":"結論を出すということで、採択を主張します。今のまま住み続けたい人もいますし、計画に反対している人もいます。このような状況で都市計画手続に入るべきではないですし、この再開発はやめるべきだと考えますので、採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":190,"id":"exchange-064"},{"speaker":"中塚委員","kind":"質問・要望","question":"結論を出すということと、態度としては採択でお願いします。陳情者の陳情要旨、理由は全くそのとおりだと思います。都市計画の手続に入るべきではありません。ですから、本陳情を採択して、区長に見直しを求めるべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":191,"id":"exchange-065"},{"speaker":"横山委員","kind":"意見","question":"本日、結論を出すで、不採択でお願いします。区としての対応と民間としての対応というものがあると思います。しかるべきタイミングにてそれぞれのお立場、計画等において適切にご対応いただきますようお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":192,"id":"exchange-066"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6747#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":63557,"voices":204}}]);
